  ui_story_1011_10111501_37_dialog_content = "เทวทูตทั้งสี่ ตามข้ามา",
  ui_story_1011_10111501_38_dialog_content = "ค่ะ!",
  ui_story_1011_10111501_39_dialog_content = "<color=#e8d9bb>วึ้ง!</color>",
  ui_story_1011_10111501_40_dialog_content = "ชีพจรลูมินาอีกแล้ว!",
  ui_story_1011_10111501_41_dialog_content = "แต่... พลังงานของแดโมคลีสกำลังลดลงแล้วค่ะ!",
  ui_story_1011_10111501_42_dialog_content = "ดีมาก แล้วพลังของพวกเจ้าล่ะ?",
  ui_story_1011_10111501_43_dialog_content = "เรายังทนไหว... แต่คงได้อีกไม่นานค่ะ!",
  ui_story_1011_10111501_44_dialog_content = "พยายามเข้านะ ทุกคน...",
  ui_story_1011_10111501_45_dialog_content = "หน้าอกของฉัน... กำลังลุกไหม้...",
  ui_story_1011_10111501_46_dialog_content = "...",
  ui_story_1011_10111501_47_dialog_content = "เข้าใจแล้ว",
  ui_story_1011_10111501_48_dialog_content = "เราจะจบเรื่องนี้ให้ได้ นี่จะเป็นครั้งสุดท้ายแล้ว",
  ui_story_1011_10111501_49_dialog_content = "ทุกคน ใช้ลูมินาขัดขวางการส่งพลังงานของแดโมคลีสเดี๋ยวนี้!",
  ui_story_1011_10111501_50_dialog_content = "ทำทุกอย่างเท่าที่ทำได้เพื่อหยุดการทำงานของมัน!",
  ui_story_1011_10111501_51_dialog_content = "ค่ะ!",
  ui_story_1011_10111501_52_dialog_content = "<color=#e8d9bb>วึ้ง!</color>",
  ui_story_1011_10111501_53_dialog_content = "<color=#e8d9bb>วื้ดด...</color>",
  ui_story_1011_10111501_54_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111501_55_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_1011_10111501_56_dialog_content = "เรา... หยุดมันได้แล้วใช่มั้ย...?",
  ui_story_1011_10111501_57_dialog_content = "ทั้งพวกเรา... และมัน... ต่างก็มอดไหม้...",
  ui_story_1011_10111501_58_dialog_content = "...",
  ui_story_1011_10111501_59_dialog_content = "ท่านเจ้าเมือง ทุกอย่างเรียบร้อยแล้วใช่มั้ยคะ?",
  ui_story_1011_10111501_60_dialog_content = "ใช่ ภารกิจของเราลุล่วงแล้ว",
  ui_story_1011_10111501_61_dialog_content = "แต่ว่า...",
  ui_story_1011_10111501_62_dialog_content = "แดโมคลีส...",
  ui_story_1011_10111501_63_dialog_content = "เป้าหมายของเจ้าคืออะไรกันนะ...?",
  ui_story_1011_10111501_64_dialog_content = "<color=#e8d9bb>วึ้ง วึ้ง วึ้ง...</color>",
  ui_story_1011_10111501_65_dialog_content = "หนวกหูชะมัด! เมี้ยว!",
  ui_story_1011_10111501_66_dialog_content = "*สะอื้น* ฉันของีบสบาย ๆ ไม่ได้หรือไง...",
  ui_story_1011_10111501_67_dialog_content = "หืม? ฟิลิชี?",
  ui_story_1011_10111501_68_dialog_content = "นี่เธอหลับในเวลางานอีกแล้วเหรอเนี่ย?",
  ui_story_1011_10111501_69_dialog_content = "พ-พูดอะไรน่ะ คุณวิเวียน? ฉันตื่นเต็มสองตาเลยนะ!",
  ui_story_1011_10111501_70_dialog_content = "ช่างเถอะ... ไว้ฉันจะจัดการกับเธอคราวหน้าก็แล้วกัน",
  ui_story_1011_10111501_71_dialog_content = "แต่เสียงหนวกหูนั่นมันอะไรกันนะ...?",
  ui_story_1011_10111501_72_dialog_content = "<color=#e8d9bb>วึ้ง วึ้ง วึ้ง...</color>",
  ui_story_1011_10111501_73_dialog_content = "เสียงนั่น... น่ารำคาญชะมัด! มันเสียงอะไรกันน่ะ!?",
  ui_story_1011_10111501_74_dialog_content = "นี่! ใครก็ได้!",
  ui_story_1011_10111501_75_dialog_content = "โอ้ ผู้บัญชาการชาโรนา",
  ui_story_1011_10111501_76_dialog_content = "เธอก็เหมือนกันเหรอ...?",
  ui_story_1011_10111501_77_dialog_content = "วิเวียน เธอรู้มั้ยว่าเกิดอะไรขึ้น?",
  ui_story_1011_10111501_78_dialog_content = "ไม่รู้เลย ฉันก็ไม่เคยได้ยินอะไรแบบนี้มาก่อนเหมือนกัน",
  ui_story_1011_10111501_79_dialog_content = "ไม่มีใครรู้อะไรสักอย่าง",
  ui_story_1011_10111501_80_dialog_content = "อย่าบอกนะ ว่าอุตส่าห์รอดมาจากสนามรบได้ แต่จะต้องมาตายเพราะเสียงกวนประสาทนี่ในแกนน่อนน่ะ...",
  ui_story_1011_10111501_81_dialog_content = "ต้องมีอะไรเสียสักอย่างแหละ ฉันจะให้คนไปสืบหาเดี๋ยวนี้เลย!",
  ui_story_1011_10111501_82_dialog_content = "<color=#e8d9bb>วึ้ง วึ้ง วึ้ง...</color>",
  ui_story_1011_10111501_83_dialog_content = "สถานการณ์ในตอนนี้ก็คือ ทุกคนในแกนน่อนได้ยินเสียงนั่น",
  ui_story_1011_10111501_84_dialog_content = "อาฮะ...",
  ui_story_1011_10111501_85_dialog_content = "ทีมซ่อมบำรุงบอกว่าเสียงนั่นมาจากอุปกรณ์โบราณบางอย่างในกำแพงเมือง",
  ui_story_1011_10111501_86_dialog_content = "เราเคยเช็กและยืนยันไปแล้วว่ามันเสีย... ไม่มีใครคิดว่ามันจะส่งเสียงแบบนั้นออกมาได้",
  ui_story_1011_10111501_87_dialog_content = "อาฮะ...",
  ui_story_1011_10111501_88_dialog_content = "กรอนรู นี่เธอฟังอยู่รึเปล่าเนี่ย?",
  ui_story_1011_10111501_89_dialog_content = "อืม... ฉันฟังอยู่",
  ui_story_1011_10111501_90_dialog_content = "หมายถึงเครื่องนั่น... ใช่ เครื่องนั่นใช่มั้ย?",
  ui_story_1011_10111501_91_dialog_content = "นี่เธอไม่ฟังเลยนี่นา!",
  ui_story_1011_10111501_92_dialog_content = "วางหนังสือลงได้แล้ว! นี่เรื่องสำคัญนะ!",
  ui_story_1011_10111501_93_dialog_content = "เสียงนั่นทำให้คนทั้งเมืองตื่นตระหนกกันหมดแล้ว!",
  ui_story_1011_10111501_94_dialog_content = "แล้วทีมวิทยาการของเราก็ทำอะไรไม่ได้ด้วย เธอช่วย...",
  ui_story_1011_10111501_95_dialog_content = "ชู่ว!",
  ui_story_1011_10111501_96_dialog_content = "!?",
  ui_story_1011_10111501_97_dialog_content = "<color=#e8d9bb>วึ้ง วึ้ง วึ้ง...</color>",
  ui_story_1011_10111501_98_dialog_content = "อ๋อ เข้าใจแล้ว",
  ui_story_1011_10111501_99_dialog_content = "โอเค คราวนี้ฉันเข้าใจแล้ว",
  ui_story_1011_10111501_100_dialog_content = "หืม? เข้าใจ? เข้าใจอะไรน่ะ?",
  ui_story_1011_10111501_101_dialog_content = "อย่าหนีเพราะมันน่ารำคาญสิ... ตั้งใจฟังให้ดี ๆ!",
  ui_story_1011_10111501_102_dialog_content = "นี่ไม่ใช่แค่เสียงรบกวน มันแฝงข้อความบางอย่างมาด้วย...",
  ui_story_1011_10111501_103_dialog_content = "ข้อความ?",
  ui_story_1011_10111501_104_dialog_content = "ใช่ นี่คือภาษาโบราณที่เก่าแก่มาก ๆ",
  ui_story_1011_10111501_105_dialog_content = "ขอเช็กก่อนนะ... หน้า 302... หน้า 564...",
  ui_story_1011_10111501_106_dialog_content = "นี่ไง!",
  ui_story_1011_10111501_107_dialog_content = "การตีความภาษาโบราณส่วนใหญ่มันก็เป็นการคาดเดาอย่างมีเหตุผล เพราะงั้นฉันไม่รับประมาณว่ามันจะแม่นยำแค่ไหนนะ...",
  ui_story_1011_10111501_108_dialog_content = "แต่ฉันคิดว่ามันกำลังบอกเราว่า...",
  ui_story_1011_10111501_109_dialog_content = "<color=#FFB400>\"รีบหนีไปซ่อน เดี๋ยวนี้\"</color>",
  ui_story_1011_10111501_110_dialog_content = "ฉันมาแล้ว บร็อค",
  ui_story_1011_10111501_111_dialog_content = "ฮึ่ม! เตรียมตัวแพ้รึยัง?",
  ui_story_1011_10111501_112_dialog_content = "นั่นควรเป็นคำพูดของฉันมากกว่านะ คุณนายพลขี้แพ้!",
  ui_story_1011_10111501_113_dialog_content = "พอกันทีกับฉายาเฮงซวยนี่!",
  ui_story_1011_10111501_114_dialog_content = "วันนี้ล่ะ ทุกคนจะได้เห็นฉันเอาชนะคุณซินซา อย่างยุติธรรมขาวสะอาด!",
  ui_story_1011_10111501_115_dialog_content = "โฮ่! ฉันล่ะชอบความมั่นใจแบบนั้นจริง ๆ",
  ui_story_1011_10111501_116_dialog_content = "แต่... ทุกคนก็อยู่นี่ด้วยรึ?",
  ui_story_1011_10111501_117_dialog_content = "ใช่ ผมเรียกทุกคนที่เรดีเซล เวรนช์ มาดูเองแหละ",
  ui_story_1011_10111501_118_dialog_content = "ทำไมล่ะ? หรือว่ากลัวการสู้กับผมต่อหน้าทุกคนหรือไง?",
  ui_story_1011_10111501_119_dialog_content = "ไม่ใช่เรื่องนั้นเฟ้ย คือฉันงง ๆ ว่า ไหนล่ะทุกคนที่นายบอก?",
  ui_story_1011_10111501_120_dialog_content = "ไม่เห็นจะมีใครเลย",
  ui_story_1011_10111501_121_dialog_content = "เฮ้! ทุกคน ออกมาสิ!",
  ui_story_1011_10111501_122_dialog_content = "การดวลกำลังจะเริ่มแล้วนะ!",
  ui_story_1011_10111501_123_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1011_10111501_124_dialog_content = "นี่!",
  ui_story_1011_10111501_125_dialog_content = "ฉันควรปรบมือให้นายดีมั้ยเนี่ย?",
  ui_story_1011_10111501_126_dialog_content = "สู้ ๆ สู้ ๆ...",
  ui_story_1011_10111501_127_dialog_content = "คราวนี้พี่จะต้องชนะแน่ ๆ!",
