  ui_story_1011_10111501_134_dialog_content = "อยากเห็นหมอนั่นร่วงลงไปตรงไหนดีล่ะ?",
  ui_story_1011_10111501_135_dialog_content = "เอ่อ... คุณซินซา อย่าสู้กันบนเลพิดอสได้มั้ย?",
  ui_story_1011_10111501_136_dialog_content = "ช่างหัวคนดูสิ... ที่จริงฉันก็ไม่ต้องการคนดูอยู่แล้ว!",
  ui_story_1011_10111501_137_dialog_content = "เดี๋ยวค่อยเล่าเรื่องชัยชนะอันไร้ที่ติให้คนอื่นฟังทีหลังก็ได้!",
  ui_story_1011_10111501_138_dialog_content = "ฮ่าฮ่า! เข้ามาเลย!",
  ui_story_1011_10111501_139_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_1011_10111501_140_dialog_content = "หวาาาา!",
  ui_story_1011_10111501_141_dialog_content = "อะไรเนี่ย?",
  ui_story_1011_10111501_142_dialog_content = "บ็อปเปอร์ อย่าสตาร์ทเลพิดอสโดยพลการสิ!",
  ui_story_1011_10111501_143_dialog_content = "บอส ฉันยังไม่ได้ไปไหนเลย...",
  ui_story_1011_10111501_144_dialog_content = "คนที่อยู่บนเลพิดอสมีแต่คุณคนเดียวนะ",
  ui_story_1011_10111501_145_dialog_content = "เอ๊ะ? แล้วเมื่อกี้มันอะไรหว่า?",
  ui_story_1011_10111501_146_dialog_content = "นี่ คุณซินซา คิดจะหนีหรือไง?",
  ui_story_1011_10111501_147_dialog_content = "หุบปากน่า! เลพิดอสมันขยับเองต่างหา⁠—",
  ui_story_1011_10111501_148_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_1011_10111501_149_dialog_content = "หวาาาาาา! ทำไมมันเร็วขึ้นเรื่อย ๆ ล่ะเนี่ย!",
  ui_story_1011_10111501_150_dialog_content = "โว่ว! นี่มันน่าตื่นเต้นกว่าที่คิดไว้ซะอีกนะเนี่ย",
  ui_story_1011_10111501_151_dialog_content = "พี่ชายหนีการต่อสู้... ทำไมพี่ขี้ขลาดอย่างนี้ล่ะ",
  ui_story_1011_10111501_152_dialog_content = "ฉันไม่ได้ทำนะ! สาบานได้! เป็นฝีมือเลพิดอสต่างหากล่ะ!",
  ui_story_1011_10111501_153_dialog_content = "เลิกยืนดูได้แล้ว! มาช่วยกันหน่อยเซ่!",
  ui_story_1011_10111501_154_dialog_content = "เฮ้ยย!",
  ui_story_1011_10111501_155_dialog_content = "<color=#e8d9bb>พั่บ พั่บ... พั่บ พั่บ...</color>",
  ui_story_1011_10111501_156_dialog_content = "สวัสดี ฉันมีจดหมายด่วนถึงคุณอีสต์วาน ช่วยเซ็นรับด้วย",
  ui_story_1011_10111501_157_dialog_content = "เดี๋ยวฉันจัดการเอง",
  ui_story_1011_10111501_158_dialog_content = "เอ๊ะ ใครเป็นคนส่งน่ะ?",
  ui_story_1011_10111501_159_dialog_content = "ไม่เห็นเขียนไว้บนซองเลย",
  ui_story_1011_10111501_160_dialog_content = "โอ๊ะ คืออย่างนี้นะ",
  ui_story_1011_10111501_161_dialog_content = "จดหมายด่วนถึงคุณอีสต์วานทุกฉบับจะต้องไม่มีระบุชื่อผู้ส่ง",
  ui_story_1011_10111501_162_dialog_content = "นี่เป็นคำขอส่วนตัวจากคุณอีสต์วานเองน่ะ",
  ui_story_1011_10111501_163_dialog_content = "โอ๊ะ งั้นเหรอ",
  ui_story_1011_10111501_164_dialog_content = "ขอบคุณนะ",
  ui_story_1011_10111501_165_dialog_content = "ขอบคุณที่ใช้บริการสหภาพผู้ส่งสาร แล้วเจอกัน!",
  ui_story_1011_10111501_166_dialog_content = "หวัดดี ฉันมีจดหมายด่วนถึงคุณอีสต์วาน ช่วยเช็นยับด้วย",
  ui_story_1011_10111501_167_dialog_content = "ได้สิ ยังมีอีกเหรอเนี่ย?",
  ui_story_1011_10111501_168_dialog_content = "แย้วก็... ที่ซองไม่มีชื่อผู้ฉ่งก็เพราะว่า...",
