  ui_story_1011_10111501_170_dialog_content = "ช่าย!",
  ui_story_1011_10111501_171_dialog_content = "เธอฝากไว้กับฉันก็ได้ ขอบคุณนะ",
  ui_story_1011_10111501_172_dialog_content = "ไม่มีปัญหา! แล้วเจอกันค่า!",
  ui_story_1011_10111501_173_dialog_content = "หวาาาา! สายแล้ว สายแล้ว",
  ui_story_1011_10111501_174_dialog_content = "หวังว่าจะไม่โดนตัดเงินเดือนนะ",
  ui_story_1011_10111501_175_dialog_content = "อ้าว คุณโดฟก็มาด้วยเหยอ?",
  ui_story_1011_10111501_176_dialog_content = "โย่ ทวีตตี้! เธอ...",
  ui_story_1011_10111501_177_dialog_content = "ไว้คุยกันทีหลังนะ แค่นี้ฉันก็สายมากพอแล้ว",
  ui_story_1011_10111501_178_dialog_content = "สวัสดี ฉันมีจดหมายด่วนถึงคุณอีสต์วาน ช่วยเซ็นรับด้วย",
  ui_story_1011_10111501_179_dialog_content = "พ่อคะ สหภาพผู้ส่งสารมีจดหมายด่วนมาถึงพ่อค่ะ",
  ui_story_1011_10111501_180_dialog_content = "จดหมายด่วนงั้นรึ? ไหนดูหน่อยซิ",
