  ui_story_1012_10120401_35_dialog_content = "ถอดรหัสการควบคุมการเข้าถึง Neural Aux จะไม่สามารถรับคำสั่งอื่นๆ ได้ในระหว่างกระบวนการ โปรดรอ.",
  ui_story_1012_10120401_36_dialog_content = "1%... 2%... 5%...",
