  ui_story_1012_10120401_69_dialog_content = "จะเป็นอย่างไร คาเลสไทต์?",
  ui_story_1012_10120401_70_dialog_content = "คุณจะดิ้นรนต่อไปอย่างไร้ประโยชน์เหมือนอิลลูมิแนนที่บ้าบิ่นที่นี่หรือไม่?",
  ui_story_1012_10120401_71_dialog_content = "...",
  ui_story_1012_10120401_72_option_content = "ฉันไม่เชื่อแก",
  ui_story_1012_10120401_73_dialog_content = "โอ้?",
