  ui_story_1012_10120502_62_dialog_content = "หัวอิคลิพไซท์มันทำจากเหล็กหรือไง?!",
  ui_story_1012_10120502_63_dialog_content = "ฮ่า! ยัยฟอร์เซคินชอบด่าว่าฉันหัวแข็ง แต่สุดท้ายตัวเองก็ดื้อไม่เบา!",
  ui_story_1012_10120502_64_dialog_content = "กลับไปเถอะน่า พวกแกน่ะมาถึงทางตันแล้ว!",
  ui_story_1012_10120502_65_dialog_content = "อีกไม่นานพวกมันจะพังทลายหากยังเป็นเช่นนี้ต่อไป",
  ui_story_1012_10120502_66_dialog_content = "PlayerName รีบเปิดระบบคอร์ดลิงก์แล้วรักษาไวซ์กันเถอะ",
  ui_story_1012_10120502_67_dialog_content = "ถ้าไวซ์ตื่นขึ้นมา เราก็จะฝ่าออกไปจากที่นี่ด้วยกัน เรายังพอมีหวัง!",
  ui_story_1012_10120502_68_dialog_content = "สมองกลผู้ช่วย ช่วยฉันเปิดระบบคอร์ดลิงก์ที!",
  ui_story_1012_10120502_69_dialog_content = "เปิดใช้งานระบบคอร์ดลิงก์!",
  ui_story_1012_10120502_70_dialog_content = "ค้นหาบันทึกการทดลองสำหรับข้อมูลเกี่ยวกับผลข้างเคียงและผลลัพธ์ของ Chord Link!",
  ui_story_1012_10120502_71_dialog_content = "กำลังค้นหา... เกิดข้อผิดพลาด!",
  ui_story_1012_10120502_72_dialog_content = "ฉันไม่สามารถเรียกคืนบันทึกการทดสอบได้!",
  ui_story_1012_10120502_73_dialog_content = "หา?!",
  ui_story_1012_10120502_74_dialog_content = "คุณไม่ได้บอกว่าพวกเขาทั้งหมดถูกเก็บไว้ที่นี่?",
  ui_story_1012_10120502_75_dialog_content = "ทำไมถึงดึงมาไม่ได้ล่ะ?!",
  ui_story_1012_10120502_76_dialog_content = "ฉันถูกตัดการเชื่อมต่อจาก Chord Zone เป็นเวลานาน ดังนั้นฉันจึงไม่คุ้นเคยกับเรื่องที่เกี่ยวข้องกับมัน",
  ui_story_1012_10120502_77_dialog_content = "สมองกลตรวจพบว่ามีการลบบันทึกออกไปจากคลังข้อมูลของคอร์ดโซนด้วย",
  ui_story_1012_10120502_78_dialog_content = "ข้อมูลเหล่านี้สูญหายไปเป็นเวลานานแล้ว และไม่สามารถกู้คืนได้",
  ui_story_1012_10120502_79_dialog_content = "แล้ว...",
  ui_story_1012_10120502_80_dialog_content = "พวกคุณวางแผนจะใช้อุปกรณ์ที่ยังไม่ทดลองกับ Vice เหรอ?",
  ui_story_1012_10120502_81_dialog_content = "ไม่ ฉันจะไปหาบันทึกการทดลองก่อน แต่พวกมันถูกล้างไปหมดแล้ว...",
  ui_story_1012_10120502_82_dialog_content = "บาร์ตัน คาร์ลีน กรุณารอสักครู่",
  ui_story_1012_10120502_83_dialog_content = "ฉันจะยืนยันว่า Chord Link ทำอะไรด้วยตัวฉันเอง",
  ui_story_1012_10120502_84_dialog_content = "เดี๋ยวก่อน คุณไม่ใช่ชาวออโรเรียน เราไม่รู้ว่าจะเกิดอะไรขึ้นถ้าคุณใช้มัน",
  ui_story_1012_10120502_85_dialog_content = "แต่ฉันจะให้ไวซ์มาเสี่ยงไม่ได้",
  ui_story_1012_10120502_86_dialog_content = "Forsakin กำลังจะบุกเข้ามาในไม่ช้า สู้กันสองคนก็ได้...",
  ui_story_1012_10120502_87_dialog_content = "ในขณะเดียวกัน ฉันเป็น Caelestite ที่ไม่สามารถใช้ Luminatics ได้ ฉันเหมาะกับการทดลองมากกว่า!",
  ui_story_1012_10120502_88_dialog_content = "อย่าหนีนะ!",
  ui_story_1012_10120502_89_dialog_content = "อย่าขวางผมนะ!",
  ui_story_1012_10120502_90_dialog_content = "ใจเย็นก่อนเถอะน่า!",
  ui_story_1012_10120502_91_dialog_content = "คุณรู้หรือไม่ว่าสิ่งนั้นสามารถทำอะไรได้บ้าง?",
  ui_story_1012_10120502_92_dialog_content = "Chord Link สามารถรักษาบาดแผลและปรับเปลี่ยนส่วนต่าง ๆ ของร่างกายของ Aurorian เพื่อปลดปล่อยศักยภาพที่แท้จริงของพวกมัน",
  ui_story_1012_10120502_93_dialog_content = "รักษาอาการบาดเจ็บได้งั้นรึ?",
  ui_story_1012_10120502_94_dialog_content = "งั้นฉันจะลองเอง!",
  ui_story_1012_10120502_95_dialog_content = "แต่ฉันไม่รู้ด้วยซ้ำว่ามันมีผลข้างเคียงอะไร อัตราความสำเร็จเป็นอย่างไร หรือมันสามารถฆ่าคุณได้หรือเปล่า!",
  ui_story_1012_10120502_96_dialog_content = "ถ้างั้นก็ยิ่งต้องเป็นฉันนี่แหละ!",
  ui_story_1012_10120502_97_dialog_content = "คุณต้องมีวิชาทดสอบใช่ไหม",
  ui_story_1012_10120502_98_dialog_content = "ฉันบาดเจ็บสาหัส ฉันทำอะไรไม่ได้มากถ้าต้องเผชิญหน้ากับ Forsakin ในตอนนี้",
  ui_story_1012_10120502_99_dialog_content = "ถ้าคุณอยู่ข้างนอกและประสานงานกับ Carleen พวกคุณจะสามารถซื้อเวลาได้มากขึ้น",
  ui_story_1012_10120502_100_dialog_content = "เพราะงั้นให้ฉันลองเครื่องนั่นเถอะ",
  ui_story_1012_10120502_101_dialog_content = "ถ้าเครื่องนั้นสามารถรักษาฉันได้ ฉันจะต้องประหลาดใจรอ Forsakin",
  ui_story_1012_10120502_102_dialog_content = "จากนั้นนายก็ใช้เครื่องนั่นช่วยไวซ์",
