  ui_story_1012_10120601_31_dialog_content = "ทำซ้ำ! ตรวจพบผู้บุกรุก 30 ฟุตข้างหน้า...",
  ui_story_1012_10120601_32_dialog_content = "พวกเขาหยุดหรือยัง",
  ui_story_1012_10120601_33_dialog_content = "M-อาจจะ?",
  ui_story_1012_10120601_34_dialog_content = "<color=#e8d9bb><size=45>เปรี้ยง!!!</size></color>",
  ui_story_1012_10120601_35_dialog_content = "“ผู้บุกรุก”?",
  ui_story_1012_10120601_36_dialog_content = "ฉันทำสิ่งเดียวกับที่คุณทำ",
  ui_story_1012_10120601_37_dialog_content = "ข้อแตกต่างเพียงอย่างเดียวคือใครเป็นคนทำก่อน",
  ui_story_1012_10120601_38_dialog_content = "... หือ?",
  ui_story_1012_10120601_39_dialog_content = "ดังนั้นจึงมีอุปกรณ์ปลุกระดมดังกล่าวฝังอยู่ที่ด้านล่างของสุสานแห่งนี้",
  ui_story_1012_10120601_40_dialog_content = "ดูเหมือนว่าเมื่อพูดถึงการฆ่า Barton คุณนำหน้าฉันไปหนึ่งก้าว",
  ui_story_1012_10120601_41_dialog_content = "เลิกพล่ามไร้สาระได้แล้ว!",
  ui_story_1012_10120601_42_dialog_content = "PlayerName ไม่ต้องไปเสียเวลากับเธอหรอก!",
  ui_story_1012_10120601_43_dialog_content = "เธอไม่ได้รับอนุญาตอีกต่อไป! รองยังอยู่ที่นั่น!",
  ui_story_1012_10120601_44_dialog_content = "มีหลายสิ่งหลายอย่างในชีวิตที่ไม่เป็นไปตามที่คุณต้องการ",
  ui_story_1012_10120601_45_dialog_content = "PlayerNameฉันประหลาดใจที่คุณยังต้องการให้ฉันบอกคุณเมื่อคุณเป็น Caelestite ที่ได้ผจญภัยไปไกลกว่า Colossus ของคุณ",
  ui_story_1012_10120601_46_dialog_content = "ฉันแน่ใจว่าคุณไม่ต้องการให้ฉันอธิบายเพิ่มเติมเกี่ยวกับสิ่งที่เกิดขึ้นกับ Caeleste คนสุดท้ายที่ต่อต้านฉัน",
  ui_story_1012_10120601_47_dialog_content = "แก...!",
  ui_story_1012_10120601_48_dialog_content = "(ภาษาอิคลิพส์) โจมตี",
  ui_story_1012_10120601_49_dialog_content = "(สุริยุปราคา) ใช่!",
  ui_story_1012_10120702_1_dialog_content = "กรร!",
  ui_story_1012_10120702_2_dialog_content = "ฮ่าห์!",
  ui_story_1012_10120702_3_dialog_content = "กรร...",
  ui_story_1012_10120702_4_dialog_content = "ข้างหลังคุณ! คาร์ลีน!",
  ui_story_1012_10120702_5_dialog_content = "หา...?!",
  ui_story_1012_10120702_6_dialog_content = "กรรรร!!!",
  ui_story_1012_10120702_7_dialog_content = "โอย...",
  ui_story_1012_10120702_8_dialog_content = "(ไม่ได้ผล Forsakin นำ Eclipsites มามากเกินไป)",
  ui_story_1012_10120702_9_dialog_content = "(นี่อาจมีประสิทธิภาพมากกว่าการเชื่อมโยงกับจิตสำนึกของ Carleen!)",
  ui_story_1012_10120702_10_dialog_content = "หา?!",
  ui_story_1012_10120702_11_dialog_content = "ช่างน่าประหลาดใจ. คุณเรียนรู้การใช้อาวุธเมื่อใด PlayerName?",
  ui_story_1012_10120702_12_dialog_content = "อืม... มันดูเหมือนปืน Caelesite แน่นอน ถือได้ว่าเป็นโบราณวัตถุจริงๆ",
  ui_story_1012_10120702_13_dialog_content = "นี่เป็นรายการที่ยอดเยี่ยม",
  ui_story_1012_10120702_14_dialog_content = "ฉันขอรับไว้ก็แล้วกัน ขอบคุณนะ PlayerName",
  ui_story_1012_10120702_15_dialog_content = "หนอย! เอาคืนมานะ!",
  ui_story_1012_10120702_16_dialog_content = "กรรรร!!!",
  ui_story_1012_10120702_17_dialog_content = "หยุดพวกมันไว้ PlayerName! เราจะให้มันเข้ามาไม่ได้นะ!",
  ui_story_1012_10120702_18_dialog_content = "นี่ไม่ใช่เหตุผลที่กระบวนการโฮโมโฟนิกส์ล้มเหลว!",
  ui_story_1012_10120702_19_dialog_content = "บุปผาน้ำแข็ง! จงแผ่กว้าง!",
  ui_story_1012_10120702_20_dialog_content = "<size=45>กรรรร!</size>",
  ui_story_1012_10120702_21_dialog_content = "ค-คาร์ลีน!",
  ui_story_1012_10120702_22_option_content = "บังคับเชื่อมกระแสจิต!",
  ui_story_1012_10120702_23_dialog_content = "คาร์ลีน... ตอบฉันที... ได้โปรดเถอะ!",
  ui_story_1012_10120702_24_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120702_25_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120702_26_dialog_content = "(Eclipsian) ฆ่า Barton และ Vice อย่าทำให้อุปกรณ์เสียหาย",
  ui_story_1012_10120702_27_dialog_content = "(ภาษาอิคลิพส์) รับทราบ",
  ui_story_1012_10120702_28_dialog_content = "<size=50><anim type=Shake>กรร—</anim></size>",
  ui_story_1012_10120702_29_dialog_content = "(ทำไม... ทำไมสิ่งนี้ถึงเกิดขึ้น...?)",
  ui_story_1012_10120702_30_dialog_content = "(ความรู้สึกสิ้นหวังนี้กลับมาอีกครั้ง... ฉันประสบมันอีกครั้ง...)",
  ui_story_1012_10120702_31_dialog_content = "(ถ้าฉันสามารถใช้ Luminatics ได้ สิ่งต่างๆ คงจะแตกต่างออกไป)",
  ui_story_1012_10120702_32_dialog_content = "(ไวซ์ คาร์ลีน แล้วก็...)",
  ui_story_1012_10120702_33_dialog_content = "(พวกเขา...)",
  ui_story_1012_10120702_34_dialog_content = "ช่วยด้วย! ใครก็ได้ช่วยฉันที!",
  ui_story_1012_10120702_35_dialog_content = "อย่าเข้ามานะ ฉันจะสู้กับพวกแกเอง!",
  ui_story_1012_10120702_36_dialog_content = "ฮือ... แงง... แงงงง...",
  ui_story_1012_10120702_37_dialog_content = "เปลวเพลิงของการต่อสู้ แล้วก็พวกอิคลิพไซท์... ลืมตาขึ้นมาก็ต้อนรับกันแบบนี้เลยเรอะ?",
  ui_story_1012_10120702_38_dialog_content = "(หา?!)",
  ui_story_1012_10120702_39_dialog_content = "อะไรจะดีไปกว่านี้?!",
  ui_story_1012_10120702_40_dialog_content = "ฉันแทบจะอดใจไม่ไหว พลังนี้รู้สึกเหมือนจะพุ่งออกมาได้ทุกเมื่อ!",
  ui_story_1012_10120702_41_dialog_content = "และอะไรจะดีไปกว่าการฝึกฝนการต่อสู้อย่างทันท่วงที!",
  ui_story_1012_10120702_42_dialog_content = "บาร์ตัน! คุณ... คุณหายดีแล้ว!",
  ui_story_1012_10120702_43_dialog_content = "อ้าว PlayerName... เป็นอะไรไปน่ะ ไอ้หนู?",
  ui_story_1012_10120702_44_dialog_content = "ปาดน้ำตาออกจากหน้า อย่าทำหน้าบูด!",
  ui_story_1012_10120702_45_dialog_content = "แสดงความกล้าให้ฉันเห็นหน่อย!",
  ui_story_1012_10120702_46_dialog_content = "ด-ได้ครับ!",
  ui_story_1012_10120702_47_dialog_content = "มาสิ ฉันจะสอนนายเองว่าสนามรบที่แท้จริงมันเป็นยังไง",
  ui_story_1012_10120702_48_dialog_content = "หอคอยนี้เป็นของคุณ คุณจะปล่อยให้ตกอยู่ในเงื้อมมือของ Eclipse ไม่ได้!",
  ui_story_1012_10120702_49_dialog_content = "(Eclipsian) ช่างน่าประหลาดใจจริงๆ เทคโนโลยี Caelesite โบราณนั้นล้ำหน้ามาก",
  ui_story_1012_10120702_50_dialog_content = "(Eclipsian) สิ่งนี้น่าตื่นเต้นอย่างไม่น่าเชื่อ การไล่ตามมันเป็นการตัดสินใจที่ถูกต้อง",
  ui_story_1012_10120702_51_dialog_content = "(ภาษาอิคลิพส์) ช่างชาญฉลาดยิ่งนัก ท่านฟอร์เซคิน",
  ui_story_1012_10120702_52_dialog_content = "(สุริยุปราคา) คุณกำลังทำอะไร? ไปจับเขา แต่อย่าฆ่าเขา! ฉันต้องการให้เขามีชีวิตอยู่",
  ui_story_1012_10120702_53_dialog_content = "(สุริยุปราคา) ใช่—",
  ui_story_1012_10120702_54_dialog_content = "<color=#e8d9bb><size=45>ตูม!</size></color>",
  ui_story_1012_10120702_55_dialog_content = "\"ไม่ได้เจอกันนานเลยนะ\" ฟอร์เซคิน",
  ui_story_1012_10120702_56_dialog_content = "อุตส่าห์ให้เวลาขนาดนี้ ทำไมลูกน้องแกถึงห่วยลงล่ะเนี่ย",
  ui_story_1012_10120702_57_dialog_content = "สกรูคุณ",
  ui_story_1012_10120702_58_dialog_content = "(ภาษาอิคลิพส์) ทุกตัว! โจมตี!",
  ui_story_1012_10120702_59_dialog_content = "กรรรร!!!",
  ui_story_1012_10120702_60_dialog_content = "พยัคฆ์ดำจู่โจม!",
  ui_story_1012_10120702_61_dialog_content = "PlayerName? บาร์ตัน?!",
  ui_story_1012_10120702_62_dialog_content = "แต่นั่นต้องหมายความว่า... Chord Link สำเร็จ!",
  ui_story_1012_10120702_63_dialog_content = "ฮ่าฮ่าฮ่า! ใช่แล้ว!",
  ui_story_1012_10120702_64_dialog_content = "เร็วเข้าสิ ไปรักษาไวซ์ได้แล้ว ทีมพวกนายต้องการเธอไม่ใช่หรือไง?",
  ui_story_1012_10120702_65_dialog_content = "ส่วนนี่...เอาไว้ผม",
  ui_story_1012_10120702_66_dialog_content = "...",
  ui_story_1012_10120702_67_dialog_content = "(ภาษาอิคลิพส์) ถอยก่อน เราจะไปรวมกลุ่มกับทัพหลักของอิคลิพส์!",
  ui_story_1012_10120702_68_dialog_content = "(ภาษาอิคลิพส์) ร-รับทราบ",
  ui_story_1012_10120702_69_dialog_content = "หยุดอยู่ตรงนั้น ไอ้บ้า!",
  ui_story_1012_10120702_70_dialog_content = "ไอ้พวกทุเรศเอ๊ย!",
  ui_story_1012_10120702_71_dialog_content = "เธอไม่เป็นไรนะ คาร์ลีน? เมื่อกี้เกือบแย่แล้ว เธอปลอดภัยดีรึเปล่า...?",
  ui_story_1012_10120702_72_dialog_content = "ฉันสบายดี. ไม่มีเวลาให้เสียเปล่า PlayerName...",
  ui_story_1012_10120702_73_dialog_content = "เราต้องช่วยไวซ์เดี๋ยวนี้!",
  ui_story_1012_10120702_74_dialog_content = "คุณถูก. มาทำโฮโมโฟนิกส์กันเถอะ",
  ui_story_1012_10120702_75_dialog_content = "(ฉันหวังดีกับเธอ Chord Link.)",
  ui_story_1012_10120702_76_dialog_content = "(โปรดตื่นเถิดรอง...)",
  ui_story_1012_10120702_77_dialog_content = "<color=#e8d9bb>คำเตือนจากระบบ: ระบบคอร์ดลิงก์ทำงานแล้ว...</color>",
  ui_story_1012_10120801_1_dialog_content = "<color=#e8d9bb>การแจ้งเตือนระบบ: Chord Link เปิดใช้งานแล้ว... อย่าขัดจังหวะกระบวนการโฮโมโฟนิกส์...</color>",
  ui_story_1012_10120801_2_dialog_content = "...",
  ui_story_1012_10120801_3_dialog_content = "...",
  ui_story_1012_10120801_4_dialog_content = "นี่มันทำงานมาเป็นชาติแล้วนะ! อะไรกันเนี่ย?",
  ui_story_1012_10120801_5_dialog_content = "ใจเย็นก่อนเถอะ PlayerName ให้เวลาไวซ์หน่อยสิ",
  ui_story_1012_10120801_6_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_1012_10120801_7_dialog_content = "ทั้งสองวิธี กระบวนการไม่ได้ดำเนินไปนานไปหน่อยหรือ?!",
  ui_story_1012_10120801_8_dialog_content = "พอคิดดูแล้ว... Barton ดูเหมือนจะตื่นขึ้นในเวลาไม่นาน",
  ui_story_1012_10120801_9_dialog_content = "เอาไงดีล่ะ PlayerName?",
  ui_story_1012_10120801_10_dialog_content = "(คาร์ลีน...)",
  ui_story_1012_10120801_11_dialog_content = "(ฉันควรตั้งสติไว้)",
  ui_story_1012_10120801_12_dialog_content = "เราทำตามคำสั่ง Chord Link ไปยังตัวอักษรแล้วใช่ไหม? เราวางรองไว้ตามที่ระบุไว้",
  ui_story_1012_10120801_13_dialog_content = "เราทำอย่างที่บาร์ตันทำ",
  ui_story_1012_10120801_14_dialog_content = "เราไม่ได้รับการแจ้งเตือนความผิดปกติใดๆ จาก Chord Link หรือ Neural Aux",
  ui_story_1012_10120801_15_dialog_content = "นั่นคือสิ่งที่ทำให้ฉันคิดว่าบางทีปัญหาก็คือ...",
  ui_story_1012_10120801_16_option_content = "สถานะไฮเบอร์เนตของ Vice",
  ui_story_1012_10120801_17_dialog_content = "... งั้นเหรอ มันก็เป็นไปได้อย่างเดียวน่ะนะ",
  ui_story_1012_10120801_18_dialog_content = "พวกเขาทั้งคู่ได้รับบาดเจ็บ แต่นายพลอิลลูมินาไม่ได้หมดสติ",
  ui_story_1012_10120801_19_dialog_content = "ดังนั้นแม้จะได้รับบาดเจ็บสาหัส เขาก็ตื่นขึ้นมาด้วยร่างกายที่แข็งแรงขึ้น",
  ui_story_1012_10120801_20_option_content = "Forsakin กำลังทำอยู่",
  ui_story_1012_10120801_21_dialog_content = "จริงหรือ Forsakin ทำอะไรได้บ้าง...?",
  ui_story_1012_10120801_22_dialog_content = "แต่... Eclipsites ของ Forsakin ในตอนนี้ไม่ได้อยู่ใกล้ Chord Link เลย...",
  ui_story_1012_10120801_23_dialog_content = "นายพลอิลลูมินากำจัดพวกมันทันที",
  ui_story_1012_10120801_24_dialog_content = "สถานะไฮเบอร์เนตเป็นเพียงเหตุผลเชิงตรรกะเท่านั้น",
  ui_story_1012_10120801_25_dialog_content = "จริงด้วย นึกถึงข้อมูลที่เราเจอในระบบวงแหวนสิ...",
  ui_story_1012_10120801_26_dialog_content = "ตัวทดลอง... ฟื้นตัวจากสถานะ \"สูญเสียการรับรู้\" ไม่สำเร็จ... / ร่างกาย... / สัญญาณชีพหายไป",
  ui_story_1012_10120801_27_dialog_content = "ตัวทดลอง... ฟื้นตัวจากสถานะ \"สูญเสียการรับรู้\" ไม่สำเร็จ... / เกิดปรากฏการณ์... / สัญญาณชีพ...",
  ui_story_1012_10120801_28_dialog_content = "ตัวทดลอง... ฟื้นตัวจากสถานะ \"สูญเสียการรับรู้\" ไม่สำเร็จ... / ในการทดลอง...",
  ui_story_1012_10120801_29_dialog_content = "เคเลสไทต์ที่โดนทดลองมีบางสิ่งเหมือน ๆ กัน นั่นก็คือ",
  ui_story_1012_10120801_30_dialog_content = "พวกเขาสูญเสียการรับรู้",
  ui_story_1012_10120801_31_dialog_content = "แต่ทำไมล่ะ? ทำไมถึงเป็นแบบนี้?",
  ui_story_1012_10120801_32_dialog_content = "(พวกเขาถูกกำหนดให้ร่วมชะตากรรมที่ไม่ฟื้นจากการจำศีลหรือไม่?)",
  ui_story_1012_10120801_33_dialog_content = "(ถ้าเป็นอย่างนั้น... ไวซ์!)",
  ui_story_1012_10120801_34_dialog_content = "PlayerName...",
  ui_story_1012_10120801_35_dialog_content = "PlayerName?",
  ui_story_1012_10120801_36_dialog_content = "ค-คุณไรน์ฮาร์ต?!",
  ui_story_1012_10120801_37_dialog_content = "อย่างน้อยสัญญาณของคุณก็แรงพอ",
  ui_story_1012_10120801_38_dialog_content = "สถานการณ์ที่นั่นเป็นอย่างไร? คุณมีความคิดเกี่ยวกับละครที่คุณปลุกระดมบ้างไหม?",
  ui_story_1012_10120801_39_dialog_content = "ผ-ผมขอโทษครับ",
  ui_story_1012_10120801_40_dialog_content = "ฮ่าฮ่าฮ่าฮ่า! ฉันไม่โทษเธอหรอก",
  ui_story_1012_10120801_41_dialog_content = "ฉันแค่อยากจะเตือนคุณว่า ท่ามกลางกลียุคล่าสุดใน Eraveil นั้น Illumina ไม่ใช่คนเดียวที่ได้รับรู้เหตุการณ์ล่าสุดเหล่านี้และออกเดินทาง",
  ui_story_1012_10120801_42_dialog_content = "อย่าทำให้ตัวเองอยู่ในสถานะที่คุณขาดพลังในการดำเนินการ",
  ui_story_1012_10120801_43_dialog_content = "ไม่ว่ายังไง เธอเป็นเพียงคนเดียวเท่านั้น ที่จะนำการเปลี่ยนแปลงมาสู่อีราเวลได้",
  ui_story_1012_10120801_44_dialog_content = "ฉันขอตัวก่อนนะ",
  ui_story_1012_10120801_45_dialog_content = "ครับ คุณไรน์ฮาร์ต",
  ui_story_1012_10120801_46_dialog_content = "เธอพูดถูกนะ",
  ui_story_1012_10120801_47_dialog_content = "ขณะนี้เรามองไม่เห็นสิ่งที่เกิดขึ้นนอกหอคอย มันทำให้เราเสียเปรียบ",
  ui_story_1012_10120801_48_dialog_content = "แล้วเราจะรู้เรื่องราวข้างนอกได้ยังไงล่ะ?",
  ui_story_1012_10120801_49_dialog_content = "บาร์ตันน่าจะยังติดต่อกับฟอร์ซาคินอยู่ ไม่อยากรบกวนเขาและสร้างปัญหาไปมากกว่านี้...",
  ui_story_1012_10120801_50_dialog_content = "ได้รับคำถามแล้ว... กำลังวิเคราะห์คำถาม...",
  ui_story_1012_10120801_51_dialog_content = "หา?!",
  ui_story_1012_10120801_52_dialog_content = "มีวิธีด้วยเหรอ สมองกลผู้ช่วย?",
  ui_story_1012_10120801_53_dialog_content = "กำลังเปิดใช้งานระบบเฝ้าติดตามภายนอกหอคอย",
  ui_story_1012_10120801_54_dialog_content = "แฮ่ก แฮ่ก...",
  ui_story_1012_10120801_55_dialog_content = "เลิกหนีสักที ฟอร์เซคิน!",
  ui_story_1012_10120801_56_dialog_content = "สู้จนกว่าฝ่ายใดฝ่ายหนึ่งจะล้ม! เผชิญหน้ากับฉันเหมือนนักรบตัวจริง!",
  ui_story_1012_10120801_57_dialog_content = "หืม?",
  ui_story_1012_10120801_58_dialog_content = "อะไรกัน...?",
  ui_story_1012_10120801_59_dialog_content = "ฉันไม่เคย... ไม่เห็นอะไรแบบนี้มานานแล้ว!",
  ui_story_1012_10120801_60_dialog_content = "(กองทัพอิคลิพไซท์มากมายอะไรขนาดนี้!)",
  ui_story_1012_10120801_61_dialog_content = "(สิ่งนี้เริ่มดูคล้ายกับ Darkover Crisis เมื่อสิบปีก่อนอย่างน่าขนลุก)",
  ui_story_1012_10120801_62_dialog_content = "(ฉันจะ... ยั้งไว้ได้อีกนานแค่ไหน PlayerNameก๊วนน้อย?)",
