  ui_story_1012_10121302_112_dialog_content = "<color=#e8d9bb>บี๊บ...</color>",
  ui_story_1012_10121302_113_dialog_content = "<color=#e8d9bb>บี๊บ—</color>",
  ui_story_1012_10121302_114_dialog_content = "...",
  ui_story_1012_10121401_1_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_1012_10121401_2_dialog_content = "เจ้านี่...",
  ui_story_1012_10121401_3_dialog_content = "(แข็งแกร่งอะไรอย่างนี้)",
  ui_story_1012_10121401_4_dialog_content = "โอ้ เจ้าเหยื่อตัวน้อย... หมดแรงหนีแล้วสินะ?",
  ui_story_1012_10121401_5_dialog_content = "แกบินได้นี่นา! ยังไงก็ไม่เหนื่อยอยู่แล้ว!",
