  ui_story_1012_10121401_18_dialog_content = "<color=#e8d9bb>เปรี้ยง!</color>",
  ui_story_1012_10121401_19_dialog_content = "*แค่ก*... อึก...",
  ui_story_1012_10121401_20_dialog_content = "*แฮ่ก แฮ่ก*... ไม่เป็นไรนะ ทหารอิลลูมินา?",
  ui_story_1012_10121401_21_dialog_content = "ฉันไม่เป็นไร... ในที่สุดก็หลุดจากมิตินั่นได้แล้ว",
