  ui_story_1012_10121401_46_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_1012_10121401_47_dialog_content = "โอ๊ย...",
  ui_story_1012_10121401_48_dialog_content = "แขนซ้าย... ขยับไม่ได้แล้ว...",
  ui_story_1012_10121401_49_dialog_content = "โอย... เจ็บชะมัด...",
  ui_story_1012_10121401_50_dialog_content = "*แค่ก*",
  ui_story_1012_10121401_51_dialog_content = "จิ๊ จิ๊... ได้เห็นพวกแกทุกคนต้องทรมานแบบนี้ ช่างน่าเวทนาจริง ๆ",
  ui_story_1012_10121401_52_dialog_content = "ท่านฟิเจอรัลด์! พวกมันเป็นแค่ออโรเรียนชั้นต่ำ ไม่ต้องให้ท่านลดตัวลงมายุ่งหรอกครับ",
  ui_story_1012_10121401_53_dialog_content = "ฉันก็เป็นคนแบบนี้ล่ะ! ประทับใจเสมอ เมื่อได้เห็นแสงสว่างสุดท้ายในดวงตาของพวกมันกำลังจะดับลง",
  ui_story_1012_10121401_54_dialog_content = "ความเมตตาที่มีให้ศัตรูนี่มัน! ท่านฟิเจอรัลด์ ท่านนี่ช่างยิ่งใหญ่นัก",
  ui_story_1012_10121401_55_dialog_content = "ยิ่งใหญ่งั้นรึ? อย่าดูถูกข้าด้วยคำพูดแบบนั้นเลย",
  ui_story_1012_10121401_56_dialog_content = "แต่... ก็ปฏิเสธไม่ได้ล่ะนะ ว่าข้าก็นึกสงสารเจ้าพวกนี้อยู่นิดหน่อย",
  ui_story_1012_10121401_57_dialog_content = "และข้าก็อยากจะจบความทรมานของเจ้าตัวน้อยพวกนี้ด้วยตนเอง",
  ui_story_1012_10121401_58_dialog_content = "งั้นรึ?",
  ui_story_1012_10121401_59_dialog_content = "หืม? นั่นมัน...",
  ui_story_1012_10121401_60_dialog_content = "ผู้ที่แสดงความเมตตาได้ จะต้องอยู่เหนือผู้อื่น",
  ui_story_1012_10121401_61_dialog_content = "ซึ่งแน่นอนว่าเจ้าไม่ได้อยู่ในฐานะที่จะทำแบบนั้น",
  ui_story_1012_10121401_62_dialog_content = "ราชินีแห่งแดนเหนือ!!! แก...",
  ui_story_1012_10121401_63_dialog_content = "ไมเคิลแองเจโลล่ะ?",
  ui_story_1012_10121401_64_dialog_content = "เขาหยุดฉันไม่ได้หรอก",
  ui_story_1012_10121401_65_dialog_content = "หนอย!",
  ui_story_1012_10121401_66_dialog_content = "นี่เป็นการต่อสู้ที่หนักหนาสำหรับเจ้าด้วย ไม่ใช่สำหรับออโรเรียนเท่านั้น",
  ui_story_1012_10121401_67_dialog_content = "เจ้าเอาแต่หนีมานานเกินไปแล้ว",
  ui_story_1012_10121401_68_dialog_content = "ไม่ว่ายังไงเจ้าก็จะต้องเผชิญหน้ากับข้า ก่อนที่ศึกครั้งนี้จะจบลง",
  ui_story_1012_10121401_69_dialog_content = "นี่คือราคาที่เจ้าจะต้องจ่าย สำหรับสงครามในครั้งนี้",
  ui_story_1012_10121401_70_dialog_content = "ฝ่าบาท!!! โอ ราชินีของเรามาช่วยแล้ว!!!",
  ui_story_1012_10121401_71_dialog_content = "ราชินีแห่งแดนเหนือ ช่างเป็นพลังที่น่าประทับใจจริง ๆ!",
  ui_story_1012_10121401_72_dialog_content = "พวกเธอ! ฉันรู้ว่าเธอถึงขีดจำกัดแล้ว",
  ui_story_1012_10121401_73_dialog_content = "แต่ขอให้อดทนอีกหน่อย เพราะสงครามยังไม่จบลงง่าย ๆ หรอกนะ",
  ui_story_1012_10121401_74_dialog_content = "ขณะนี้เคเลสไทต์พยายามชิงความได้เปรียบกลับมา แต่เราจะต้องซื้อเวลาให้เขาโดยการปกป้องหอคอยแห่งการหวนคืน",
  ui_story_1012_10121401_75_dialog_content = "การต่อสู้อันโหดร้ายนี้ไม่มีทีท่าว่าจะจบลงเลย",
  ui_story_1012_10121401_76_dialog_content = "เคเลสไทต์...",
  ui_story_1012_10121401_77_dialog_content = "มันคุ้มแล้วเหรอ ที่จะเดิมพันสงครามครั้งนี้กับเด็กอ่อนแอเพียงคนเดียวน่ะ?",
  ui_story_1012_10121401_78_dialog_content = "ฉันเชื่อมั่นใจตัวเขา",
  ui_story_1012_10121401_79_dialog_content = "และหวังว่าพวกเธอทุกคนก็จะคิดเช่นนั้นเหมือนกัน",
  ui_story_1012_10121401_80_dialog_content = "ค่ะ! ถ้าฝ่าบาทเชื่อมั่น ฉันก็จะเชื่อในตัวเขา!",
  ui_story_1012_10121401_81_dialog_content = "...",
  ui_story_1012_10121401_82_dialog_content = "อืม... การตัดสินใจของราชินีแห่งแดนเหนือเป็นสิ่งที่น่าเชื่อกว่าฉัน",
  ui_story_1012_10121401_83_dialog_content = "แล้วยังไงพวกเราก็ไม่คิดจะยอมแพ้อยู่แล้ว",
  ui_story_1012_10121401_84_dialog_content = "แต่เรื่องที่ฉันกังวลก็คือ...",
  ui_story_1012_10121401_85_dialog_content = "เรายังมีกำลังพอที่จะปกป้องหอคอยไว้ได้อีกเหรอ?",
  ui_story_1012_10121401_86_dialog_content = "เรื่องนั้นไม่ต้องห่วง",
  ui_story_1012_10121401_87_dialog_content = "เธอคนนั้นยังปกป้องทางเข้าของหอคอยอยู่ อย่างไรซะ เธอก็เกิดมาเพื่อสงครามอยู่แล้ว",
  ui_story_1012_10121401_88_dialog_content = "(ภาษาอิคลิพส์) ถอนกำลัง! ถอยเดี๋ยวนี้!",
  ui_story_1012_10121401_89_dialog_content = "(ภาษาอิคลิพส์) เร็วเข้า! ถอยให้ไกลที่สุดเท่าที่จะทำได้!",
  ui_story_1012_10121401_90_dialog_content = "(ภาษาอิคลิพส์) ท่านฟอร์เซคิน ท่านฟิเจอรัลด์สั่งให้เราบุกเต็มกำลังไม่ใช่เหรอขอรับ",
  ui_story_1012_10121401_91_dialog_content = "(ภาษาอิคลิพส์) แล้ว ทำไม...?",
  ui_story_1012_10121401_92_dialog_content = "(ภาษาอิคลิพส์) ฉันบอกให้ถอยก็ถอยไง! ฉันสั่งอะไรก็ทำซะ!!!",
  ui_story_1012_10121401_93_dialog_content = "(ภาษาอิคลิพส์) ท่านฟอร์เซคิน?",
  ui_story_1012_10121401_94_dialog_content = "(ภาษาอิคลิพส์) นี่คือคำสั่งใหม่ เพราะฉะนั้นถอยไปได้แล้ว!",
  ui_story_1012_10121401_95_dialog_content = "(ภาษาอิคลิพส์) หน้าที่ของพวกแกคือโจมตี ไม่ใช่เอาตัวเองไปตายเปล่า!",
  ui_story_1012_10121401_96_dialog_content = "<color=#e8d9bb>ตูม!!! ปัง เปรี้ยง ตูม!</color>",
  ui_story_1012_10121401_97_dialog_content = "หา?!",
  ui_story_1012_10121401_98_dialog_content = "เกิดอะไรขึ้นตรงทางเข้าหอคอยสีขาวน่ะ?",
  ui_story_1012_10121401_99_dialog_content = "เสียง... ระเบิดงั้นเหรอ?",
  ui_story_1012_10121401_100_dialog_content = "...",
  ui_story_1012_10121401_101_dialog_content = "ทั้งหุบเขากำลังสั่นสะเทือน",
  ui_story_1012_10121401_102_dialog_content = "นั่นมันบ้าอะไรเนี่ย...?",
  ui_story_1012_10121401_103_dialog_content = "นั่นคืออาวุธ และเจ้าก็เคยเห็นมันมาก่อน",
  ui_story_1012_10121401_104_dialog_content = "หมายความว่ายังไงครับ ผมเคยเห็นมาก่อนงั้นเหรอ...?!",
  ui_story_1012_10121401_105_dialog_content = "เป็นไปไม่ได้...",
  ui_story_1012_10121401_106_dialog_content = "ในที่สุด! ฉันก็จะได้เห็นวาระสุดท้ายอันแสนกล้าหาญของจอมทัพแห่งอิลลูมินา",
  ui_story_1012_10121401_107_dialog_content = "ไม่รู้ว่าฉันควรจะตื่นเต้นหรือประหม่าดีนะ?",
  ui_story_1012_10121401_108_dialog_content = "หืม ศัตรูหายหัวไปไหนหมดล่ะเนี่ย?",
  ui_story_1012_10121401_109_dialog_content = "น่าสงสัยจังแฮะ ทำไมจู่ ๆ สนามรบก็โล่งแบบนี้ได้?",
  ui_story_1012_10121401_110_dialog_content = "พวกแกมันก็เป็นแค่ตัวประหลาดน่ารังเกียจ",
  ui_story_1012_10121401_111_dialog_content = "สิ่งวิปริตอย่างแกกลัวตายเป็นด้วยเหรอ?",
  ui_story_1012_10121401_112_dialog_content = "...",
  ui_story_1012_10121401_113_dialog_content = "ไรน์ฮาร์ต ถ้าเธอใช้พลังแบบนั้น มันจะเป็นการทำลายตัวเธอเองนะ",
  ui_story_1012_10121401_114_dialog_content = "ฮ่าฮ่าฮ่า! ไร้สาระน่า ที่นี่คือสนามรบ",
  ui_story_1012_10121401_115_dialog_content = "ฉันไม่คิดว่าตัวเองจะได้กลับบ้านอย่างไร้รอยขีดข่วนอยู่แล้ว",
  ui_story_1012_10121401_116_dialog_content = "เธอควรใช้พลังนั่นช่วยคนอื่นตีฝ่าวงล้อมออกไปไม่ใช่หรือไง",
  ui_story_1012_10121401_117_dialog_content = "เธอไม่ได้เข้าใจอะไรเลยสินะ...",
  ui_story_1012_10121401_118_dialog_content = "สงครามครั้งนี้คือการตั้งรับจนกว่าเราจะคว้าชัยชนะ",
  ui_story_1012_10121401_119_dialog_content = "ฉันไม่เคยคิดจะฝ่าออกไปอยู่แล้ว!",
  ui_story_1012_10121401_120_dialog_content = "...",
  ui_story_1012_10121401_121_dialog_content = "ไม่ว่ายังไง เราสองคนก็คงไม่มีทางเข้าใจกันได้จริง ๆ",
  ui_story_1012_10121401_122_dialog_content = "ฮ่าฮ่า! มันก็เป็นแบบนั้นมาเสมอไม่ใช่หรือไง",
  ui_story_1012_10121401_123_dialog_content = "ในเมื่อเธอจุดไฟเผาตัวเอง",
  ui_story_1012_10121401_124_dialog_content = "ฉันก็จะคอยดูจนกว่าเธอจะมอดไหม้",
  ui_story_1012_10121401_125_dialog_content = "เอาสิ เข้ามาเลย",
  ui_story_1012_10121401_126_dialog_content = "นี่คือการต่อสู้ครั้งสุดท้ายของพวกเรา",
  ui_story_1012_10121401_127_dialog_content = "...",
  ui_story_1012_10121401_128_dialog_content = "(ภาษาอิคลิพส์) กำลังรบทุกหน่วย โจมตีหอคอยแห่งการหวนคืน",
  ui_story_1012_10121401_129_dialog_content = "แฮ่ก แฮ่ก",
  ui_story_1012_10121401_130_dialog_content = "กรรร!!",
  ui_story_1012_10121401_131_dialog_content = "อิคลิพไซท์.... ยังเหลืออีกเยอะเลย...",
