  ui_story_1012_10121401_133_dialog_content = "อ๊าก...!",
  ui_story_1012_10121401_134_dialog_content = "โชคดีที่เป็นแขนซ้ายของฉัน... ฉันยังถืออาวุธได้...",
  ui_story_1012_10121401_135_dialog_content = "มันยังเหลืออีกเท่าไหร่เหรอ PlayerName? พวกมันอยู่ตรงไหนบ้าง...",
  ui_story_1012_10121401_136_dialog_content = "โอ๊ะ ลืมไปเลย นายไม่ได้ยินฉันสินะ...",
  ui_story_1012_10121401_137_dialog_content = "แล้วฉันก็ไม่รู้ด้วยซ้ำว่าตอนนี้นายทำอะไรอยู่",
  ui_story_1012_10121401_138_dialog_content = "ฉันจะทนได้อีกนานแค่ไหนกัน... คงไม่นานขนาดนั้นด้วยซ้ำ...",
  ui_story_1012_10121401_139_dialog_content = "อ๊ากกกก!",
  ui_story_1012_10121401_140_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_1012_10121401_141_dialog_content = "โอ๊ย! มือฉัน!",
  ui_story_1012_10121401_142_dialog_content = "ต่อยด้วยมือแบบนี้... จะได้ผลจริง ๆ เหรอ?",
  ui_story_1012_10121401_143_dialog_content = "...",
  ui_story_1012_10121401_144_dialog_content = "แย่ล่ะ มันอยู่ทางขวา...",
  ui_story_1012_10121401_145_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_1012_10121401_146_dialog_content = "แค่ก",
  ui_story_1012_10121401_147_dialog_content = "แย่ล่ะ! ยังไม่ทันไร... เจ้านั่นก็กลับมาอีกแล้ว...",
  ui_story_1012_10121401_148_dialog_content = "...",
  ui_story_1012_10121401_149_dialog_content = "อ๋อ ท่านี้ฉันจำได้ เป็นท่าจู่โจมแบบรวดเร็วรุนแรง",
  ui_story_1012_10121401_150_dialog_content = "เอาล่ะ ตั้งสติให้ดี! ตั้งสติ...",
