  ui_story_1012_10121401_152_dialog_content = "ฟู่! หลบได้...",
  ui_story_1012_10121401_153_dialog_content = "แต่ก็ไม่รู้จะสวนมันยังไงแล้ว...",
  ui_story_1012_10121401_154_dialog_content = "ตอนนี้ฉันหมดแรง ทำได้แค่หลบอย่างเดียว ถึงจะพอเอาตัวรอดไปได้เรื่อย ๆ แต่...",
  ui_story_1012_10121401_155_dialog_content = "ฉันจะมัวเสียเวลาแบบนี้ไม่ได้อีกแล้ว",
  ui_story_1012_10121401_156_dialog_content = "สถานการณ์ข้างนอกหอคอยแย่มาก แล้วคาร์ลีนก็คงหยุดอิคลิพไซท์มากมายขนาดนั้นไม่ได้นาน",
  ui_story_1012_10121401_157_dialog_content = "ฉันจะต้องใช้ \"คอร์ดแห่งบัญญัติ\" ให้ได้ ยิ่งเร็วเท่าไหร่ยิ่งดี",
  ui_story_1012_10121401_158_dialog_content = "แต่จะทำได้ยังไงล่ะ?",
  ui_story_1012_10121401_159_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_1012_10121401_160_dialog_content = "อีกแล้วเหรอ!",
  ui_story_1012_10121401_161_dialog_content = "โอย... แค่ยืนก็แทบจะไม่ไหวแล้ว...",
  ui_story_1012_10121401_162_dialog_content = "แต่ถ้าไม่จัดการผู้พิทักษ์ทั้งสองตัว ฉันก็ทำอะไรไม่ได้",
  ui_story_1012_10121401_163_dialog_content = "ยังไงก็ต้องกำจัดพวกมัน",
  ui_story_1012_10121401_164_dialog_content = "ลองอีกทีก็แล้วกัน...",
  ui_story_1012_10121401_165_dialog_content = "อ๊าาาาาา!",
  ui_story_1012_10121401_166_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_1012_10121401_167_dialog_content = "เจ็บชะมัด!",
  ui_story_1012_10121401_168_dialog_content = "แต่... เดี๋ยวนะ นี่มันพื้นที่ในจิตสำนึกนี่นา!",
  ui_story_1012_10121401_169_dialog_content = "ไม่ว่าจะเจ็บแค่ไหน แต่ทุกอย่างในนี้ทำร้ายฉันจริง ๆ ไม่ได้",
  ui_story_1012_10121401_170_dialog_content = "มันก็เป็นแค่ความคิด เพราะงั้นถ้าทนเจ็บให้ได้ก็ไม่มีปัญหา!",
  ui_story_1012_10121401_171_dialog_content = "ใช่ แค่อดทนไว้",
  ui_story_1012_10121401_172_dialog_content = "ถ้าหมัดเดียวไม่เป็นไร ก็ลองสักร้อยครั้ง หมื่นครั้ง",
  ui_story_1012_10121401_173_dialog_content = "ฉันจะไม่หยุดจนกว่าจะชนะ!",
  ui_story_1012_10121401_174_option_content = "ต่อย!",
  ui_story_1012_10121401_175_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_1012_10121401_176_dialog_content = "โอ๊ย...",
  ui_story_1012_10121401_177_option_content = "ต่อย!",
  ui_story_1012_10121401_178_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_1012_10121401_179_dialog_content = "จนความเจ็บให้ได้...",
  ui_story_1012_10121401_180_option_content = "ต่อย!",
  ui_story_1012_10121401_181_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_1012_10121401_182_dialog_content = "นิ้วของฉันชาไปหมดแล้ว แย่ล่ะ แบบนี้จะกำมือได้ยังไง",
  ui_story_1012_10121401_183_dialog_content = "จะสร้างพื้นที่จิตสำนึกให้สมจริงขนาดนี้ไปทำไมเนี่ย?",
  ui_story_1012_10121401_184_dialog_content = "ช่างเหอะ ฉันยังมีมืออีกข้าง!",
  ui_story_1012_10121401_185_option_content = "ต่อย!",
  ui_story_1012_10121401_186_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_1012_10121401_187_dialog_content = "พวกแก จะอึดอะไรขนาดนี้เนี่ย?",
  ui_story_1012_10121401_188_option_content = "ต่อย!",
  ui_story_1012_10121401_189_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_1012_10121401_190_dialog_content = "เอาล่ะ ได้ผลมั้ย...?",
  ui_story_1012_10121401_191_dialog_content = "!!!",
  ui_story_1012_10121401_192_dialog_content = "เดี๋ยวนะ ลืมอีกตัวไปเลย...",
  ui_story_1012_10121401_193_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_1012_10121401_194_dialog_content = "อัก... โอย...",
  ui_story_1012_10121401_195_dialog_content = "หมดแรงแล้ว... ฉัน... ขยับไม่ได้เลย...",
  ui_story_1012_10121401_196_dialog_content = "ไม่ว่าฉันจะทำยังไง ฉันสู้มันคนเดียวไม่ไหว",
  ui_story_1012_10121401_197_dialog_content = "(ในที่สุด ฉันก็ได้เข้าใจถึงความหมายของ \"โองการสูงสุด\" ของหอคอยแห่งการหวนคืน)",
  ui_story_1012_10121401_198_dialog_content = "(ว่ามันห่างไกลและสูงส่งเกินกว่าที่ฉันจะเข้าใจ)",
  ui_story_1012_10121401_199_dialog_content = "(ระบบที่มีอำนาจบงการจิตใจอย่างแท้จริง ไม่ใช่แค่จักรกลที่สักแต่พูด)",
  ui_story_1012_10121401_200_dialog_content = "(มันฉวยโอกาสจู่โจมจุดอ่อนที่ติดตัวมาตั้งแต่กำเนิดของพวกเรา)",
  ui_story_1012_10121401_201_dialog_content = "(ไม่ว่าจะมีสติปัญญาหรือพลังใจมากมายแค่ไหนก็ไร้ความหมาย)",
  ui_story_1012_10121401_202_dialog_content = "(มันใช้แค่เพียงสิ่งเดียว นั่นก็คือพลังที่ไม่อาจต่อต้าน เพื่อปกป้องโองการสูงสุด)",
  ui_story_1012_10121401_203_dialog_content = "(เคเลสไทต์ไม่มีวันสู้กับสิ่งนั้นได้ ตั้งแต่วินาทีแรกที่พวกเราถือกำเนิดมา)",
  ui_story_1012_10121401_204_dialog_content = "(นี่คือพันธนาการแห่งสายเลือดของเผ่าพันธุ์เคเลสไทต์)",
  ui_story_1012_10121401_205_dialog_content = "...",
  ui_story_1012_10121401_206_dialog_content = "ขอโทษนะทุกคน ฉัน...",
  ui_story_1012_10121401_207_dialog_content = "ใครเป็นคนคิดเรื่องแย่ ๆ พวกนี้ล่ะเนี่ย?",
  ui_story_1012_10121401_208_dialog_content = "!!!",
  ui_story_1012_10121401_209_dialog_content = "ไวซ์?",
  ui_story_1012_10121401_210_dialog_content = "เจ้าพวกนั้นนี่น่ารำคาญชะมัดเลย ว่ามั้ย?",
  ui_story_1012_10121401_211_dialog_content = "นายไปหลบก่อนดีกว่านะ ตอนนี้ฉันกำลังฝึกให้ชินกับของเล่นใหม่อยู่ กลัวนายจะโดนลูกหลงน่ะ",
  ui_story_1012_10121401_212_dialog_content = "ไวซ์ เธอจริง ๆ ด้วย!!!",
  ui_story_1012_10121401_213_dialog_content = "เธอ... ฟื้นแล้วงั้นเหรอ? แต่ เป็นไปได้ยังไงกัน?",
  ui_story_1012_10121401_214_dialog_content = "อย่าถามเยอะขนาดนั้นสิ ฉันไม่รู้ว่าจะต้องเริ่มตอบตรงไหนน่ะ",
  ui_story_1012_10121401_215_dialog_content = "มาเริ่มจากเรื่องง่าย ๆ ก่อนก็แล้วกัน นายต้องจัดการเจ้าพวกนั้นใช่มั้ย?",
  ui_story_1012_10121401_216_dialog_content = "ใช่!",
  ui_story_1012_10121401_217_dialog_content = "งั้นมัวรออะไรอยู่ล่ะ?",
  ui_story_1012_10121401_218_dialog_content = "PlayerName สั่งการฉันเลยสิ",
  ui_story_1012_10121402_1_dialog_content = "เอาล่ะ หมดเวลาสนุกของพวกแกสองตัวแล้ว!",
  ui_story_1012_10121402_2_dialog_content = "แกก่อนก็แล้วกัน เจ้าตัวโต!",
  ui_story_1012_10121402_3_dialog_content = "ซ่า...",
  ui_story_1012_10121402_4_dialog_content = "คราวหน้าไปหัดหลบการโจมตีมาด้วยล่ะ",
  ui_story_1012_10121402_5_dialog_content = "การป้องกันอย่างเดียวต้านลูกธนูของฉันไม่อยู่หรอกนะ!",
  ui_story_1012_10121402_6_dialog_content = "ไวซ์! ระวัง!",
  ui_story_1012_10121402_7_dialog_content = "รู้แล้ว ให้ระวังทางขวาใช่มั้ย?",
  ui_story_1012_10121402_8_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_1012_10121402_9_dialog_content = "หืม... เธอรู้ได้ไงน่ะ?",
  ui_story_1012_10121402_10_dialog_content = "เหลือแค่ตัวเดียวแล้ว ยิ่งง่ายเข้าไปใหญ่",
  ui_story_1012_10121402_11_dialog_content = "แกจะรับลูกธนูได้กี่ดอกกันนะ? ขอลองหน่อยเถอะ!",
  ui_story_1012_10121402_12_dialog_content = "ซ่า...",
  ui_story_1012_10121402_13_dialog_content = "โอ้โห! เราจัดการผู้พิทักษ์ทั้งสองตัวได้แล้ว",
  ui_story_1012_10121402_14_dialog_content = "เยี่ยมเลย ไวซ์!!!",
  ui_story_1012_10121402_15_dialog_content = "ฟู่... พวกมันก็เก่งเหมือนกันนะ",
  ui_story_1012_10121402_16_dialog_content = "ถ้าร่างกายของฉันไม่ได้รับการดัดแปลง ฉันก็คงสู้ไม่ไหว",
  ui_story_1012_10121402_17_dialog_content = "แล้วเธอเข้ามาในนี้ได้ยังไงน่ะ? นึกว่าที่นี่เปิดให้แต่เคเลสไทต์ซะอีก",
  ui_story_1012_10121402_18_dialog_content = "หรือว่า... เธอจะไม่ใช่ไวซ์จริง ๆ? แต่เป็นแค่ส่วนหนึ่งของจินต...",
  ui_story_1012_10121402_19_dialog_content = "ฉันเป็นไวซ์ตัวจริงนะ!",
  ui_story_1012_10121402_20_dialog_content = "คิดว่านายมีพลังวิเศษหรือไง? เรียกไวซ์ออกมาช่วยทุกเวลาที่เกิดเรื่องอะไรยังงั้นเรอะ?",
  ui_story_1012_10121402_21_dialog_content = "ก็ไม่น่าใช่แหละ แต่เธอเข้ามาได้ยังไงน่ะ? มันไม่สมเหตุสมผลเลย",
  ui_story_1012_10121402_22_dialog_content = "เอาล่ะ ฉันจะเล่าง่าย ๆ ละกัน...",
  ui_story_1012_10121402_23_dialog_content = "ฉันฟื้นขึ้นมาจากอาการหมดสติ แล้วก็รู้สึกได้ทันทีว่านายอยากให้ฉันช่วย",
  ui_story_1012_10121402_24_dialog_content = "เอ๋?",
  ui_story_1012_10121402_25_dialog_content = "ฉันก็ไม่รู้ว่าทำไม เหมือนกับว่าความคิดของเรามันเชื่อมกันสักทางน่ะ",
  ui_story_1012_10121402_26_dialog_content = "ฉันรับรู้ได้ว่านายกังวลใจมาก ๆ แล้วก็รู้ตำแหน่งของนายด้วย",
  ui_story_1012_10121402_27_dialog_content = "พอฉันเจอนายแล้วแตะตัวนาย จิตสำนึกของฉันก็ถูกส่งมาที่นี่ เหมือนตัวเองโดนดึงเข้ามา",
  ui_story_1012_10121402_28_dialog_content = "แล้วที่เหลือก็เป็นอย่างที่เห็นนี่แหละ",
  ui_story_1012_10121402_29_dialog_content = "จิตสำนึกของเรา เชื่อมกันยังงั้นเหรอ?",
  ui_story_1012_10121402_30_dialog_content = "ฉันก็ไม่รู้ว่ามันเกิดขึ้นได้ยังไง",
  ui_story_1012_10121402_31_dialog_content = "แต่เรื่องรายละเอียดไว้คุยกันทีหลังเถอะ!",
  ui_story_1012_10121402_32_dialog_content = "คาร์ลีนบอกว่านายต้องเปิดระบบอาวุธสุดยอดสักอย่างในหอคอยใช่มั้ย?",
  ui_story_1012_10121402_33_dialog_content = "งั้นเรารีบไปกันเถอะ!",
  ui_story_1012_10121402_34_dialog_content = "จริงด้วย นั่นสินะ!",
  ui_story_1012_10121402_35_dialog_content = "เราต้องช่วงชิงสิทธิ์ควบคุมวงแหวนแกนกลาง มันอยู่ที่ไหนสักแห่งในพื้นที่จิตสำนึกนี่ล่ะมั้ง",
  ui_story_1012_10121402_36_option_content = "บังคับเชื่อมกระแสจิต",
  ui_story_1012_10121402_37_dialog_content = "<color=#e8d9bb>วื้ด!</color>",
  ui_story_1012_10121402_38_dialog_content = "อ๊ะ! อะไรเนี่ย...?",
  ui_story_1012_10121402_39_dialog_content = "(ความคิดของฉันแผ่ขยายออกไปครอบคลุมทุกอย่าง)",
  ui_story_1012_10121402_40_dialog_content = "(พวกเรา... เป็นหนึ่งเดียวกัน...)",
  ui_story_1012_10121402_41_dialog_content = "(ฉันรู้สึกถึงความสงบอย่างที่ไม่เคยสัมผัสมาก่อน ราวกับว่า...)",
  ui_story_1012_10121402_42_dialog_content = "(ฉันกำลังล่องลอยอยู่บนท้องฟ้าที่ไร้ขอบเขต)",
  ui_story_1012_10121402_43_dialog_content = "(ไม่มีใครฉุดรั้ง มองเห็นทุกสิ่งเบื้องล่างจากข้างบนนั้น)",
  ui_story_1012_10121402_44_dialog_content = "ได้ผลมั้ย? เจออะไรบ้างรึเปล่า?",
  ui_story_1012_10121402_45_dialog_content = "ไม่น่าจะใช่แฮะ ฉันไม่เจออะไรเลย มีแต่พวกเรากับผู้พิทักษ์ที่โดนจัดการไปแล้ว",
  ui_story_1012_10121402_46_dialog_content = "แต่เอาจริง ๆ ฉันยังไม่รู้ด้วยซ้ำว่าควรมองหาอะไร",
  ui_story_1012_10121402_47_dialog_content = "อยากให้สมองกลผู้ช่วยมาอยู่ด้วยจัง",
  ui_story_1012_10121402_48_dialog_content = "ต้องการให้สมองกลช่วยอะไรงั้นรึ?",
  ui_story_1012_10121402_49_dialog_content = "หวา!",
  ui_story_1012_10121402_50_dialog_content = "นี่แกเป็นตัวจริงรึเปล่าเนี่ย?",
  ui_story_1012_10121402_51_dialog_content = "ตอนแรกทำไมเรียกแล้วไม่เห็นตอบเลย?",
  ui_story_1012_10121402_52_dialog_content = "สาเหตุเป็นเพราะสมองกลไม่ได้รับอนุญาตให้แตะต้องวงแหวนแกนกลาง",
  ui_story_1012_10121402_53_dialog_content = "แล้วทำไมตอนนี้ทำไมโผล่ออกมาได้แล้วล่ะ?",
  ui_story_1012_10121402_54_dialog_content = "เพราะนั่นเป็นส่วนหนึ่งของโองการสูงสุด",
  ui_story_1012_10121402_55_dialog_content = "โองการสูงสุดต้องการให้สมองกลผู้ช่วยปรากฏตัว ดังนั้นสมองกลจึงปฏิบัติตามคำสั่งดังกล่าว",
  ui_story_1012_10121402_56_dialog_content = "โองการสูงสุด?",
  ui_story_1012_10121402_57_dialog_content = "คนที่อยากให้แกโผล่มาคือฉันต่างหาก?",
  ui_story_1012_10121402_58_dialog_content = "ถูกต้องแล้ว",
  ui_story_1012_10121402_59_dialog_content = "ขณะนี้คุณคือโองการสูงสุด",
  ui_story_1012_10121402_60_dialog_content = "ว่าไงนะ?!",
  ui_story_1012_10121402_61_dialog_content = "จิตสำนึกของคุณได้รวมเข้ากับวงแหวนแกนกลางแล้ว",
  ui_story_1012_10121402_62_dialog_content = "วงแหวนแกนกลางคือผู้ครอบครองโองการสูงสุด ดังนั้น ตอนนี้คุณคือโองการสูงสุด",
  ui_story_1012_10121402_63_dialog_content = "สมองกลต้องปฏิบัติตามคำสั่งของคุณ และสนองความปรารถนาของคุณให้เป็นจริง",
  ui_story_1012_10121402_64_dialog_content = "เอาล่ะ ต้องการให้สมองกลช่วยอะไรงั้นรึ?",
  ui_story_1012_10121402_65_dialog_content = "เดี๋ยวนะ ตอนแรกโองการสูงสุดคอยขัดขวางฉัน แต่ตอนนี้...ฉันกลายเป็นโองการสูงสุดซะเองงั้นเหรอ?",
  ui_story_1012_10121402_66_dialog_content = "เอาล่ะ ถ้างั้น... ฉันขอเปิดใช้งานคอร์ดแห่งบัญญัติ",
  ui_story_1012_10121402_67_dialog_content = "ได้รับคำสั่งแล้ว กำลังเริ่มต้นคอร์ดแห่งบัญญัติ",
  ui_story_1012_10121402_68_dialog_content = "กรุณาป้อนพารามิเตอร์กำหนดเป้าหมาย และกฎเกณฑ์ที่คุณต้องการบังคับใช้",
  ui_story_1012_10121402_69_dialog_content = "เอ๋??? พูดอะไรของแกน่ะ?",
  ui_story_1012_10121402_70_dialog_content = "คอร์ดแห่งบัญญัติเป็นอาวุธความแม่นยำสูง",
  ui_story_1012_10121402_71_dialog_content = "การทำงานจำเป็นต้องระบุข้อมูล \"ระยะเวลา\" และข้อมูล \"เป้าหมาย\" ประกอบด้วย",
  ui_story_1012_10121402_72_dialog_content = "ทั้งนี้เพื่อให้ผลลัพธ์เป็นไปตามที่คาดหมาย",
  ui_story_1012_10121402_73_dialog_content = "แล้วฉันจะรู้ได้ยังไงว่าต้องใส่ข้อมูลอะไรบ้าง?",
  ui_story_1012_10121402_74_dialog_content = "แล้วพวกนี้มันเป็นตัวเลขจริง ๆ เหรอ? ฉันอ่านไม่ออกเลย!",
  ui_story_1012_10121402_75_dialog_content = "นี่เป็นขั้นตอนที่จำเป็น กรุณาป้อนพารามิเตอร์กำหนดเป้าหมาย และกฎเกณฑ์ที่คุณต้องการบังคับใช้",
  ui_story_1012_10121402_76_dialog_content = "ง-งั้น... แค่โจมตีอิคลิพไซท์ทั้งหมดที่อยู่ใกล้กับหอคอยแห่งการหวนคืนก็พอ โอเคมั้ย?",
  ui_story_1012_10121402_77_dialog_content = "ขออภัย คำขอนี้กว้างเกินไป คอร์ดแห่งบัญญัติเป็นอาวุธความแม่นยำสูง",
  ui_story_1012_10121402_78_dialog_content = "แล้วจะให้ฉันทำยังไงล่ะ!?",
  ui_story_1012_10121402_79_dialog_content = "อุตส่าห์มาไกลขนาดนี้แล้ว คงไม่ได้จะห้ามฉันหรอกนะ?",
  ui_story_1012_10121402_80_dialog_content = "เราพบพารามิเตอร์ที่มีอยู่เดิม ซึ่งนำไปใช้เริ่มต้นการทำงานได้",
  ui_story_1012_10121402_81_dialog_content = "ต้องการดำเนินการต่อหรือไม่?",
  ui_story_1012_10121402_82_dialog_content = "พารามิเตอร์ที่มีอยู่เดิม?",
  ui_story_1012_10121402_83_dialog_content = "คำเตือน: อิคลิพไซท์ที่ไม่ได้ลงทะเบียนกำลังเข้าสู่หอคอยแห่งการหวนคืน",
  ui_story_1012_10121402_84_dialog_content = "พวกมันมีจำนวนมากเกินไป ไม่สามารถนับได้อย่างแม่นยำ",
  ui_story_1012_10121402_85_dialog_content = "แย่แล้ว! ทุกคนข้างนอกกำลังจะเสียท่า",
  ui_story_1012_10121402_86_dialog_content = "จะมัวเสียเวลาไปมากกว่านี้ไม่ได้แล้ว",
  ui_story_1012_10121402_87_dialog_content = "สมองกลผู้ช่วย บอกได้มั้ยว่าใครเป็นคนป้อนพารามิเตอร์พวกนั้น?",
  ui_story_1012_10121402_88_dialog_content = "ได้สิ",
