  ui_story_1013_10130201_144_dialog_content = "ที่รกร้างว่างเปล่าโดยสิ้นเชิง มีลมพัดเย็นสบายและมีแดดจัด",
  ui_story_1013_10130201_145_dialog_content = "ฟังดูถูกต้อง",
