  ui_story_1013_10130201_153_dialog_content = "โว่ว!",
  ui_story_1013_10130201_154_dialog_content = "มันปรากฏ!",
  ui_story_1013_10130201_155_dialog_content = "นั่นเป็นเรื่องเหลือเชื่อ ดูเหมือนว่าฉัน!",
