  ui_story_1013_10130401_2_dialog_content = "หิวจนไส้กิ่วแล้วเนี่ย...",
  ui_story_1013_10130401_3_dialog_content = "<color=#e8d9bb>กรร!</color>",
  ui_story_1013_10130401_4_dialog_content = "ฉันหิวมาก!",
  ui_story_1013_10130401_5_dialog_content = "หลังจากเสร็จจากศูนย์วิจัยเมื่อวานนี้ Vice ก็พาฉันออกไปค้างคืนในเมืองกันนอน",
  ui_story_1013_10130401_6_dialog_content = "ไม่คิดว่าวันนี้จะตื่นสายขนาดนี้!",
  ui_story_1013_10130401_7_dialog_content = "<color=#e8d9bb>*ท้องร้อง*</color>",
  ui_story_1013_10130401_8_dialog_content = "แค่นั้นแหละ. ต้องหาอะไรกินแล้วล่ะ",
  ui_story_1013_10130401_9_dialog_content = "เมืองนี้ใหญ่มาก ฉันแน่ใจว่ามีแหล่งหาอาหารมากมาย",
  ui_story_1013_10130401_10_dialog_content = "ฉันหวังว่ามันจะไม่แพงเกินไป Nightium เหลือไม่เยอะแล้วนะคะ",
  ui_story_1013_10130401_11_dialog_content = "ไม่อะ",
  ui_story_1013_10130401_12_dialog_content = "อีกไม่?",
  ui_story_1013_10130401_13_dialog_content = "ทำไมไม่มีอะไรเลยจริงๆ?!",
  ui_story_1013_10130401_14_dialog_content = "ฉันเดินไปหลายไมล์ ไม่พบอาหารเลย และตอนนี้ฉันยิ่งหิวมากขึ้นไปอีก!",
  ui_story_1013_10130401_15_dialog_content = "ฉันสาบานว่าการมองเห็นของฉันกำลังจะเลือนหายไปแล้ว...",
  ui_story_1013_10130401_16_dialog_content = "รอ! นั่นมัน...กลิ่นอาหารฉันเหรอ?!",
  ui_story_1013_10130401_17_dialog_content = "PlayerName?!",
  ui_story_1013_10130401_18_dialog_content = "ตื่นนอน, PlayerName! คุณไม่อยากนอนที่นี่!",
  ui_story_1013_10130401_19_option_content = "วี-ไวซ์?!",
  ui_story_1013_10130401_20_dialog_content = "คุณสบายดีหรือเปล่า? คุณดูไม่ค่อยดีนัก",
  ui_story_1013_10130401_21_dialog_content = "ฉันสบายดี. หิวจริงๆ หาที่กินไม่ได้แล้ว...",
  ui_story_1013_10130401_22_dialog_content = "ฉันพเนจรไปโดยเปล่าประโยชน์มาช้านานแต่สุดท้ายก็กลับมาที่นี่",
  ui_story_1013_10130401_23_dialog_content = "โอ้ ฉันขอโทษจริงๆ! ฉันลืมที่จะพูดถึง",
  ui_story_1013_10130401_24_dialog_content = "Illumina ใช้ระบบปันส่วน ดังนั้นจึงไม่มีร้านอาหารหรืออะไรใน Gannon",
  ui_story_1013_10130401_25_dialog_content = "หากผู้เข้าชมต้องการเสบียง พวกเขาต้องไปในพื้นที่ที่กำหนดและกระโดดผ่านห่วงของข้าราชการทั้งหมดก่อน",
  ui_story_1013_10130401_26_dialog_content = "เมื่อวานยุ่งกับการสอบมากจนลืมสมัครไปเลย...",
  ui_story_1013_10130401_27_dialog_content = "เจ้าหน้าที่วิเวียนได้จัดเตรียมเสบียงให้กับคุณแล้ว ดังนั้น ไปรับพวกเขากันเถอะเมื่อเราทำเสร็จแล้ว!",
  ui_story_1013_10130401_28_dialog_content = "ดูเหมือนเป็นเรื่องยุ่งยากเล็กน้อย",
  ui_story_1013_10130401_29_dialog_content = "ผลผลิตของสมาพันธ์อิลลูมิน่ามีจำกัด แม้แต่การทำให้แน่ใจว่าทุกคนสามารถรับประทานได้ก็ไม่ใช่เรื่องเล็ก",
  ui_story_1013_10130401_30_dialog_content = "การปันส่วนเป็นวิธีที่ดีที่สุดในการหลีกเลี่ยงขยะและทำให้ทุกคนมีเพียงพอ",
  ui_story_1013_10130401_31_dialog_content = "อย่างไรก็ตาม ดูสิ่งที่ฉันนำมา! อาหารเช้า!",
  ui_story_1013_10130401_32_dialog_content = "แถ่นแท้น!",
  ui_story_1013_10130401_33_dialog_content = "นั่นเป็นอาหารที่ฉันได้กลิ่น!",
  ui_story_1013_10130401_34_dialog_content = "คุณต้องหิวโหย! มาและกิน!",
  ui_story_1013_10130401_35_dialog_content = "ต้องรีบกลับไปที่ศูนย์วิจัยแล้ว!",
  ui_story_1013_10130401_36_dialog_content = "ฉันกำลังขุด!",
  ui_story_1013_10130401_37_dialog_content = "(ฉันไม่รู้มาก่อนว่าสถานที่ที่ดูทรงพลังอย่างอิลลูมินาจะต้องระวังทรัพยากรมากขนาดนี้)",
  ui_story_1013_10130401_38_dialog_content = "นอม นอม นอม...",
  ui_story_1013_10130401_39_dialog_content = "มันดีกว่า! อิ่มแล้วกลับมามีชีวิตชีวาอีกครั้ง!",
  ui_story_1013_10130401_40_dialog_content = "ใช่ ฉันมีความสุขที่สุดเวลาทานอาหารเสมอ!",
  ui_story_1013_10130401_41_dialog_content = "เมื่อเราเติมพลังแล้ว เราก็ควรเริ่มงานของวัน",
  ui_story_1013_10130401_42_dialog_content = "เราควรจะช่วยกันต่อด้วย Battle Simulator ใช่ไหม?",
  ui_story_1013_10130401_43_dialog_content = "ได้. ตามที่นักวิทยาศาสตร์ที่ทำงานตลอดทั้งคืนได้ค้นพบฟังก์ชันใหม่!",
  ui_story_1013_10130401_44_dialog_content = "เราควรจะดูหรือไม่?",
  ui_story_1013_10130401_45_dialog_content = "เอาสิ!",
  ui_story_1013_10130401_46_dialog_content = "<color=#e8d9bb>ศูนย์วิจัยอิลลูมินา</color>",
  ui_story_1013_10130401_47_dialog_content = "สวัสดีตอนเช้า! ในที่สุดคุณสองคนก็มาถึงที่นี่",
  ui_story_1013_10130401_48_dialog_content = "แม่ทัพใหญ่?!",
  ui_story_1013_10130401_49_dialog_content = "คุณรอเราตลอดเวลานี้หรือไม่?",
  ui_story_1013_10130401_50_dialog_content = "ใช่. ฉันต้องการเห็นด้วยตัวเองว่า Battle Simulator ทำงานอย่างไร",
  ui_story_1013_10130401_51_dialog_content = "คุณอยู่ที่นี่ทั้งหมดเหรอ?",
  ui_story_1013_10130401_52_dialog_content = "เราได้จัดการอัปเกรด Battle Simulator แล้ว!",
  ui_story_1013_10130401_53_dialog_content = "ถูกตัอง! และเรายังมีชื่อที่อัปเกรดใหม่ทั้งหมดสำหรับมันด้วย—Battlefield Simulator!",
  ui_story_1013_10130401_54_option_content = "สนามรบ?",
  ui_story_1013_10130401_55_dialog_content = "แม้ว่าพยางค์พิเศษหนึ่งพยางค์จะไม่ฟังดูมากนัก แต่ความแตกต่างนั้นมีมากมายมหาศาล!",
  ui_story_1013_10130401_56_option_content = "ความแตกต่างอะไร?",
  ui_story_1013_10130401_57_dialog_content = "ใหญ่มาก!",
  ui_story_1013_10130401_58_dialog_content = "Battlefield Simulator อัปเดตตัวเองหลังจากอ่านข้อมูลที่นำมาจากโมดูลใหม่ของ Soroz",
  ui_story_1013_10130401_59_dialog_content = "ตอนนี้ การจำลองการต่อสู้ในประวัติศาสตร์ที่แม่นยำสามารถสร้างขึ้นใหม่จากบันทึกการต่อสู้โดยละเอียด!",
  ui_story_1013_10130401_60_dialog_content = "ไม่เพียงแค่ศัตรูเท่านั้น แต่ยังสามารถสร้างเวลาท้องถิ่น ภูมิประเทศ และแม้แต่สภาพอากาศได้อย่างสมบูรณ์แบบ",
