  ui_story_1013_10130701_62_dialog_content = "รอเดี๋ยวสิ",
  ui_story_1013_10130701_63_dialog_content = "มีบางอย่างกำลังคลานออกมาจากพื้น!",
  ui_story_1013_10130701_64_dialog_content = "<color=#e8d9bb>เสียงกรอบแกรบ—</color>",
  ui_story_1013_10130701_65_dialog_content = "ฟ่อ-!!!",
  ui_story_1013_10130701_66_dialog_content = "อ๊ะ ไม่นะ!",
  ui_story_1013_10130701_67_dialog_content = "(มันอยู่ที่นั่นเสมอ? ทำให้มันรอดพ้นจากภัยพิบัติได้หรือไม่?)",
  ui_story_1013_10130701_68_dialog_content = "(ฉันจะทำให้มันเสร็จ!)",
  ui_story_1013_10130702_1_dialog_content = "ฟ่อ-!!!",
  ui_story_1013_10130702_2_dialog_content = "ฉันไม่สามารถเอาชนะได้!",
  ui_story_1013_10130702_3_dialog_content = "ร่างกายของมันดูใหญ่ขึ้นเรื่อยๆ",
