  ui_story_1013_10131501_125_dialog_content = "Twilight คือการตั้งถิ่นฐานในภูมิภาค Aurora Ruins",
  ui_story_1013_10131501_126_dialog_content = "สถานที่นั้นซับซ้อนกว่าที่คุณคิด",
  ui_story_1013_10131501_127_dialog_content = "ที่ซับซ้อน?",
  ui_story_1013_10131501_128_dialog_content = "การเข้าถึงของสภาวิทยาศาสตร์ในภูมิภาคนั้นอนุญาตให้พวกเขาสังเกตการณ์เท่านั้น",
  ui_story_1013_10131501_129_dialog_content = "พวกเขาไม่สามารถทำอะไรได้มากไปกว่านั้น",
