  ui_story_1014_10140201_17_dialog_content = "...",
  ui_story_1014_10140201_18_dialog_content = "ยังไม่ดี เบเร็ตต้า?",
  ui_story_1014_10140201_19_dialog_content = "ขอโทษ เลดี้คาร์ลีน ฉันไม่มีความรู้เกี่ยวกับอุปกรณ์ประเภทนี้มากนัก",
  ui_story_1014_10140201_20_dialog_content = "หืมม?",
  ui_story_1014_10140201_21_dialog_content = "จังหวะเหมาะรอง",
  ui_story_1014_10140201_22_dialog_content = "ว่าไง? มีอะไรให้ฉันช่วยไหม",
  ui_story_1014_10140201_23_dialog_content = "ฉันกำลังคิดที่จะติดต่อกับกลุ่มอัศวินลูโม่ที่ประจำอยู่ที่ชายแดนเพื่อทำความเข้าใจสถานการณ์ในพื้นที่นั้น",
  ui_story_1014_10140201_24_dialog_content = "พวกเขาอยู่ที่นั่นมาหลายปีแล้ว และน่าจะช่วยเราได้",
  ui_story_1014_10140201_25_dialog_content = "สิ่งนี้มักจะถูกจัดการโดย City Lord เป็นความผิดของฉันเองที่ไม่ติดต่อล่วงหน้า",
