  ui_story_1014_10140201_33_dialog_content = "<color=#e8d9bb>Buzz—เสียงแตก—</color>",
  ui_story_1014_10140201_34_dialog_content = "อืม โอเค แล้วจะ... ปรับ power module ยังไงล่ะ!",
  ui_story_1014_10140201_35_dialog_content = "ตกลง! ควรจะไปตอนนี้ดี",
  ui_story_1014_10140201_36_dialog_content = "<color=#e8d9bb>Buzz—เสียงแตก—</color>",
  ui_story_1014_10140201_37_dialog_content = "อะฮ่าฮ่า! ในกรณีนั้น สิ่งเดียวที่เหลือคือ—",
