  ui_story_1014_10140402_25_dialog_content = "ขอโทษที่ทำให้ทุกคนรอ! ในที่สุดเราก็กลับมาสู่เส้นทางที่ดีได้แล้ว!",
  ui_story_1014_10140402_26_dialog_content = "กองกำลัง Illumina ใน Twilight กำลังรอต้อนรับคุณอยู่!",
  ui_story_1014_10140402_27_dialog_content = "?!",
  ui_story_1014_10140402_28_dialog_content = "แอ็กซีเลีย?! คุณตื่นแล้ว!",
  ui_story_1014_10140402_29_dialog_content = "เอ่อ พวกคุณแค่ดูฉันจัดการกับ Eclipsites พวกนั้นเหรอ?",
  ui_story_1014_10140402_30_dialog_content = "ก็จริงนะ",
  ui_story_1014_10140402_31_dialog_content = "คุณคิดอย่างไร? ฉันเจ๋งกว่านี้ไม่ใช่เหรอ ไม่ต้องพูดถึงแข็งแกร่งกว่าตอนที่พวกเราอยู่ที่สำนักงานใหญ่อีกเหรอ?",
  ui_story_1014_10140402_32_dialog_content = "อยากต่อยสักรอบไหม? มาดูกันว่าใครจะชนะในครั้งนี้!",
  ui_story_1014_10140402_33_dialog_content = "ไม่เป็นไรขอบคุณ.",
  ui_story_1014_10140402_34_dialog_content = "อ้อ ดูเหมือนคุณจะมีหุ่นยนต์ที่ไม่คุ้นเคยสี่ตัวอยู่ข้างๆ คุณเหรอ?",
  ui_story_1014_10140402_35_dialog_content = "พวกเขาคือ Cubic Trio",
  ui_story_1014_10140402_36_dialog_content = "เอ่อ โอเค แต่มีสี่—",
  ui_story_1014_10140402_37_dialog_content = "ผู้ชายตัวเล็กคนที่สี่ช่วยฉันยกแขนเสื้อขึ้น",
  ui_story_1014_10140402_38_dialog_content = "แปลกมาก! แต่ทำไม่เป็น!",
  ui_story_1014_10140402_39_dialog_content = "อย่างไรก็ตาม ฌอน Axelia คือสิ่งที่เรากำลังจะเสนอให้เป็นการแลกเปลี่ยนระหว่างการซื้อขาย",
  ui_story_1014_10140402_40_dialog_content = "อย่าให้เธอใช้พลังงานมากเกินไปในตอนนี้",
  ui_story_1014_10140402_41_dialog_content = "จริงเหรอเนี่ย!",
  ui_story_1014_10140402_42_dialog_content = "นั่นทำให้ฉันเป็นรุ่นพี่ของ Axelia เหรอ!",
  ui_story_1014_10140402_43_dialog_content = "คุณมีอะไรอยากจะถามฉันไหม",
  ui_story_1014_10140402_44_dialog_content = "ฉันสงสัยเกี่ยวกับโครงสร้างทางทหารในปัจจุบันของทไวไลท์",
  ui_story_1014_10140402_45_dialog_content = "อืม ฉันเป็นทหารราบมากกว่า ดังนั้น...",
  ui_story_1014_10140402_46_dialog_content = "ในกรณีนั้น มี Eclipsites แบบพิเศษรอบ Twilight หรือไม่?",
  ui_story_1014_10140402_47_dialog_content = "เอ่อ ฉันก็ไม่ค่อยแน่ใจเหมือนกัน...",
  ui_story_1014_10140402_48_dialog_content = "อย่างไรก็ตาม โปรดอย่าลังเลที่จะถามอะไรฉันอีก! เช่นเดียวกับที่ที่อาหารดีที่สุดอยู่ใน Twilight หรือประวัติศาสตร์ หรือจุดชมวิวที่ดีที่สุด...",
  ui_story_1014_10140402_49_dialog_content = "กดมันลง คุณจะ...",
  ui_story_1014_10140501_1_dialog_content = "<color=#e8d9bb>ชานเมืองสนธยา</color>",
  ui_story_1014_10140501_2_dialog_content = "Lady Carleen รายงานการลาดตระเวนก่อนหน้านี้ระบุว่า Twilight อยู่ข้างหน้า",
  ui_story_1014_10140501_3_dialog_content = "ลีโอและคนอื่นๆ น่าจะมาต้อนรับเราในไม่ช้าเช่นกัน เตรียมลงจอด PlayerName.",
  ui_story_1014_10140501_4_dialog_content = "<color=#e8d9bb>ตูม...</color>",
  ui_story_1014_10140501_5_dialog_content = "...?! เกิดอะไรขึ้นน่ะ?",
  ui_story_1014_10140501_6_dialog_content = "การระเบิด",
  ui_story_1014_10140501_7_dialog_content = "Axelia กลับไปที่ห้องชะงักงันของคุณ มันวุ่นวายที่นั่น",
