  ui_story_1014_10140501_15_dialog_content = "<color=#e8d9bb>ฟิ้วว—</color>",
  ui_story_1014_10140501_16_dialog_content = "มีบางอย่างผิดปกติ",
  ui_story_1014_10140501_17_dialog_content = "เร็ว! หาที่ลงจอด PlayerName.",
  ui_story_1014_10140501_18_dialog_content = "A-เอาล่ะ! นั่งให้แน่นนะทุกคน!",
  ui_story_1014_10140501_19_dialog_content = "ระหว่างทางมีสะดุดบ้างเล็กน้อย แต่เราก็ผ่านมันมาได้ ยินดีต้อนรับสู่ทไวไลท์!",
  ui_story_1014_10140501_20_dialog_content = "ตั้งอยู่บนพรมแดนแอสตร้า มีอากาศสบาย วิถีชีวิตที่เรียบง่ายและดั้งเดิม—",
  ui_story_1014_10140501_21_dialog_content = "ออกจากทาง! เคลื่อนย้ายไปมา! เอาล่ะ ให้ฉันผ่าน...",
  ui_story_1014_10140501_22_dialog_content = "ไอ ไอ ฝุ่นเยอะจัง!",
  ui_story_1014_10140501_23_dialog_content = "ฮ่าฮ่าฮ่า... ใช่แล้ว มันเกิดขึ้นบางครั้ง",
  ui_story_1014_10140501_24_dialog_content = "สวัสดี ฉันขอถามหน่อยได้ไหมว่าพวกคุณกำลังมุ่งหน้าไปทางไหน? มีอะไรให้ช่วยไหม?",
  ui_story_1014_10140501_25_dialog_content = "Twilight ยังห่างไกลจากที่นี่มากไหม?",
  ui_story_1014_10140501_26_dialog_content = "ตอนนี้เราอยู่ที่ชานเมืองแล้ว! พวกนาย... ต้องไม่ใช่คนแถวนี้",
  ui_story_1014_10140501_27_dialog_content = "ได้เลย ขอบคุณนะ!",
  ui_story_1014_10140501_28_dialog_content = "รอก่อน! หากคุณกำลังจะไป Twilight เหมือนกัน คุณอาจแท็กไปกับเราด้วย",
  ui_story_1014_10140501_29_dialog_content = "ขออภัย เราเหลือเวลาไม่มากแล้ว",
  ui_story_1014_10140501_30_dialog_content = "ฉันขอแนะนำให้คุณหาที่พักพิงโดยเร็ว",
  ui_story_1014_10140501_31_dialog_content = "ที่หลบภัย?",
  ui_story_1014_10140501_32_dialog_content = "คุณเห็นว่าท้องฟ้ากลายเป็นสีตลกได้อย่างไร? นั่นเป็นสัญญาณที่แน่นอนว่า <color=#FFB400>ออโรราสตอร์ม</color> กำลังมา!",
  ui_story_1014_10140501_33_dialog_content = "ถ้าคุณหาที่กำบังไม่ได้ในเร็วๆ นี้ เมื่อโดนโจมตีแล้ว จะไม่มีใครช่วยคุณได้",
  ui_story_1014_10140501_34_dialog_content = "ออโรราสตอร์ม...?",
  ui_story_1014_10140501_35_dialog_content = "ฉันเคยอ่านเกี่ยวกับเรื่องนี้ในหนังสือเท่านั้น แม้แต่นอร์ธแลนด์ที่มีแสงออโรร่าบ่อยครั้งก็แทบไม่เห็นปรากฏการณ์เช่นนี้",
  ui_story_1014_10140501_36_dialog_content = "มีเพียงผู้อยู่อาศัยที่อาศัยอยู่ในเขตชายแดนมาหลายชั่วอายุคนเท่านั้นที่ได้เห็นพวกเขา",
  ui_story_1014_10140501_37_dialog_content = "<color=#e8d9bb>ปี๊บ—ปี๊บ—</color>",
  ui_story_1014_10140501_38_dialog_content = "นั่นคือเสียงไซเรนเตือนของ Twilight!",
  ui_story_1014_10140501_39_dialog_content = "ฟังนะทุกคน ตามจังหวะของคุณ ไม่มีทางที่คุณจะไปถึง Twilight ได้ในวันนี้",
  ui_story_1014_10140501_40_dialog_content = "ฉันชื่อฌอน นายทหารชั้นผู้น้อยของกองกำลังอิลลูมินาที่ประจำการในทไวไลท์ ถ้าคุณจะเชื่อฉัน",
  ui_story_1014_10140501_41_dialog_content = "ฉันจะพาทุกคนไปหลบภัยในร่องลึกชั่วคราวได้!",
  ui_story_1014_10140501_42_dialog_content = "เชื่อใจคุณมากไหม คุณเป็นแค่เด็กกลุ่มหนึ่ง!",
  ui_story_1014_10140501_43_dialog_content = "ใช่ แต่เราไม่มีวิธีป้องกันตัวเองเลยใช่ไหม หากเราถูกโจมตีโดย Eclipsites อีกครั้ง...",
