  ui_story_1014_10140701_68_dialog_content = "ถอยหลังหน่อย รอง อย่าปล่อยให้พวกเขาเข้าใกล้เกินไป",
  ui_story_1014_10140701_69_dialog_content = "เวลาแบบนี้จะถอยหลังไม่ได้แล้ว! ด้านขวาของคุณ!",
  ui_story_1014_10140701_70_dialog_content = "ว้าว! เยอะจัง... ทุกคนอยู่ไหน? ฉันอยู่ที่ไหน?!",
  ui_story_1014_10140701_71_dialog_content = "โอ้ถ้า Axelia อยู่ที่นี่เท่านั้น",
  ui_story_1014_10140701_72_dialog_content = "เฮ้! ระวังคำพูดของคุณ! ฉันยังไม่พออีกเหรอ!",
  ui_story_1014_10140701_73_dialog_content = "ทุกคน ไปข้างหลังฉัน! อย่าหนี!",
  ui_story_1014_10140701_74_dialog_content = "ฉันจะปกป้องคุณ...",
  ui_story_1014_10140701_75_dialog_content = "อ๊าก!! Eclipsites มุ่งตรงมาหาเรา!",
  ui_story_1014_10140701_76_dialog_content = "หืม? ที่ไหนเหรอ?",
  ui_story_1014_10140701_77_dialog_content = "ที่นี่! พวกเขาอยู่ที่นี่!",
  ui_story_1014_10140701_78_dialog_content = "รอก่อน ฉันกำลังมา!",
  ui_story_1014_10140701_79_dialog_content = "ก๊าาาซ!",
  ui_story_1014_10140701_80_dialog_content = "... พวกเขาอยู่ทุกที่!",
  ui_story_1014_10140701_81_dialog_content = "PlayerName! ช่วยบอกตำแหน่งของศัตรูหน่อยได้ไหม?",
  ui_story_1014_10140701_82_dialog_content = "ฉันไม่สามารถรู้ได้ว่าพวกเขาอยู่ที่ไหน...",
  ui_story_1014_10140701_83_dialog_content = "<size=45>ทุกคน! ออกไปจากที่นี่!!</size>",
  ui_story_1014_10140701_84_dialog_content = "ฮะ? และเราตั้งใจจะไปที่ไหน?",
  ui_story_1014_10140701_85_dialog_content = "ไม่รู้สิ แต่... ยิ่งห่างยิ่งดี!",
  ui_story_1014_10140701_86_dialog_content = "<color=#e8d9bb>ดังก้อง—ดังก้อง—</color>",
  ui_story_1014_10140701_87_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_1014_10140701_88_dialog_content = "ว้าว... ผู้ชายคนนี้ไร้สาระ",
  ui_story_1014_10140701_89_dialog_content = "อย่ายืนอยู่ตรงนั้น!",
  ui_story_1014_10140701_90_dialog_content = "<anim type=Shake><size=50>กรี้ด!</size></anim>",
  ui_story_1014_10140701_91_dialog_content = "*ไอ* ขบวนแตก... ทุกคนโอเคไหม?",
  ui_story_1014_10140701_92_dialog_content = "PlayerName เตือนทุกคนเพื่อไม่ให้ใครถูกจับได้",
  ui_story_1014_10140701_93_dialog_content = "ฉันเป็นห่วงพลเรือนมากกว่า",
  ui_story_1014_10140701_94_dialog_content = "หากการก่อตัวแตก พวกเขาก็มีแนวโน้มที่จะถูกโจมตี",
  ui_story_1014_10140701_95_dialog_content = "คุณถูก! เราควรไปช่วยพวกเขา!",
  ui_story_1014_10140701_96_dialog_content = "เราจะออกไปจากที่นี่ได้ไหม?",
  ui_story_1014_10140701_97_dialog_content = "ช่วยด้วย!",
  ui_story_1014_10140701_98_dialog_content = "Eclipsites พวกมันอยู่ทุกที่!",
  ui_story_1014_10140701_99_dialog_content = "พวกเขาไปไหน? คนที่มาช่วยเรา?!",
  ui_story_1014_10140701_100_dialog_content = "ใจเย็นๆ นะทุกคน! มาหาฉันสิ ฉันจะปกป้องเธอเอง!",
  ui_story_1014_10140701_101_dialog_content = "PlayerName,ศัตรู...",
  ui_story_1014_10140701_102_dialog_content = "พวกเขาอยู่ทุกที่ในขณะนี้ สนามรบทั้งหมดกำลังคลานไปพร้อมกับพวกเขา!",
  ui_story_1014_10140701_103_dialog_content = "ไม่มีทางที่พลเรือนจะรวมกลุ่มกันได้ Eclipsites ทำให้ฝูงชนกระจัดกระจาย",
  ui_story_1014_10140701_104_dialog_content = "S-แล้วตอนนี้เราจะทำอย่างไร?",
  ui_story_1014_10140701_105_dialog_content = "ฉันกำลังคิดอยู่...",
  ui_story_1014_10140701_106_dialog_content = "ไม่ใช่แค่พวกเขา แต่พวกเราก็เช่นกัน",
  ui_story_1014_10140701_107_dialog_content = "สัตว์ประหลาดที่พวกเขาเรียกว่า Cerritus จะโจมตีอย่างต่อเนื่อง และเราจะอยู่รอดได้ไม่นานในทะเลแห่ง Eclipsites",
  ui_story_1014_10140701_108_dialog_content = "แม่นแล้ว...มาอีกแล้ว...",
  ui_story_1014_10140701_109_dialog_content = "คุณเห็นทางออกไหม Yingel? คุณมักจะเป็นคนที่ฉลาดที่สุดในห้อง",
  ui_story_1014_10140701_110_dialog_content = "ลืมเรื่องพลเรือน ถอยไปข้างหลังอัศวินไอรอนธร",
  ui_story_1014_10140701_111_dialog_content = "หา? แต่...",
  ui_story_1014_10140701_112_dialog_content = "ลีโอพูดถูก เราต้องเผชิญหน้ากับมัน นี่คือพรมแดน และเราไม่แข็งแกร่งพอ",
  ui_story_1014_10140701_113_dialog_content = "แม้ว่าเราจะต่อสู้ต่อไป พลเรือนเหล่านั้นก็ยังคงถูกไล่ออกทีละคนในความสับสนวุ่นวาย",
  ui_story_1014_10140701_114_dialog_content = "เราไม่สามารถช่วยชีวิตทุกคนได้",
  ui_story_1014_10140701_115_dialog_content = "...",
  ui_story_1014_10140701_116_dialog_content = "เราทำดีที่สุดแล้ว PlayerName. คุณต้องเข้าใจสถานการณ์ของเรา",
  ui_story_1014_10140701_117_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1014_10140701_118_dialog_content = "คุณได้ยินไหม? สัตว์ประหลาดกำลังมา",
  ui_story_1014_10140701_119_dialog_content = "ว-เรา...",
  ui_story_1014_10140701_120_dialog_content = "ถ้าเธอไม่ตัดสินใจ ฉันจะพาเธอไปกับฉัน",
  ui_story_1014_10140701_121_dialog_content = "!!!",
  ui_story_1014_10140701_122_dialog_content = "หาที่กำบังให้หน่อย คุณลูโมโพลิส เรากำลังถอนตัว",
  ui_story_1014_10140701_123_dialog_content = "แต่กลับ...",
  ui_story_1014_10140701_124_dialog_content = "ฉันสัญญา! ฉันบอกว่าฉันจะปกป้องพวกเขา...",
  ui_story_1014_10140701_125_dialog_content = "จากนั้นให้การเติบโตของคุณเริ่มต้นด้วยคำสัญญาที่คุณรักษาไม่ได้",
  ui_story_1014_10140701_126_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1014_10140701_127_dialog_content = "ฉันขอโทษ แต่อย่างน้อยฉันก็ต้องพยายาม ฉันไม่สามารถทำลายคำพูดของฉันได้อย่างง่ายดาย",
  ui_story_1014_10140701_128_dialog_content = "เพราะฉันเลือกที่จะเรียกตัวเองว่าอัศวิน",
  ui_story_1014_10140701_129_dialog_content = "หนอย...!",
  ui_story_1014_10140701_130_dialog_content = "เบเร็ตต้า!!",
  ui_story_1014_10140701_131_dialog_content = "ดังนั้นคุณจึงเรียกตัวเองว่าอัศวิน ขอบคุณพระนามที่ทำให้ท่านชอบธรรมและบริสุทธิ์",
  ui_story_1014_10140701_132_dialog_content = "หา?",
  ui_story_1014_10140701_133_dialog_content = "กรรรรรรรรรร!!",
  ui_story_1014_10140701_134_dialog_content = "Cerritus ถูก Luminatics ขับไล่! นั่นก็คือ-",
  ui_story_1014_10140701_135_dialog_content = "นี่เป็นครั้งแรกที่ฉันได้พบกับอัศวินเช่นคุณ",
  ui_story_1014_10140701_136_dialog_content = "R-จริงเหรอ? ฉันแค่ทำในสิ่งที่อัศวินคาดหวังเท่านั้น",
  ui_story_1014_10140701_137_dialog_content = "แต่อัศวินคนอื่นไม่เหมือนคุณ",
  ui_story_1014_10140701_138_dialog_content = "คุณสวยมาก... คุณเป็นนางฟ้าแบบไหน?",
  ui_story_1014_10140701_139_dialog_content = "ฉันก็ปรารถนาจะพบทูตสวรรค์มานานแล้ว แต่อนิจจา... พวกเขายังมาไม่ถึงฉันเลย",
  ui_story_1014_10140701_140_dialog_content = "ดังนั้นมนุษย์ต้องเพียงพอสำหรับความพยายามบางอย่าง",
  ui_story_1014_10140701_141_dialog_content = "ชาวบ้านทั้งหลายจงตามแสงสว่างมาหาเราเถิด",
  ui_story_1014_10140701_142_dialog_content = "White Night ขึ้นสูง แสงสว่างจะชำระล้างความชั่วร้ายทั้งหมดและนำดวงวิญญาณทั้งหมดกลับบ้าน",
  ui_story_1014_10140701_143_dialog_content = "ดู! Eclipsites กลัวแสงที่นั่น!",
  ui_story_1014_10140701_144_dialog_content = "เร็ว! ไปที่นั่นกันเถอะ! เราจะปลอดภัย!",
  ui_story_1014_10140701_145_dialog_content = "ฉันได้ยินเกี่ยวกับเธอ! ต้องเป็นเธอ—นักบุญหญิงแห่งสนธยา!",
  ui_story_1014_10140701_146_dialog_content = "อัศจรรย์! พลเรือนสามารถจัดกลุ่มอีกครั้ง!",
  ui_story_1014_10140701_147_dialog_content = "Eclipsites กำลังซ่อนตัวจากแสงที่แผ่ออกมาจากร่างของหญิงสาว ดูเหมือนเราจะต้องตามไปถ้าอยากจะออกไปจากที่นี่!",
  ui_story_1014_10140701_148_dialog_content = "ใช่ฉันเห็นด้วย ดังนั้น เปลี่ยนแผน: ตอนนี้เราล้อมรอบผู้หญิงคนนั้นและพยายามอย่างดีที่สุดเพื่อปกปิดการล่าถอยของพลเรือน",
  ui_story_1014_10140701_149_dialog_content = "คัดลอกมา ผู้การหญิงเกิล!",
  ui_story_1014_10140701_150_dialog_content = "อย่าเรียกฉันว่า",
  ui_story_1014_10140701_151_dialog_content = "กัปตัน! พวกเขากำลังจะกลับมา! กับพลเรือนเหล่านั้น!",
  ui_story_1014_10140701_152_dialog_content = "ฉันเห็น. เปิดขบวนอย่างระมัดระวังและเข้าทางด้านหลัง",
  ui_story_1014_10140701_153_dialog_content = "ครับ!",
  ui_story_1014_10140701_154_dialog_content = "มันคืออัศวินไอรอนธร! ขอบคุณพระเจ้า! พวกเราปลอดภัยแล้ว",
  ui_story_1014_10140701_155_dialog_content = "ก้าวให้ทัน! ใครจะผ่อนคลายได้อย่างไรจนกว่าเราจะอยู่ใน Twilight และออกจากถิ่นทุรกันดารที่ถูกทำลายนี้?",
  ui_story_1014_10140701_156_dialog_content = "ทำได้ดีมาก กัปตันลีโอ",
  ui_story_1014_10140701_157_dialog_content = "คุณกำลังประชดประชันใช่ไหม <color=#FFB400>ความศักดิ์สิทธิ์ของคุณ</color>?",
  ui_story_1014_10140701_158_dialog_content = "ไม่เลย. ฉันไม่ได้เป็นเด็กขนาดนั้นและรู้ดีถึงสถานการณ์ของคุณ",
  ui_story_1014_10140701_159_dialog_content = "หลายคนหนีไปที่ Twilight เป็นไปไม่ได้ที่จะปกป้องพวกเขาเช่นเดียวกับเมืองของเรา",
  ui_story_1014_10140701_160_dialog_content = "ทุก Eclipsite ที่สามารถผ่านได้คุณจะพุ่งตรงเข้าสู่ Twilight โดยธรรมชาติแล้ว คุณไม่สามารถออกจากแนวรับได้",
  ui_story_1014_10140701_161_dialog_content = "ขอบคุณสำหรับการให้อภัยของคุณ ฉันรู้สึกดีขึ้นแล้วตอนนี้.",
  ui_story_1014_10140701_162_dialog_content = "ใบหน้าของคุณไม่แสดงมัน นี่เป็นประเด็นศักดิ์ศรีที่คุณพูดหรือไม่?",
  ui_story_1014_10140701_163_dialog_content = "ไม่ ไม่จริง ฉันแค่อิจฉาคุณที่คุณสามารถทำสิ่งที่ฉันทำไม่ได้ได้อย่างง่ายดาย",
  ui_story_1014_10140701_164_dialog_content = "ถึงตาคุณแล้ว ที่จะทำสิ่งที่ฉันทำไม่ได้",
  ui_story_1014_10140701_165_dialog_content = "แน่นอน. นำพลเรือนไปทางด้านหลังและปล่อยให้สนามรบเป็นของฉัน",
  ui_story_1014_10140701_166_dialog_content = "ไม่มีคราสเดียวที่จะผ่านอัศวินไอรอนธอร์นไปได้",
  ui_story_1014_10140701_167_dialog_content = "ฉันศรัทธาในตัวคุณ.",
  ui_story_1014_10140701_168_dialog_content = "ต่อไป ช่วงเวลาสั้น ๆ ของเราที่มีร่วมกันสิ้นสุดลงแล้ว",
  ui_story_1014_10140701_169_dialog_content = "ดูเหมือนว่าเราจะเป็นเช่นนี้เสมอ การแปรงไหล่ในการผ่านสนามรบ",
  ui_story_1014_10140701_170_dialog_content = "ใช่. เสมอ.",
  ui_story_1014_10140701_171_dialog_content = "เรามักจะวิ่งสวนทางกันเสมอ",
  ui_story_1014_10140701_172_dialog_content = "เพื่อนของเราใกล้เข้ามาแล้ว ฉันสามารถได้ยินมัน",
  ui_story_1014_10140701_173_dialog_content = "อัศวินเหล็ก! รอ! ใครเป็นคนให้เตะคนตัวโตอย่างเท่าเทียมกัน!",
  ui_story_1014_10140701_174_dialog_content = "<size=40>ฉัน!!</size>",
  ui_story_1014_10140701_175_dialog_content = "<size=40>ฉันด้วย!</size>",
  ui_story_1014_10140701_176_dialog_content = "สนใจเข้าร่วมกับเราไหม? ถ้ายังมีแรงสู้ต่อแน่นอน",
  ui_story_1014_10140701_177_dialog_content = "อย่างแน่นอน! ถึงเวลาชดใช้สิ่งที่เราเพิ่งประสบมา 10 เท่า!",
  ui_story_1014_10140701_178_dialog_content = "ฮ่าฮ่าฮ่าฮ่า! ฉันชอบจิตวิญญาณนั้น!",
  ui_story_1014_10140701_179_dialog_content = "ด้วยความช่วยเหลือของคุณ เป้าหมายของเราจะไม่เป็นเพียงการป้องกันเท่านั้น",
  ui_story_1014_10140701_180_dialog_content = "คืนนี้ ฉันอยากจะแขวนธงของเราไว้บนเขาของมัน!",
  ui_story_1014_10140702_1_dialog_content = "<anim type=Shake><size=45>กร๊ากกก!!! กราาาาาา—</size></anim>",
  ui_story_1014_10140702_2_dialog_content = "พักผ่อนเถอะไอ้ตัวโต",
  ui_story_1014_10140702_3_dialog_content = "ว้าย...ในที่สุดก็ลงแล้ว สิ่งนั้นแข็งแกร่งเป็นบ้า",
  ui_story_1014_10140702_4_dialog_content = "อย่าเพิ่งพักผ่อน การโจมตีของ Eclipsites ยังคงดำเนินต่อไป และเราจะต้องดูให้จบ",
  ui_story_1014_10140702_5_dialog_content = "แน่นอน! แต่อย่างน้อยความดันก็ดับลง",
  ui_story_1014_10140702_6_dialog_content = "เอ้ย ในที่สุดเราก็ออกจากม็อบ Eclipsite ได้แล้ว",
  ui_story_1014_10140702_7_dialog_content = "แล้วเซอร์ริทัสล่ะ? ไอ้ใหญ่นั่นหายไปไหน?",
  ui_story_1014_10140702_8_dialog_content = "...",
  ui_story_1014_10140702_9_dialog_content = "ขอขอบคุณ! โอ้ ขอบคุณ ท่านผู้บริสุทธิ์!",
  ui_story_1014_10140702_10_dialog_content = "คุณช่วยพวกเราทุกคน!",
