  ui_story_1014_10140801_211_dialog_content = "แน่นอน ตราบใดที่คุณทำให้โซรอซฟื้นคืนสติได้",
  ui_story_1014_10140801_212_dialog_content = "เอาล่ะ มาเริ่มกันเลย!",
  ui_story_1014_10140801_213_dialog_content = "ฉันขออยู่ดูได้ไหม",
