  ui_story_1014_10140801_221_dialog_content = "เอาล่ะ อย่าหักโหมกับตัวเอง",
  ui_story_1014_10140801_222_dialog_content = "เข้าใจแล้วครับ",
  ui_story_1014_10140801_223_dialog_content = "<color=#e8d9bb>กริ๊ง กริ๊ง!</color>",
  ui_story_1014_10140801_224_dialog_content = "เฮ้ ตื่นเถอะ คาเลสไทต์",
