  ui_story_1014_10140801_246_dialog_content = "อะไรนะ!",
  ui_story_1014_10140801_247_dialog_content = "เราก็ต้องหามันให้เจอ? มันอยู่ที่ไหน?",
  ui_story_1014_10140801_248_dialog_content = "<anim type=Shake>เวลาของฉันใกล้จะหมดลงแล้ว...</anim>",
