  ui_story_1014_10141102_34_dialog_content = "Axelia น่าประทับใจจริงๆ",
  ui_story_1014_10141102_35_dialog_content = "เธออาจจะคว้าอันดับหนึ่งในการจัดอันดับบุคคลหากเธอเข้าร่วมการฝึกร่วมทางทหาร!",
  ui_story_1014_10141102_36_dialog_content = "คุณรู้จักการฝึกร่วมทางทหารหรือไม่?",
  ui_story_1014_10141102_37_dialog_content = "ใช่ Reinhardt บอกฉันเกี่ยวกับพวกเขาก่อนหน้านี้",
  ui_story_1014_10141102_38_dialog_content = "เธอยังบอกด้วยว่าเธอตั้งหน้าตั้งตารอที่จะได้ดวลกับแชมป์เปี้ยน",
  ui_story_1014_10141102_39_dialog_content = "ฟังดูเหมือนสิ่งที่เธอต้องการทำ",
  ui_story_1014_10141102_40_dialog_content = "ฉันตั้งตารอที่จะได้เห็นเธอต่อสู้กับคนอย่าง Axelia ในงานนี้ด้วย",
  ui_story_1014_10141102_41_dialog_content = "แน่นอน ถ้ามีโอกาส ฉันอยากจะชกกับเลดี้ คาร์ลีน แชมป์เก่า",
  ui_story_1014_10141102_42_dialog_content = "ช่างโอหังนัก!",
  ui_story_1014_10141102_43_dialog_content = "ไม่เป็นไร",
  ui_story_1014_10141102_44_dialog_content = "ฉันจะเข้าร่วมในกิจกรรมต่อไป",
  ui_story_1014_10141102_45_dialog_content = "ฉันหวังว่าจะได้ต่อสู้กับคุณ ลีโอ",
  ui_story_1014_10141102_46_dialog_content = "มันเป็นข้อตกลง.",
  ui_story_1014_10141102_47_dialog_content = "คุณลงทะเบียนสำหรับกิจกรรมด้วยหรือไม่ ลีโอ?",
  ui_story_1014_10141102_48_dialog_content = "ได้สิ",
  ui_story_1014_10141102_49_dialog_content = "ชาวออโรเรียนทุกคนมีสิทธิ์ได้รับ",
  ui_story_1014_10141102_50_dialog_content = "ฉันจะไปทดสอบตัวเองกับสิ่งที่ดีที่สุดทั่วทั้ง Astra ไม่ว่ามันจะอยู่ไกลแค่ไหนก็ตาม",
  ui_story_1014_10141102_X50_dialog_content = "<color=#e8d9bb>ลึกลงไปในซากปรักหักพังของแสงออโรรา</color>",
  ui_story_1014_10141102_51_dialog_content = "(เรามาไกลกันแล้วนะ ดูเหมือนทริปนี้จะจบเร็ว)",
  ui_story_1014_10141102_52_dialog_content = "(แต่ก็ยังไม่เห็น Forsakin นะ... การสันนิษฐานของผมอาจผิดหรือเปล่า?)",
  ui_story_1014_10141102_53_dialog_content = "(ไม่ วัตถุประสงค์ของเธอชัดเจนมาโดยตลอด และ PlayerName เป็นเหยื่อที่ดีที่สุด)",
  ui_story_1014_10141102_54_dialog_content = "(ฉันไม่ผิด สิ่งที่ฉันทำได้ตอนนี้คือรอ)",
  ui_story_1014_10141102_55_dialog_content = "Yingel ทำไมคุณหยุด? คุณได้รับบาดเจ็บหรือไม่?",
  ui_story_1014_10141102_56_dialog_content = "ฮะ...? ไม่ ฉันโอเค แค่สงสัยว่าทำไมมี Eclipsites เยอะจัง",
  ui_story_1014_10141102_57_dialog_content = "ขออนุญาตแทรก...",
  ui_story_1014_10141102_58_dialog_content = "เป้าหมายของภารกิจนี้คือช่วย PlayerName ค้นหาส่วนประกอบของ Colossus",
  ui_story_1014_10141102_59_dialog_content = "จากที่ฉันรู้ เราไม่น่าจะอยู่ห่างจากยักษ์ใหญ่โบราณ",
  ui_story_1014_10141102_60_dialog_content = "เดินหน้ากันต่อไปดีไหม?",
  ui_story_1014_10141102_61_dialog_content = "ใช่ คุณโจเซลีนพูดถูก",
  ui_story_1014_10141102_62_dialog_content = "ที่นี่ให้ฮีบี้จี๊บเหมือนมีคนแอบดูเราอยู่...",
  ui_story_1014_10141102_63_dialog_content = "เราควรได้รับส่วนที่เราต้องการและกลับไปที่ Twilight!",
  ui_story_1014_10141102_64_dialog_content = "<color=#e8d9bb>ที่ไหนสักแห่งนอกซากปรักหักพังออโรรา</color>",
  ui_story_1014_10141102_65_dialog_content = "(Eclipsian) กลิ่นแห่งความปรารถนาของพวกเขากำลังเข้าใกล้ยักษ์ใหญ่",
  ui_story_1014_10141102_66_dialog_content = "(Eclipsian) วัตถุนั้นอยู่ใน Colossus ได้ไหม?",
  ui_story_1014_10141102_67_dialog_content = "(Eclipsian) เราควรย้ายเข้าไปเดี๋ยวนี้ ท่าน Asmodeus?",
  ui_story_1014_10141102_68_dialog_content = "(Eclipsian) ให้ความปรารถนาของพวกเขาเข้ามาใกล้ ใกล้เข้ามา...",
  ui_story_1014_10141102_69_dialog_content = "(Eclipsian) ความปรารถนาของผู้ทรยศ Caelesite จะเป็นสัญญาณนำทาง",
  ui_story_1014_10141102_70_dialog_content = "(Eclipsian) เราต้องการรอเท่านั้น",
  ui_story_1014_10141201_1_dialog_content = "ยักษ์ใหญ่อยู่ข้างหน้า ถนอมดวงตาของคุณ",
  ui_story_1014_10141201_2_dialog_content = "ฉันอดใจรอยักษ์ใหญ่จากยุคโบราณไม่ไหวแล้ว...",
  ui_story_1014_10141201_3_dialog_content = "<size=45>มันใหญ่มาก!</size>",
  ui_story_1014_10141201_4_dialog_content = "ขนาดเกินความคาดหมายของฉันโดยสิ้นเชิง!",
  ui_story_1014_10141201_5_dialog_content = "ขนาดของมันถือว่าใหญ่ที่สุดในบรรดาโคลอสซีที่ค้นพบ",
  ui_story_1014_10141201_6_dialog_content = "กองทหารของสหพันธ์อิลลูมินาที่ประจำการอยู่ในทไวไลท์ได้ศึกษายักษ์ใหญ่นี้และได้รับข้อมูลที่มีค่ามากมาย",
  ui_story_1014_10141201_7_dialog_content = "ข้อมูลประเภทใด",
  ui_story_1014_10141201_8_dialog_content = "ข้อมูลเกี่ยวกับวิธีการสร้างอุปกรณ์บางอย่าง เช่น พิมพ์เขียวบางส่วนสำหรับระบบการแพทย์ของมัน",
  ui_story_1014_10141201_9_dialog_content = "การค้นพบอื่นใด เช่น ข้อมูลความทรงจำ หรือข้อความโบราณของ Caelesite?",
  ui_story_1014_10141201_10_dialog_content = "ฉันเกรงว่าจะตอบไม่ได้เนื่องจากเป็นข้อมูลลับ",
  ui_story_1014_10141201_11_dialog_content = "อย่างไรก็ตาม เนื่องจากอุบัติเหตุในปฏิบัติการ Colossus จึงไปต่อ <color=#FFB400>อาละวาด</color> ครั้งหนึ่ง.",
  ui_story_1014_10141201_12_dialog_content = "เหตุการณ์ดังกล่าวทำให้พื้นที่ภายในหลายแห่งบน Colossus ไม่สามารถเข้าถึงได้",
  ui_story_1014_10141201_13_dialog_content = "หลังจากนั้นก็ถูกกำหนดให้เป็นวัตถุที่มีความเสี่ยงสูงและมีมูลค่าต่ำ เช่นเดียวกับซากปรักหักพังออโรร่าที่อยู่",
  ui_story_1014_10141201_14_dialog_content = "เจ้าหน้าที่ Ulysses อนุญาติให้คณะสำรวจนี้เพียงเพราะคุณอยู่ในนั้น",
  ui_story_1014_10141201_15_dialog_content = "เพราะฉันเป็น Caelestite?",
  ui_story_1014_10141201_16_dialog_content = "ถูกต้อง",
  ui_story_1014_10141201_17_dialog_content = "Caelestites สามารถนำร่อง Colossi ดังนั้นเราอาจค้นพบสิ่งที่เป็นไปไม่ได้",
  ui_story_1014_10141201_18_dialog_content = "...ไปกันต่อครับ",
  ui_story_1014_10141201_19_dialog_content = "เราควรเข้าไปข้างในไหม?",
  ui_story_1014_10141201_20_dialog_content = "ระวังตัวด้วยนะ",
  ui_story_1014_10141201_21_dialog_content = "ฉันเห็นร่องรอยของกิจกรรม Eclipsite",
  ui_story_1014_10141201_22_dialog_content = "มี Eclipsites จำนวนมากใน Colossus นี้",
  ui_story_1014_10141201_23_dialog_content = "ไม่ว่าจะมีกี่ตัว ฉันก็ต้องได้ข้อมูลมา",
  ui_story_1014_10141201_24_dialog_content = "เพื่อประโยชน์ของโซรอซ",
  ui_story_1014_10141201_25_dialog_content = "ที่นี่กว้างขวางมาก",
  ui_story_1014_10141201_26_dialog_content = "นอกจาก Eclipsites แล้ว ก็ไม่มีร่องรอยอื่นใดอีก",
  ui_story_1014_10141201_27_dialog_content = "Colossus ของคุณมีห้องกว้างขวางแบบนี้ไหม PlayerName?",
  ui_story_1014_10141201_28_option_content = "แน่นอนสิ",
  ui_story_1014_10141201_29_dialog_content = "ห้องโดยสารของ Soroz มีขนาดใหญ่มาก คุณสามารถวิ่งเหยาะๆ ได้โดยไม่มีปัญหา",
  ui_story_1014_10141201_30_dialog_content = "น่าประทับใจมาก!",
  ui_story_1014_10141201_31_option_content = "ไม่",
  ui_story_1014_10141201_32_dialog_content = "ห้องและโถงทางเดินใน Soroz นั้นกว้างขวาง แต่โดยปกติแล้วจะมีผู้คนจำนวนมากบนเรือ",
  ui_story_1014_10141201_33_dialog_content = "จึงทำให้รู้สึกโล่งน้อยกว่าที่เป็นอยู่",
  ui_story_1014_10141201_34_dialog_content = "มีเหตุผล!",
  ui_story_1014_10141201_35_dialog_content = "มีประตูอยู่ข้างหน้า",
  ui_story_1014_10141201_36_dialog_content = "คล้ายกับประตูที่นำไปสู่ห้องต่างๆ บนโซรอซ",
  ui_story_1014_10141201_37_dialog_content = "ประตูนี้ควรนำไปสู่สะพาน",
  ui_story_1014_10141201_38_dialog_content = "ดูเหมือนปิดสนิทไม่มีที่จับหรือตัวล็อค...",
  ui_story_1014_10141201_39_dialog_content = "เราจะเปิดได้อย่างไร",
  ui_story_1014_10141201_40_dialog_content = "ประตูทุกบานบน Soroz เปิดด้วยกระแสจิต",
  ui_story_1014_10141201_41_dialog_content = "ให้ฉันลองด้วยอันนี้",
  ui_story_1014_10141201_42_option_content = "บูสต์พลัง!",
  ui_story_1014_10141201_43_dialog_content = "<color=#e8d9bb>อือออออ...</color>",
  ui_story_1014_10141201_44_dialog_content = "<color=#e8d9bb>ตรวจพบผู้เยี่ยมชม Caelestite ที่ไม่ได้ลงทะเบียน</color>",
  ui_story_1014_10141201_45_dialog_content = "นี่เป็นระบบหลักของ Colossus นี้หรือไม่? มันฟังดูแข็งมาก",
  ui_story_1014_10141201_46_dialog_content = "เช่นเดียวกับ Soroz ที่ไม่มีบุคลิก ...",
  ui_story_1014_10141201_47_dialog_content = "<color=#e8d9bb>กรุณาลงทะเบียนด้วยตัวคุณเอง</color>",
  ui_story_1014_10141201_48_dialog_content = "ชื่อของฉันคือ PlayerNameฉันเป็นชาวคาเลสไทต์",
  ui_story_1014_10141201_49_dialog_content = "<color=#e8d9bb>ผู้ใช้ที่ไม่ได้ลงทะเบียนเปลี่ยนเป็น PlayerName.</color>",
  ui_story_1014_10141201_50_dialog_content = "<color=#e8d9bb>คุณได้รับสิทธิ์เข้าถึง Naviduz อย่างเต็มรูปแบบ</color>",
  ui_story_1014_10141201_51_dialog_content = "<color=#FFB400>นาวิดุซ</color>...? นั่นคือหนึ่งใน Colossi ตั้งแต่สมัยโบราณ!",
  ui_story_1014_10141201_52_dialog_content = "เข้าเต็มรึยัง ?! นั่นเป็นเรื่องง่าย!",
  ui_story_1014_10141201_53_dialog_content = "<color=#e8d9bb>โปรโตคอลการเข้าถึงของ Naviduz เป็นไปตามการอนุญาตที่กำหนดโดยนักบินทุกคน</color>",
  ui_story_1014_10141201_54_dialog_content = "<color=#e8d9bb>\"ต่ำกว่า 100 ปี ผู้ดูแลระบบเท่านั้นที่จะได้รับสิทธิ์เข้าถึงแบบเต็ม\"</color>",
  ui_story_1014_10141201_55_dialog_content = "<color=#e8d9bb>\"มากกว่า 100 ปี แต่ไม่ถึง... ปี เข้าถึงได้เต็มที่... ชาวคาเลสทั้งหมด\"</color>",
  ui_story_1014_10141201_56_dialog_content = "<color=#e8d9bb>\"เกิน... ปี แต่ไม่เกิน... ปี เข้าถึงได้เต็มที่... สิ่งมีชีวิตทั้งหมด\"</color>",
  ui_story_1014_10141201_57_dialog_content = "<color=#e8d9bb>ตามโปรโตคอล Naviduz กำลังให้สิทธิ์การเข้าถึงแก่ Caelestites ทั้งหมดอย่างเต็มที่</color>",
  ui_story_1014_10141201_58_dialog_content = "รอนานขนาดนั้นเลยเหรอ? ... ฉันเสียใจ.",
  ui_story_1014_10141201_59_dialog_content = "<color=#e8d9bb>บุคลิกของ Naviduz ถูกระงับ ไม่สามารถเข้าใจความหมายของคำว่า \"ฉันขอโทษ\"</color>",
  ui_story_1014_10141201_60_dialog_content = "<color=#e8d9bb>ทุกสิ่งบน Naviduz เป็นของขวัญสำหรับชาว Caelesti ในอนาคต</color>",
  ui_story_1014_10141201_61_dialog_content = "บุคลิกภาพของคุณถูกระงับ? ทำไม",
  ui_story_1014_10141201_62_dialog_content = "<color=#e8d9bb>บุคลิกภาพมีค่าใช้จ่ายเพิ่มเติมในการรักษา</color>",
  ui_story_1014_10141201_63_dialog_content = "<color=#e8d9bb>เพื่อให้แน่ใจว่า Naviduz จะสามารถรักษาและส่งต่อข้อมูลทั้งหมดไปยัง Caelestites ที่อาจพบ Colossus...</color>",
  ui_story_1014_10141201_64_dialog_content = "<color=#e8d9bb>Naviduz เลือกที่จะระงับบุคลิกภาพและเริ่มโหมดการอนุรักษ์</color>",
  ui_story_1014_10141201_65_dialog_content = "ระบบและข้อมูลบุคลิกภาพของคุณยังทำงานอยู่หรือไม่?",
  ui_story_1014_10141201_66_dialog_content = "<color=#e8d9bb>เรียกใช้การวินิจฉัยตนเอง</color>",
  ui_story_1014_10141201_67_dialog_content = "<color=#e8d9bb>\"ระบบควบคุมหลัก กำลังทำงาน ความสมบูรณ์ของชิ้นส่วนลดลง 72% จำเป็นต้องบำรุงรักษา\"</color>",
  ui_story_1014_10141201_68_dialog_content = "<color=#e8d9bb>โมดูลชีวภาพออฟไลน์</color>",
  ui_story_1014_10141201_69_dialog_content = "<color=#e8d9bb>ช่วยชีวิตออฟไลน์</color>",
  ui_story_1014_10141201_70_dialog_content = "<color=#e8d9bb>ข้อมูลบุคลิกภาพเสื่อมลง 32% ไม่สามารถทำงานในระดับปกติได้</color>",
  ui_story_1014_10141201_71_dialog_content = "มันเสื่อมจนใช้งานไม่ได้?",
  ui_story_1014_10141201_72_dialog_content = "คุณก็เช่นกัน Naviduz...",
  ui_story_1014_10141201_73_dialog_content = "ยังไงก็ขอบคุณที่อดทนรอกันมานาน",
  ui_story_1014_10141201_74_dialog_content = "กรุณาเปิดประตูสู่สะพาน",
  ui_story_1014_10141201_75_dialog_content = "<color=#e8d9bb>ยอมรับคำสั่งแล้ว</color>",
  ui_story_1014_10141201_76_dialog_content = "<color=#e8d9bb>ครืน!</color>",
  ui_story_1014_10141201_77_dialog_content = "ประตูเปิดอยู่.",
  ui_story_1014_10141201_78_dialog_content = "ฉันเห็นสะพานและคอนโซลควบคุมที่พังยับเยิน",
  ui_story_1014_10141201_79_dialog_content = "<anim type=Shake><size=45>กรรรรรร!</size></anim>",
  ui_story_1014_10141201_80_dialog_content = "ระวัง Eclipsites ที่พเนจรกำลังมาที่นี่!",
  ui_story_1014_10141201_81_dialog_content = "เตรียมตัวต่อสู้กันเถอะ",
  ui_story_1014_10141302_1_dialog_content = "ล้าง Eclipsites ทั้งหมดแล้ว",
  ui_story_1014_10141302_2_dialog_content = "ปิดประตู, PlayerNameดังนั้นเราจึงไม่ได้รับสหายของพวกเขาอีกต่อไป",
  ui_story_1014_10141302_3_dialog_content = "ฉันจะบอก Naviduz",
  ui_story_1014_10141302_4_dialog_content = "...",
  ui_story_1014_10141302_5_dialog_content = "คุณสบายดีไหม Axelia?",
