  ui_story_1014_10141302_7_dialog_content = "ฉันสบายดี",
  ui_story_1014_10141302_8_dialog_content = "ผลที่ตามมาของการต่อสู้ยังอยู่ในขอบเขตที่ยอมรับได้",
