  ui_story_1014_10141302_30_dialog_content = "เข้าใจแล้วครับ",
  ui_story_1014_10141302_31_dialog_content = "<color=#e8d9bb>กำลังทำซ้ำข้อมูล กรุณารอสักครู่</color>",
