  ui_story_1014_10141302_35_dialog_content = "<color=#e8d9bb>ปี๊บ ปี๊บ ปี๊บ...</color>",
  ui_story_1014_10141302_36_dialog_content = "นี่คือสำนักงานใหญ่ของ Ironthorn Knights ใน Twilight โปรดตอบกลับหากคุณว่าง เซอร์ลีโอ",
  ui_story_1014_10141302_37_dialog_content = "นี่คือ Expedition Knight Leo ไปข้างหน้า",
