  ui_story_1015_10150101_111_dialog_content = "เห็นได้ชัดว่าเราไม่สามารถทราบกำลังของกองกำลังศัตรูของเราได้",
  ui_story_1015_10150101_112_dialog_content = "สถานการณ์ที่เลวร้ายที่สุดคือการเผชิญหน้าทั้งหมดนี้เป็นกลุ่มอิสระของ Eclipsites",
  ui_story_1015_10150101_113_dialog_content = "หากพวกเขารวมตัวกันเพื่อปิดล้อม Twilight ผลที่ตามมาจะเกินกว่าจะคาดคิด",
  ui_story_1015_10150101_114_dialog_content = "พูดได้ดี. มันสดชื่นมากที่ได้ยินความคิดของจิตใจที่ชาญฉลาด",
  ui_story_1015_10150101_115_dialog_content = "คุณคิดกลยุทธ์เพื่อรับมือกับสถานการณ์แล้วหรือยัง?",
  ui_story_1015_10150101_116_dialog_content = "ฉันส่งกองทหารออกลาดตระเวนอย่างลับๆ เพื่อพยายามทำความเข้าใจการเคลื่อนไหวของศัตรูอย่างถ่องแท้",
  ui_story_1015_10150101_117_dialog_content = "แต่ในความคิดของฉัน กำลังทหารของเราในปัจจุบันไม่เพียงพอที่จะรักษาความเข้าใจใน Twilight",
  ui_story_1015_10150101_118_dialog_content = "นี่คือเหตุผลที่ข้าจะส่งคำขอกำลังเสริม",
  ui_story_1015_10150101_119_dialog_content = "อืม... ใช่ นี่เป็นตัวเลือกที่ปลอดภัยที่สุด",
  ui_story_1015_10150101_120_dialog_content = "คุณอยากพบฉันเกี่ยวกับเรื่องนี้ ดังนั้นฉันคิดว่าคุณตั้งใจที่จะขอความช่วยเหลือจากอิลลูมิน่า ถูกต้องไหม?",
  ui_story_1015_10150101_121_dialog_content = "แน่นอนว่าเรายังไม่รู้ว่าเราจะต้องเจอศัตรูอีกกี่ตัวในอนาคต",
  ui_story_1015_10150101_122_dialog_content = "มันคงเป็นการมองการณ์ไกลที่จะปล่อยให้ความแตกต่างของ Lumopolis และ Illumina เกิดขึ้นระหว่างเราในช่วงหัวเลี้ยวหัวต่อนี้ใช่หรือไม่?",
  ui_story_1015_10150101_123_dialog_content = "ฉันเข้าใจ. ฉันจะส่งข้อความทันทีที่ฉันกลับมา",
  ui_story_1015_10150101_124_dialog_content = "ดียิ่งเร็วยิ่งดี สิ่งที่เราขาดมากที่สุดในตอนนี้คือเวลา",
  ui_story_1015_10150101_125_dialog_content = "ฉันมีลางสังหรณ์ว่าสถานการณ์ที่เราคาดการณ์ไว้นั้นมักจะกลายเป็นจริงในไม่ช้า",
  ui_story_1015_10150101_126_dialog_content = "<color=#e8d9bb>ลูโมโปลิสราชสำนัก</color>",
  ui_story_1015_10150101_127_dialog_content = "เฮ้อ...",
  ui_story_1015_10150101_128_dialog_content = "คาร์ลีน คุณทำรายงานเสร็จแล้วเหรอ?",
  ui_story_1015_10150101_129_dialog_content = "เคย",
  ui_story_1015_10150101_130_dialog_content = "คุณดูเหนื่อยเล็กน้อย",
  ui_story_1015_10150101_131_dialog_content = "การพูดคุยกับเขาเป็นงานที่เหนื่อย",
  ui_story_1015_10150101_132_dialog_content = "ผมว่าเสียเวลา สิ่งที่เขาอยากฟังแทบไม่มีผลกับสิ่งที่ฉันต้องการพูดเลย",
  ui_story_1015_10150101_133_dialog_content = "คุณกำลังพูดถึงเรื่อง Twilight ใช่ไหม",
  ui_story_1015_10150101_134_dialog_content = "ใช่. ฉันไม่เข้าใจว่าทำไมเขาถึงถามคำถามเหล่านี้เกี่ยวกับการจัดสรรทรัพยากรและโครงสร้างองค์กร",
  ui_story_1015_10150101_135_dialog_content = "เห็นได้ชัดว่าข้อเท็จจริงที่ฉันรายงานแก่เขาคือ—",
  ui_story_1015_10150101_136_dialog_content = "ลืมมันไป ฉันไม่ควรบ่นเรื่องแบบนี้",
  ui_story_1015_10150101_137_dialog_content = "ใช่ นั่นก็เพียงพอแล้ว งั้นเราไปดื่มชากันเถอะ",
  ui_story_1015_10150101_138_dialog_content = "คุณมีแผนสำหรับสองสามวันข้างหน้าหรือไม่?",
  ui_story_1015_10150101_139_dialog_content = "ไม่มีอะไรมาก. เจ้าเมืองขอให้ฉันอยู่ในโหมดสแตนด์บายในลูโมโปลิส",
  ui_story_1015_10150101_140_dialog_content = "สแตนด์บาย? อ๋อ ถูกต้องแล้ว เป็นเพราะ. <color=#FFB400>การฝึกร่วมทางทหาร</color> ใกล้เข้ามาแล้วใช่ไหม",
  ui_story_1015_10150101_141_dialog_content = "ใช่ มันควรจะเป็น",
  ui_story_1015_10150101_142_dialog_content = "คุณควรเตรียมตัวเองให้พร้อม คุณเป็นดาราของรายการ คุณรู้ไหม",
  ui_story_1015_10150101_143_dialog_content = "แต่... ฉันรู้สึกกระสับกระส่ายบ้างในตอนนี้",
  ui_story_1015_10150101_144_dialog_content = "เป็นอะไรไปล่ะ",
  ui_story_1015_10150101_145_dialog_content = "ฉันยังไม่ได้รับข้อความจาก PlayerName.",
