  ui_story_1015_10150101_147_dialog_content = "โอ้ นั่นคาร์ลีน! นานมากแล้ว!",
  ui_story_1015_10150101_148_dialog_content = "เป็นเวลานานแล้ว Gronru ฉันหวังว่าฉันจะไม่รบกวนคุณด้วยการโทรกะทันหัน",
  ui_story_1015_10150101_149_dialog_content = "ไม่ คุณโทรมาถูกเวลาพอดี",
  ui_story_1015_10150101_150_dialog_content = "ฉันเพิ่งสร้างความก้าวหน้าครั้งยิ่งใหญ่ในงานของฉันเกี่ยวกับ Soroz",
  ui_story_1015_10150101_151_dialog_content = "ฟังนี่.",
  ui_story_1015_10150101_152_dialog_content = "เปิดใช้งาน โซรอซ!",
  ui_story_1015_10150101_153_dialog_content = "การเปิดใช้งาน Soroz เสร็จสมบูรณ์",
  ui_story_1015_10150101_154_dialog_content = "ได้ยินไหม!",
  ui_story_1015_10150101_155_dialog_content = "ฉันได้ยินมา แต่... โซรอซไม่สามารถเปิดใช้งานได้เสมอโดยไม่มีอะไรเกิดขึ้นเหรอ?",
  ui_story_1015_10150101_156_dialog_content = "ฉันรู้ว่าฉันรู้ว่า! เราบินได้เสมอ แต่ก่อนมันไม่มีสติใช่ไหม?",
  ui_story_1015_10150101_157_dialog_content = "ใช่",
  ui_story_1015_10150101_158_dialog_content = "ไม่ต้องกังวล Echo Template ได้รับการกู้คืนโดยพื้นฐานแล้ว",
  ui_story_1015_10150101_159_dialog_content = "เพียงแต่ว่าพวกเราชาว Aurorian ไม่สามารถสื่อสารกับมันได้โดยตรง",
  ui_story_1015_10150101_160_dialog_content = "แต่เพียงแค่รอ PlayerName กลับมาก็จะคุยกับซอรอซได้!",
  ui_story_1015_10150101_161_dialog_content = "โอ้ ถูกต้อง! ที่จริงฉันอยากจะถามคุณว่าเกิดอะไรขึ้นกับ PlayerName... และรองแน่นอน!",
  ui_story_1015_10150101_162_dialog_content = "เกิดอะไรขึ้นกับพวกเขาหลังจากที่ฉันเห็นพวกเขาครั้งสุดท้าย?",
  ui_story_1015_10150101_163_dialog_content = "พวกเขาไม่ได้ติดต่อฉันเลยตั้งแต่ฉันกลับมาที่ลูโมโพลิส",
