  ui_story_1015_10150101_175_dialog_content = "ความวุ่นวายที่นี่คืออะไร? พวกเขากำลังมองอะไรอยู่?",
  ui_story_1015_10150101_176_dialog_content = "คุณไม่รู้เหรอ? การฝึกร่วมทางทหารกำลังจะเริ่มขึ้น นี่คือธงของกองกำลังที่เข้าร่วมต่างๆ ที่บินอยู่ข้างหน้า",
  ui_story_1015_10150101_177_dialog_content = "โอ้! ได้เวลาซ้อมรบร่วมอีกครั้ง",
  ui_story_1015_10150101_178_dialog_content = "การออกกำลังกายในปีนี้น่าสนใจทีเดียว หนังสือพิมพ์วางเรียงกันเป็นแถวที่แผนกต้อนรับทุกวัน",
  ui_story_1015_10150101_179_dialog_content = "จริงหรือ มีอะไรพิเศษเป็นพิเศษเกี่ยวกับการฝึกซ้อมทางทหารในปีนี้หรือไม่?",
  ui_story_1015_10150101_180_dialog_content = "แน่นอน. จะมีผู้เข้าร่วม Caelestite ครั้งนี้ เป็นครั้งแรกในรอบกว่าทศวรรษ",
  ui_story_1015_10150101_181_dialog_content = "<color=#e8d9bb>ฝ่ายข่าวกรองเมืองกันนอน</color>",
  ui_story_1015_10150101_182_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก ก๊อก...</color>",
  ui_story_1015_10150101_183_dialog_content = "เข้ามาเลย",
  ui_story_1015_10150101_184_dialog_content = "พันเอกหญิง มีโทรเลขด่วนถึงคุณ",
  ui_story_1015_10150101_185_dialog_content = "โปรดดูความสะดวกของคุณเร็วที่สุด",
  ui_story_1015_10150101_186_dialog_content = "โทรเลขด่วน?",
  ui_story_1015_10150101_187_dialog_content = "ได้เลย ฉันเข้าใจแล้ว แค่วางมันไว้บนโต๊ะทำงานของฉัน",
  ui_story_1015_10150101_188_dialog_content = "ค่ะ!",
  ui_story_1015_10150101_189_dialog_content = "มาดูกันว่าคำสั่งเร่งด่วนนี้อาจเป็นของใคร...",
  ui_story_1015_10150101_190_dialog_content = "อืม? ลอร์ดยูลิสซิส?",
  ui_story_1015_10150201_1_dialog_content = "เร็วเข้า หยุดพูดพร่ำเพรื่อ",
  ui_story_1015_10150201_2_dialog_content = "คุณควรเดินให้เร็วกว่ามีดของฉัน ถ้าคุณรู้ว่าอะไรดีสำหรับคุณ",
  ui_story_1015_10150201_3_dialog_content = "ครับ",
  ui_story_1015_10150201_4_dialog_content = "แต่จริงๆ แล้วเราต้องตื่นเช้าขนาดนั้นทุกวันเลยเหรอ?",
