  ui_story_1015_10151202_52_dialog_content = "...",
  ui_story_1015_10151202_53_dialog_content = "คุณคิดว่าเหตุผลที่ฉันเลือกออกจาก Illumina เป็นเพราะเรื่องเล็กน้อยอย่างความรู้สึกถูกหักหลัง?",
  ui_story_1015_10151202_54_dialog_content = "คุณคิดผิดเต็มๆ",
