  ui_story_1015_10151301_1_dialog_content = "<color=#e8d9bb>บีวี่—บีวี่—</color>",
  ui_story_1015_10151301_2_dialog_content = "ฉันไม่สามารถทนเสียงทั้งหมดนี้ได้",
