  ui_story_1015_10151301_9_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_1015_10151301_10_dialog_content = "ให้ตายเถอะ... ประตูหลักของ Undercity เชื่อมต่อกับระบบไฟฟ้า",
