  ui_story_1015_10151401_30_dialog_content = "...",
  ui_story_1015_10151401_31_dialog_content = "(สัตว์ประหลาดตัวนั้นไม่ตอบสนอง แปลว่าการทดลองของ Forsakin ล้มเหลวงั้นหรือ?)",
  ui_story_1015_10151401_32_dialog_content = "ฉันเห็นแล้ว ดูเหมือนว่าการทดลองของฉันจะประสบความสำเร็จมากยิ่งขึ้นไปอีก",
