  ui_story_1015_10151402_1_dialog_content = "<anim type=Shake><size=50>กรรรรรร!</size></anim>",
  ui_story_1015_10151402_2_dialog_content = "เขาแข็งแกร่งขนาดนี้ได้อย่างไร...?",
