  ui_story_1015_10151402_43_dialog_content = "เกิดอะไรขึ้น? ทำไม...ฉันถึงมาอยู่ที่นี่?",
  ui_story_1015_10151402_44_dialog_content = "ทำไม... จำไม่ได้...?",
  ui_story_1015_10151402_45_dialog_content = "อึก...!",
  ui_story_1015_10151402_46_dialog_content = "ความสามารถในการรับรู้ของวัตถุยังคงเหมือนเดิม แต่ความทรงจำของเขาดูเหมือนไม่เป็นระเบียบและไม่สมบูรณ์ ไม่มีความทรงจำใหม่เกิดขึ้นหลังจากสูญเสียการควบคุม",
  ui_story_1015_10151402_47_dialog_content = "บันทึกชั่วคราวเป็นผลข้างเคียงที่ต้องให้ความสนใจ จำเป็นต้องมีการศึกษาเพิ่มเติมเพื่อกำจัดผลข้างเคียงนี้อย่างสมบูรณ์",
  ui_story_1015_10151402_48_dialog_content = "แน่นอนว่ามีความเป็นไปได้มากกว่าที่สถานการณ์นี้เกิดจากความบกพร่องของตัวแบบเอง",
  ui_story_1015_10151402_49_dialog_content = "โดยรวมแล้วการทดลองประสบความสำเร็จ",
  ui_story_1015_10151402_50_dialog_content = "ในที่สุดฉันก็เข้าใจกระบวนการวิวัฒนาการ",
  ui_story_1015_10151402_51_dialog_content = "เหลือเพียงคำถามเดียว...",
  ui_story_1015_10151402_52_dialog_content = "(เรื่องการทดสอบนี้จะจำเป็นสำหรับการตรวจสอบในภายหลัง)",
  ui_story_1015_10151402_53_dialog_content = "(ฉันต้องคิดหาวิธีให้เขามากับฉัน)",
  ui_story_1015_10151402_54_dialog_content = "(อย่างไรก็ตาม เขาค่อยๆ ฟื้นคืนสติและความรู้ความเข้าใจ ซึ่งเป็นตัวแปรที่ไม่เอื้อต่อแผนของฉัน)",
  ui_story_1015_10151402_55_dialog_content = "(อย่างไรก็ตาม มีวิธีจัดการกับแบบทดสอบง่ายๆ ประเภทนี้)",
  ui_story_1015_10151402_56_dialog_content = "คุณ... ฉันรู้จักคุณ...",
  ui_story_1015_10151402_57_dialog_content = "คุณคือ... เดเนียร์?",
  ui_story_1015_10151402_58_dialog_content = "ทำไมเธอ... ทำหน้าแบบนั้น...?",
  ui_story_1015_10151402_59_dialog_content = "ที่ไหน... ไรน์ฮาร์ท...?",
  ui_story_1015_10151402_60_dialog_content = "ทำไมเธอถึง...ไม่อยู่กับคุณ...?",
  ui_story_1015_10151402_61_dialog_content = "...",
  ui_story_1015_10151402_62_dialog_content = "ทั้งเดเนียร์และคนที่คุณเคยเป็นถูกอิลลูมินาทอดทิ้งไปนานแล้ว",
  ui_story_1015_10151402_63_dialog_content = "ฉันไม่ใช่เดเนียร์",
  ui_story_1015_10151402_64_dialog_content = "ถูกทอดทิ้ง?",
  ui_story_1015_10151402_65_dialog_content = "<anim type=Shake>เอิ๊ก...!!!</anim>",
  ui_story_1015_10151402_66_dialog_content = "เขากำลังรวบรวม Darkflow!",
  ui_story_1015_10151402_67_dialog_content = "Forsakin พยายามกวนเขาด้วยคำพูดของเธอเพื่อทำให้เขาเข้าสู่ความสับสนวุ่นวายอีกครั้งและทำให้เขากลายเป็นสัตว์ประหลาดหรือไม่!",
  ui_story_1015_10151402_68_dialog_content = "ทุกคนเกือบจะอยู่บนขาสุดท้ายแล้ว...",
  ui_story_1015_10151402_69_dialog_content = "ฟังนะ... พวกเขากำลังเรียกคุณว่าสัตว์ประหลาด",
  ui_story_1015_10151402_70_dialog_content = "<anim type=Shake>ไม่... ฉันไม่ใช่... ฉันไม่ใช่สัตว์ประหลาด...</anim>",
  ui_story_1015_10151402_71_dialog_content = "<anim type=Shake>ฉัน... ทหาร... ของ Illumina...</anim>",
  ui_story_1015_10151402_72_dialog_content = "ชิ...",
  ui_story_1015_10151402_73_dialog_content = "สหพันธ์อิลลูมินาไม่มีที่สำหรับคุณอีกต่อไป",
  ui_story_1015_10151402_74_dialog_content = "มากับฉันแล้วคุณจะมีโอกาสรอดชีวิต",
  ui_story_1015_10151402_75_dialog_content = "อยู่ที่นี่และความตายเท่านั้นที่จะรอคุณอยู่",
  ui_story_1015_10151402_76_dialog_content = "อย่าเชื่อเธอ! Illumina ไม่เคยยอมแพ้ใคร!",
  ui_story_1015_10151402_77_dialog_content = "สหพันธ์อิลลูมินาละทิ้งผู้ที่ไม่สามารถมีส่วนร่วมในสาเหตุของมันต่อไปได้ โดยเฉพาะผู้ที่ล้มเหลว",
  ui_story_1015_10151402_78_dialog_content = "Grand Marshal Reinhardt ไม่เคยละทิ้งการค้นหาคุณ",
  ui_story_1015_10151402_79_dialog_content = "Reinhardt ไม่เคยกลับมาพร้อมกำลังเสริม",
  ui_story_1015_10151402_80_dialog_content = "เธอไม่ได้พูดอะไรในเรื่องนี้! เจ้าหน้าที่อิลลูมินาวางยาเธอจนเธอหมดหนทางที่จะช่วยคุณ!",
  ui_story_1015_10151402_81_dialog_content = "ฉันเห็นทั้งหมดด้วยความสามารถทางจิตของฉัน ฉันรู้ว่ามันเป็นความจริงอย่างแน่นอน!",
  ui_story_1015_10151402_82_dialog_content = "อย่าลืมว่าใน Undercity 80 Reinhardt เผชิญหน้ากับเราด้วยการชักมีดสั้น",
  ui_story_1015_10151402_83_dialog_content = "เปิดตาของคุณและดู อดีตสหายของคุณไม่ใช่ชาวออโรเรียนอีกต่อไป",
  ui_story_1015_10151402_84_dialog_content = "เธอเป็นคนที่มือเปื้อนเลือด!",
  ui_story_1015_10151402_85_dialog_content = "คุณไม่เกลียดคนหน้าซื่อใจคดเหล่านี้หรือ",
  ui_story_1015_10151402_86_dialog_content = "<size=45>เงียบเถอะคุณ!</size>",
  ui_story_1015_10151402_87_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_1015_10151402_88_dialog_content = "<anim type=Shake><size=50>อุ๊ย!!!</size></anim>",
  ui_story_1015_10151402_89_dialog_content = "ทำไม-!",
  ui_story_1015_10151402_90_dialog_content = "... จะทำอะไรน่ะ?",
  ui_story_1015_10151402_91_dialog_content = "ฉันคือ...ทหาร...แห่งอิลลูมิน่า...",
  ui_story_1015_10151402_92_dialog_content = "ฉันจะร่วมมือ...กับการสืบสวน...",
  ui_story_1015_10151402_93_dialog_content = "แต่ฉันยัง... อยากจะปกป้องเพื่อนของฉัน...",
  ui_story_1015_10151402_94_dialog_content = "...",
  ui_story_1015_10151402_95_dialog_content = "ช่างโง่เขลา",
  ui_story_1015_10151402_96_dialog_content = "ดูเหมือนว่าการรับรู้ของตัวบุคคลเองและผู้อื่นยังมีข้อบกพร่อง",
  ui_story_1015_10151402_97_dialog_content = "นี่อาจเป็นโรคทางจิตชนิดหนึ่ง ความรู้ความเข้าใจที่ผิดพลาดนี้จะต้องถูกกำจัดให้หมดไป",
  ui_story_1015_10151402_98_dialog_content = "นี่มัน...",
  ui_story_1015_10151402_99_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_1015_10151402_100_dialog_content = "อะ-อะไรนะ?!",
  ui_story_1015_10151402_101_dialog_content = "กลับมา, PlayerName! รูขนาดใหญ่ปรากฏขึ้นที่ประตู!",
  ui_story_1015_10151402_102_dialog_content = "มีบางอย่างที่ทรงพลังอย่างยิ่งกำลังพังประตูเข้ามา!",
  ui_story_1015_10151402_103_dialog_content = "เย้!!!",
  ui_story_1015_10151402_104_dialog_content = "<color=#e8d9bb>ตูมม!!!</color>",
  ui_story_1015_10151402_105_dialog_content = "นั่นเป็นคำอธิบายที่ถูกต้อง แต่ไม่ใช่บางอย่าง - มันเป็นแค่ฉัน",
  ui_story_1015_10151402_106_dialog_content = "คุณอยู่ที่นี่จริงๆ Forsakin",
  ui_story_1015_10151402_107_dialog_content = "ถูกต้องตามคิว",
  ui_story_1015_10151402_108_dialog_content = "เราเจอกันอีกแล้ว ไรน์ฮาร์ท แม้ตลอดเวลาที่ผ่านมา คุณก็ยังไม่มีความคืบหน้าใดๆ",
  ui_story_1015_10151402_109_dialog_content = "ยังเต็มใจใช้อยู่",
  ui_story_1015_10151402_110_dialog_content = "ไม่เจอกันนาน Forsakin",
  ui_story_1015_10151402_111_dialog_content = "ดูเหมือนว่าคุณยังทำได้ไม่ดีนักกับ Eclipsites และตอนนี้ คุณได้ตกลงสู่จุดต่ำสุดครั้งล่าสุดนี้แล้ว",
  ui_story_1015_10151402_112_dialog_content = "อืม? คุณชื่ออะไร? วรา...?",
  ui_story_1015_10151402_113_dialog_content = "ผู้เล่นตัวเล็กๆ ที่ต้องพึ่งเพื่อนร่วมชั้นเก่าเพื่อรักษาตำแหน่งนั้นไม่คุ้มค่าที่จะจดจำ",
  ui_story_1015_10151402_114_dialog_content = "น่าจะเป็นการดูถูก? คุณต้องเข้าใจผิดว่าฉันเป็นคนที่ใส่ใจ",
  ui_story_1015_10151402_115_dialog_content = "เมื่อฉันล้มเธอทีหลัง อย่าไปร้องไห้หาพี่สาวเธอนะ",
  ui_story_1015_10151402_116_dialog_content = "ยังไม่บรรลุนิติภาวะ",
  ui_story_1015_10151402_117_dialog_content = "นั่นคือ... ไรน์ฮาร์ท?",
  ui_story_1015_10151402_118_dialog_content = "เฮลิออส?! ลักษณะของคุณ...",
  ui_story_1015_10151402_119_dialog_content = "นี่คือ... กำลังเสริม? ในที่สุดคุณก็...",
  ui_story_1015_10151402_120_dialog_content = "...",
  ui_story_1015_10151402_121_dialog_content = "ใช่ ฉันขอโทษที่มาสาย",
  ui_story_1015_10151402_122_dialog_content = "ฉันมารับคุณและนำกำลังเสริมมา",
  ui_story_1015_10151402_123_dialog_content = "ปกป้องสถานที่แห่งนี้!",
  ui_story_1015_10151402_124_dialog_content = "ค่ะ!",
  ui_story_1015_10151402_125_dialog_content = "ตรงตามที่ฉันคาดการณ์ไว้",
  ui_story_1015_10151402_126_dialog_content = "ไรน์ฮาร์ท มาทำข้อตกลงกันเถอะ",
  ui_story_1015_10151402_127_dialog_content = "หา...?",
  ui_story_1015_10151402_128_dialog_content = "การอนุญาตให้ฉันและผู้รับการทดสอบออกจากอิลลูมินาจะไม่มีผลเสียต่อคุณ",
  ui_story_1015_10151402_129_dialog_content = "ฮะ? บางทีคุณอาจอยู่ใน Eternal Night นานเกินไป ดูเหมือนว่า Darkflow จะเข้าถึงสมองของคุณ",
  ui_story_1015_10151402_130_dialog_content = "คุณไม่อยู่ในฐานะที่จะเจรจากับเราได้ในขณะนี้",
  ui_story_1015_10151402_131_dialog_content = "ฉันไม่เจรจากับคุณ",
  ui_story_1015_10151402_132_dialog_content = "ฟอสซิลเก่าเหล่านั้นไม่ต้องการฉัน พวกเขาต้องการเขา",
  ui_story_1015_10151402_133_dialog_content = "(เธอหมายความว่ายังไง คณะกรรมการต้องการเฮลิออส?)",
  ui_story_1015_10151402_134_dialog_content = "(แต่ภารกิจของฉันคือจับ Forsakin และช่วยเหลือรองรอง)",
  ui_story_1015_10151402_135_dialog_content = "คุณรู้ดีว่าจะเกิดอะไรขึ้นหากเขาตกอยู่ในมือของคนเหล่านั้น",
  ui_story_1015_10151402_136_dialog_content = "ฉันไม่สามารถยอมรับคำขอของคุณได้",
  ui_story_1015_10151402_137_dialog_content = "ฉันคงเลือกที่จะเชื่อคุณถ้าเป็นเวลากว่าทศวรรษที่แล้ว ก่อนที่คุณจะออกจากอิลลูมินา",
  ui_story_1015_10151402_138_dialog_content = "แต่หลังจากต่อสู้มาหลายปี ฉันรู้จักคุณดีกว่าใครๆ",
  ui_story_1015_10151402_139_dialog_content = "สิ่งที่คุณอยากทำไม่ต่างจากที่พวกเขาต้องการ",
  ui_story_1015_10151402_140_dialog_content = "ส่งเขามาให้ฉัน แล้วฉันจะใช้สถานะของฉันในฐานะจอมพลเพื่อปกป้องเขา ฉันจะไม่ยอมให้ใครมาแตะต้องเขา",
  ui_story_1015_10151402_141_dialog_content = "คุณไม่มีอำนาจ",
  ui_story_1015_10151402_142_dialog_content = "การเจรจาเหล่านี้ไม่มีที่ไหนเลย ฉันไม่ต้องเสียเวลาที่นี่อีกแล้ว",
  ui_story_1015_10151402_143_dialog_content = "หยก.",
  ui_story_1015_10151402_144_dialog_content = "<anim type=Shake><size=50>กราาาาาา!</size></anim>",
  ui_story_1015_10151402_145_dialog_content = "ลาก่อน",
  ui_story_1015_10151402_146_dialog_content = "<color=#e8d9bb>ฟู่ววว!!!</color>",
  ui_story_1015_10151501_1_dialog_content = "รายงานตัว ตามข้อมูลข่าวกรองที่ส่งมาจากพันเอกหญิงและพันตรีอนาโตลี เราพบรองผู้หมวดในห้องทดลองร้าง",
  ui_story_1015_10151501_2_dialog_content = "รอง ผบช.น. กลับปฏิบัติหน้าที่!",
  ui_story_1015_10151501_3_dialog_content = "รอง! คุณสบายดีไหม? คุณได้รับบาดเจ็บหรือไม่?",
  ui_story_1015_10151501_4_dialog_content = "ฉันไม่เป็นไร!",
  ui_story_1015_10151501_5_dialog_content = "ขอโทษที่สะเพร่าและสร้างความเดือดร้อนให้ทุกคน...",
  ui_story_1015_10151501_6_dialog_content = "ตราบใดที่คุณกลับมาโดยสวัสดิภาพ ทุกอย่างก็เรียบร้อยดี",
  ui_story_1015_10151501_7_dialog_content = "ถูกตัอง. อย่ากดดันตัวเองมากเกินไป",
  ui_story_1015_10151501_8_dialog_content = "Forsakin เป็นศัตรูที่ฉลาดแกมโกง เราต้องใช้ความพยายามร่วมกันทั้งหมดเพื่อจัดการกับเธอ",
  ui_story_1015_10151501_9_dialog_content = "นั่นสินะ...",
  ui_story_1015_10151501_10_dialog_content = "การค้นหาเป็นอย่างไร คุณพบร่องรอยของ Forsakin หรือไม่?",
  ui_story_1015_10151501_11_dialog_content = "รายงานตัว! เราได้ค้นหา Undercity ทั้งหมดแล้วและไม่พบร่องรอยของ Forsakin",
  ui_story_1015_10151501_12_dialog_content = "แล้วทางเข้าออกต่างๆ และทางเดินของ Undercity เก่าล่ะ?",
  ui_story_1015_10151501_13_dialog_content = "ทางเข้าและออกทุกทางได้รับการคุ้มกัน และไม่มีใครเห็นเข้าหรือออก",
  ui_story_1015_10151501_14_dialog_content = "ฉันเห็น. อย่างไรก็ตาม เราไม่สามารถแน่ใจได้มากนัก ค้นหาต่อไป",
  ui_story_1015_10151501_15_dialog_content = "ค่ะ!",
  ui_story_1015_10151501_16_dialog_content = "Forsakin สามารถหายไปจากใต้จมูกของเราได้โดยไม่เสียเหงื่อ",
  ui_story_1015_10151501_17_dialog_content = "เธอพ่นพิษของเธอและวิ่งไปเหมือนสายลม",
  ui_story_1015_10151501_18_dialog_content = "Grand Marshal, Captain Wrath—ฉันคิดว่าฉันน่าจะรู้ว่า Forsakin หนีไปได้อย่างไร",
  ui_story_1015_10151501_19_dialog_content = "อืม? บอกเราแล้ว",
  ui_story_1015_10151501_20_dialog_content = "Forsakin ออกแบบและสร้าง Undercity แห่งนี้",
  ui_story_1015_10151501_21_dialog_content = "หลังจากสร้าง Undercity และก่อนที่จะแปรพักตร์จาก Illumina Federation Forsakin แอบเดินทางไปมาระหว่างที่นี่และเมือง Gannon หลายครั้ง",
  ui_story_1015_10151501_22_dialog_content = "ตามข่าวกรองที่ฉันรวบรวมมา Forsakin เป็นคนที่ทนไม่ได้ที่จะเสียเวลากับเรื่องไร้สาระ",
