  ui_story_1015_10151501_178_dialog_content = "กันนอนซิตี้.",
  ui_story_1015_10151501_179_dialog_content = "เรากลับมาแล้ว?",
  ui_story_1015_10151501_180_dialog_content = "ได้สิ",
  ui_story_1015_10151501_181_dialog_content = "เรากลับมาแล้ว.",
  ui_story_1016_10160101_1_dialog_content = "<color=#e8d9bb>ชู—</color>",
  ui_story_1016_10160101_2_dialog_content = "<color=#e8d9bb>กะจังกะจังกะจัง—</color>",
  ui_story_1016_10160101_3_dialog_content = "เรียน ผู้เข้าร่วมการฝึกร่วมทางทหารทุกคน",
  ui_story_1016_10160101_4_dialog_content = "รถไฟมาถึงที่หมายแล้ว ตอนนี้คุณสามารถออกจากรถไฟ",
