  ui_story_1016_10160101_208_dialog_content = "หา?",
  ui_story_1016_10160101_209_dialog_content = "เพียงแค่เงียบลงและตั้งใจฟัง",
  ui_story_1016_10160101_210_dialog_content = "<size=30>*ที่ร้องไห้*</size>",
  ui_story_1016_10160101_211_dialog_content = "ถูกต้องที่สุด",
  ui_story_1016_10160101_212_dialog_content = "แปลกจัง การร้องไห้ของคนๆ นั้นไม่ได้ฟังดูเศร้าเลย",
  ui_story_1016_10160101_213_dialog_content = "มันใกล้เข้ามาแล้ว พวกเขาคงจะกำลังเดินมาหาเรา",
  ui_story_1016_10160101_214_dialog_content = "ฮือ ๆ ๆ",
  ui_story_1016_10160101_215_dialog_content = "กึ่งมนุษย์? นั่นเป็นภาพที่หายาก",
  ui_story_1016_10160101_216_dialog_content = "ทุกอย่างโอเคไหม? ฉันได้ยินคุณร้องไห้มาแต่ไกล",
