  ui_story_1016_10160101_252_dialog_content = "แน่นอน-",
  ui_story_1016_10160101_253_dialog_content = "<color=#e8d9bb>เอี๊ยด—</color>",
  ui_story_1016_10160101_254_dialog_content = "อ๊าาา!",
  ui_story_1016_10160101_255_dialog_content = "มีคนอยู่นอกประตู!",
