  ui_story_1016_10160101_274_dialog_content = "...",
  ui_story_1016_10160101_275_dialog_content = "ถ้าอย่างนั้นเราควรจะไปเดี๋ยวนี้",
  ui_story_1016_10160101_276_dialog_content = "ใช่ในขณะที่ฉันยังจำทางกลับได้",
  ui_story_1016_10160101_277_dialog_content = "ฮึ่ม! ทีหลังไอ้เหี้ย!",
  ui_story_1016_10160101_278_dialog_content = "ทั้งสามคือผู้เข้าร่วมจาก Umbraton",
  ui_story_1016_10160101_279_dialog_content = "เราควรจะปล่อยพวกเขาไปแบบนี้จริงๆ เหรอ? เป็นไปได้ว่าพวกเขาได้ยินการสนทนาของเรา",
  ui_story_1016_10160101_280_dialog_content = "ถ้าพวกเขาได้ยินเราจริงๆ ฉันจะหาทางยุติเรื่องนี้",
