  ui_story_1016_10160501_14_dialog_content = "งั้นเรารีบกันเถอะ",
  ui_story_1016_10160501_15_dialog_content = "รับทราบ!",
  ui_story_1016_10160501_16_dialog_content = "สุริยุปราคาที่เมืองแกนนอน...",
  ui_story_1016_10160501_17_dialog_content = "ดูเหมือนว่ามีใครบางคนที่ก่อความเสียหายมากกว่าเราเสียอีก",
