  ui_story_1016_10161001_101_dialog_content = "ชื่อ เอ่อ...",
  ui_story_1016_10161001_102_dialog_content = "ขอแค่โทรหาเธอ <color=#FFB400>หยก</color>.",
  ui_story_1016_10161001_103_dialog_content = "<color=#e8d9bb>ตูม—!</color>",
  ui_story_1016_10161001_104_dialog_content = "M-การทดลองของฉัน...",
