  ui_story_1016_10161101_59_dialog_content = "นักรบโปรดจับมือ",
  ui_story_1016_10161101_60_dialog_content = "แอ็กซีเลีย...",
  ui_story_1016_10161101_61_dialog_content = "ฉันเคยได้ยินเกี่ยวกับคุณ ความแข็งแกร่งของคุณเป็นสิ่งที่น่าชื่นชม",
