  ui_story_1016_10161402_8_dialog_content = "—!!!",
  ui_story_1016_10161402_9_dialog_content = "พูดมากเกินไปแล้ว",
  ui_story_1016_10161402_10_dialog_content = "ไอ ไอ!",
  ui_story_1016_10161402_10X1_dialog_content = "รอง! คุณสบายดีไหม?!",
  ui_story_1016_10161402_11_dialog_content = "อย่างรวดเร็ว! เขาอาจจะแสร้งทำเป็นตายเพื่อทำให้เราลดการป้องกันลง",
