  ui_story_1016_10161402_58_dialog_content = "(ฉันไม่รู้ว่า Axelia เป็นอย่างไรบ้าง เธอ... ยังมีชีวิตอยู่หรือเปล่า?)",
  ui_story_1016_10161402_59_dialog_content = "(เราพร้อมที่จะปฏิบัติภารกิจของเราทุกวิถีทาง แต่เมื่อฉันเห็นเธอเดินจากไป...)",
  ui_story_1016_10161402_60_dialog_content = "ระวังตัวไว้นะทุกคน!",
  ui_story_1016_10161402_61_dialog_content = "มีบางอย่างอยู่หลังประตูบานนั้น!",
  ui_story_1016_10161402_62_dialog_content = "(ออร่านี้...!)",
  ui_story_1016_10161402_63_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1016_10161402_64_dialog_content = "<color=#e8d9bb>บิว— บิว—</color>",
  ui_story_1016_10161402_65_dialog_content = "เตรียมพร้อมสำหรับการต่อสู้อีกครั้ง PlayerName!",
  ui_story_1016_10161402_66_dialog_content = "อยู่ในระบบ! อย่าแสดงความอ่อนแอ!",
  ui_story_1016_10161402_67_dialog_content = "<color=#e8d9bb>ตูม...</color>",
  ui_story_1016_10161402_68_dialog_content = "มีคนออกมา!",
  ui_story_1016_10161402_69_dialog_content = "คือว่า...?!",
  ui_story_1016_10161402_70_dialog_content = "(ฉันเห็นร่างประหลาดพุ่งออกมาจากหลังประตู)",
  ui_story_1016_10161402_71_dialog_content = "(เป็นเพียงชั่วขณะหนึ่ง แต่ฉันสัมผัสได้ถึงกระแสแห่งความมืดที่ทรงพลังยิ่งกว่าของฟิเจอรัลด์ที่มาจากร่างกายของพวกเขา)",
  ui_story_1016_10161402_72_dialog_content = "(เราใช้กำลังส่วนใหญ่ต่อสู้กับฟิเจอรัลด์หมดแล้ว)",
  ui_story_1016_10161402_73_dialog_content = "(ในขณะนั้น คนแปลกหน้าสามารถเอาชนะเราได้ทุกเมื่อที่พวกเขาต้องการ...)",
  ui_story_1016_10161402_74_dialog_content = "ระวังไวซ์! พวกเขากำลังมาที่คุณ!",
  ui_story_1016_10161402_75_dialog_content = "หา?!",
  ui_story_1016_10161402_76_dialog_content = "หลังจากที่ห่างกันไปนาน...",
  ui_story_1016_10161402_77_dialog_content = "ในที่สุดเราก็กลับมาพบกันอีกครั้ง",
  ui_story_1016_10161402_78_dialog_content = "คุณเป็นใครน่ะ",
  ui_story_1016_10161402_79_dialog_content = "(เธอดูเหมือนก <color=#FFB400>เจตภูต</color>!)",
  ui_story_1016_10161402_80_dialog_content = "(ฉันไม่รู้ด้วยซ้ำว่าเธอชื่อ แล้วทำไม...)",
  ui_story_1016_10161402_81_dialog_content = "(ทำไมเธอดูเหมือน <color=#FFB400>คุ้นเคย</color>?!)",
  ui_story_1016_10161402_82_dialog_content = "รอ! อย่าไป!",
  ui_story_1016_10161402_83_dialog_content = "คุณจะรู้ทุกอย่างในไม่ช้าพอ ...",
  ui_story_1016_10161402_84_dialog_content = "ในอนาคต.",
  ui_story_1016_10161402_85_dialog_content = "หยุดเธอ!",
  ui_story_1016_10161402_86_dialog_content = "เธอแบก <color=#FFB400>คอนโซลหลักของ Guardian One</color>!",
  ui_story_1016_10161402_87_dialog_content = "ระยับ!",
  ui_story_1016_10161402_88_dialog_content = "มันไม่มีจุดหมาย",
  ui_story_1016_10161402_89_dialog_content = "ฉ-มันไม่มีผลเหรอ?!",
  ui_story_1016_10161402_90_dialog_content = "หลังเธอ! เราปล่อยให้เธอหนีไปไม่ได้ด้วยคอนโซลหลักของ Guardian One!",
  ui_story_1016_10161402_91_dialog_content = "<color=#e8d9bb>ในขณะเดียวกัน ในเมืองกันนอน</color>",
  ui_story_1016_10161402_92_dialog_content = "พวกเขาไปได้ไม่ไกล ค้นหาทุกซอกทุกมุมของสถานที่",
  ui_story_1016_10161402_93_dialog_content = "ครับ!",
  ui_story_1016_10161402_94_dialog_content = "...",
  ui_story_1016_10161402_95_dialog_content = "พวกมันดื้อรั้นมาก",
  ui_story_1016_10161402_96_dialog_content = "ด้วยอัตรานี้ ใช้เวลาไม่นานก่อนที่พวกเขาจะมาหาเราที่นี่",
  ui_story_1016_10161402_97_dialog_content = "เราจำเป็นต้องออกไป",
  ui_story_1016_10161402_98_dialog_content = "ที่นี่... ดูเหมือน Undercity 80 เลย",
  ui_story_1016_10161402_99_dialog_content = "ไม่มีประโยชน์ที่จะพูดอะไรแบบนั้นอีกต่อไป",
  ui_story_1016_10161402_100_dialog_content = "คุณคิดเหมือนกันใช่ไหม? บางทีคุณพูดถูก...",
  ui_story_1016_10161402_101_dialog_content = "เมื่อก่อน... พวกเราก็ไม่ต่างจากตอนนี้ ติดอยู่ใน Undercity ล้อมรอบด้วยศัตรู...",
  ui_story_1016_10161402_102_dialog_content = "เมื่อนั้น... เราต่อต้าน Eclipsites... ไม่ใช่สหายของเรา...",
  ui_story_1016_10161402_103_dialog_content = "มีความแตกต่างหรือไม่?",
  ui_story_1016_10161402_104_dialog_content = "เท่าที่ฉันกังวล ใครก็ตามที่ขวางทางฉันคือศัตรู",
  ui_story_1016_10161402_105_dialog_content = "Aurorian, Eclipsites มันไม่ต่างอะไรกับฉันเลย",
  ui_story_1016_10161402_106_dialog_content = "ไม่... มันไม่เหมือนกันเลย",
  ui_story_1016_10161402_107_dialog_content = "Eclipsites เป็นศัตรูตามธรรมชาติของเรา... แต่สหายของเรา? พวกเขาไม่รู้ว่าเราผ่านอะไรมาบ้าง",
  ui_story_1016_10161402_108_dialog_content = "ทั้งหมดนี้เป็นเรื่องเข้าใจผิด",
  ui_story_1016_10161402_109_dialog_content = "ไม่มีการเข้าใจผิด เฮลิออส",
  ui_story_1016_10161402_110_dialog_content = "นี่คือสิ่งที่พวกเขาเป็น: คนเขลาที่โง่เขลาและเชื่อฟังอย่างสุ่มสี่สุ่มห้า",
  ui_story_1016_10161402_111_dialog_content = "...",
  ui_story_1016_10161402_112_dialog_content = "อะไรนะ... เกิดอะไรขึ้นกับเธอ... ถึงทำให้เธอต้องลงเอยแบบนี้?",
  ui_story_1016_10161402_113_dialog_content = "เมื่อใดที่ความคิดของคุณชัดเจน",
  ui_story_1016_10161402_114_dialog_content = "ทีละเล็กละน้อยในช่วงสองสามวันที่ผ่านมา...",
  ui_story_1016_10161402_115_dialog_content = "แวบแรกรู้สึกเหมือนใจ...ถูกหมอกหนาปกคลุม...",
  ui_story_1016_10161402_116_dialog_content = "แต่ตอนนี้...อะไรๆ ก็ชัดเจนขึ้นนิดหน่อย...",
  ui_story_1016_10161402_117_dialog_content = "งั้นเหรอ",
  ui_story_1016_10161402_118_dialog_content = "ดูเหมือนว่าผลการทดสอบของฉันจะเกินความคาดหมายของฉันไปมาก",
  ui_story_1016_10161402_119_dialog_content = "คุณยัง...ยังไม่ตอบฉัน...",
  ui_story_1016_10161402_120_dialog_content = "บอกฉันที...ทำไมเราถึงจากไป...",
  ui_story_1016_10161402_121_dialog_content = "ให้ฉัน... ช่วยเธอกลับไปที่อิลลูมิน่า",
  ui_story_1016_10161402_122_dialog_content = "ยังไม่บรรลุนิติภาวะ",
  ui_story_1016_10161402_123_dialog_content = "คุณคาดหวังให้เราได้รับการต้อนรับที่นี่จริง ๆ เหรอ? อะไรทำให้คุณมีความคิดเช่นนั้น?",
  ui_story_1016_10161402_124_dialog_content = "นี่คือบ้านของเรา",
  ui_story_1016_10161402_125_dialog_content = "เพื่อนของเราและ Reinhardt กำลังรอเราอยู่",
  ui_story_1016_10161402_126_dialog_content = "Reinhardt ไม่ใช่เพื่อนของฉัน เธอทิ้งฉันไปนานแล้ว เหมือนกับที่เธอทิ้งคุณไป",
  ui_story_1016_10161402_127_dialog_content = "ในทุกระดับ Illumina ได้รับความเสียหายอย่างสมบูรณ์",
  ui_story_1016_10161402_128_dialog_content = "ความโกรธของคุณ...",
  ui_story_1016_10161402_129_dialog_content = "ความเกลียดชังของคุณ...จะกลืนกินคุณ...",
  ui_story_1016_10161402_130_dialog_content = "โอ้จริงเหรอ? จากนั้นให้ฉันเติมความจริงเบื้องหลังทุกสิ่ง",
  ui_story_1016_10161402_131_dialog_content = "หากคุณยังคงต้องการเชื่อในพวกเขาหลังจากนั้น ก็ช่วยอะไรคุณไม่ได้เลย",
  ui_story_1016_10161402_132_dialog_content = "ความจริง?",
  ui_story_1016_10161402_133_dialog_content = "ใช่ และความจริงก็คือเราทุกคนเป็นอาวุธที่สร้างขึ้นเพื่อผลประโยชน์ของอิลลูมินา คุณ ฉัน และแม้แต่ Reinhardt",
  ui_story_1016_10161402_134_dialog_content = "คณะกรรมการกำหนดให้เราเข้าโปรแกรมดัดแปลงการทดลองที่เรียกว่าโครงการ: ดวงอาทิตย์เทียมเพื่อเพิ่มความแข็งแกร่งของเรา",
  ui_story_1016_10161402_135_dialog_content = "การต่อสู้ของเราใน Undercity 80 เป็นเพียงการทดลองเล่นสำหรับเราซึ่งเป็นอาสาสมัครทดสอบที่มีค่าของพวกเขา",
  ui_story_1016_10161402_136_dialog_content = "ภารกิจที่เรียกว่าของเราถึงวาระตั้งแต่เริ่มต้น",
  ui_story_1016_10161402_137_dialog_content = "แต่มันจะเป็นไปได้อย่างไร!",
  ui_story_1016_10161402_138_dialog_content = "ผู้คนมากมาย... พวกเราหลายคนเสียชีวิตในการสู้รบครั้งนั้น!",
  ui_story_1016_10161402_139_dialog_content = "นั่นคือเป้าหมายของพวกเขาตลอดมา",
  ui_story_1016_10161402_140_dialog_content = "คณะกรรมการต้องการให้เราต่อสู้ในการต่อสู้ที่สิ้นหวังเพื่อให้เราปลดล็อกศักยภาพสูงสุดของเรา",
  ui_story_1016_10161402_141_dialog_content = "พวกเราส่วนใหญ่ถือว่าล้มเหลวในระหว่างกระบวนการปรับเปลี่ยน และอาจถูกฆ่าตายในสนามรบหรือไม่ก็จบลงด้วยวิธีเดียวกับคุณ",
  ui_story_1016_10161402_142_dialog_content = "ทำไม... ทำไมพวกเขาถึงทำเช่นนี้?",
  ui_story_1016_10161402_143_dialog_content = "ฉันบอกคุณแล้วเพื่อประโยชน์ในการทดลองของพวกเขา Project Artificial Sun มีอัตราความสำเร็จที่ต่ำมากในการปรับเปลี่ยนวัตถุทดสอบ",
  ui_story_1016_10161402_144_dialog_content = "วิธีเดียวที่จะวัดความสำเร็จของพวกเขาได้อย่างแท้จริงคือการบังคับให้เราเข้าสู่การต่อสู้ที่โหดร้ายกับ Eclipsites และดูว่าใครจะรอดชีวิต",
  ui_story_1016_10161402_145_dialog_content = "Reinhardt เป็นคนเดียวที่ถือว่าประสบความสำเร็จ",
  ui_story_1016_10161402_146_dialog_content = "พวกเราที่เหลือถูกทิ้งเหมือนขยะ",
  ui_story_1016_10161402_147_dialog_content = "ยังไม่เข้าใจ? งั้นผมขอทำให้มันง่ายกว่านี้หน่อย คุณไม่ใช่คนในสายตาของสหพันธ์อิลลูมิน่า คุณเป็นอาวุธ เป็นเครื่องมือ และไม่มีอะไรมากไปกว่านั้น",
  ui_story_1016_10161402_148_dialog_content = "อย่าปล่อยให้พวกเขาหลอกคุณด้วยการพูดถึงเครือญาติและประเทศของพวกเขา อยากอยู่รอดต้องเริ่มคิดเอง",
  ui_story_1016_10161402_149_dialog_content = "ไม่มีที่ใดในโลกของพวกเขาสำหรับอาวุธที่แตกหักเช่นเรา",
  ui_story_1016_10161402_150_dialog_content = "คุณได้เห็นมันด้วยตัวคุณเองแล้วใช่ไหม? วิธีที่ทุกคนชักอาวุธของพวกเขาในสายตาของคุณ",
  ui_story_1016_10161402_151_dialog_content = "...",
  ui_story_1016_10161402_152_dialog_content = "คุณ... คุณพูดเอง... พวกเขาแค่งมงาย...",
  ui_story_1016_10161402_153_dialog_content = "ถึงว่าทำไม...เราต้องทำให้เค้า...เห็นอะไรชัดเจน...",
  ui_story_1016_10161402_154_dialog_content = "และกำจัดผู้คน... ที่ทำให้พวกเขาตาบอด",
  ui_story_1016_10161402_155_dialog_content = "นั่นจะทำให้ Illumina อยู่บนเส้นทางที่ถูกต้องอีกครั้ง",
  ui_story_1016_10161402_156_dialog_content = "เราต้องแก้ไขปัญหา...อย่าหมกมุ่นอยู่กับความเกลียดชังของเรา",
  ui_story_1016_10161402_157_dialog_content = "ดังนั้นคุณยังคงเชื่อคำโกหกทั้งหมดของพวกเขาอยู่ดี",
  ui_story_1016_10161402_158_dialog_content = "ไม่ ฉันเลิกเชื่อไปนานแล้ว",
  ui_story_1016_10161402_159_dialog_content = "นี่เป็นเพียง...คำตอบของปัญหาของฉันเอง คุณบอกให้ฉันคิดไปเองใช่ไหม?",
  ui_story_1016_10161402_160_dialog_content = "ถ้าคุณอยากไป ฉันจะไม่ห้ามคุณ",
  ui_story_1016_10161402_161_dialog_content = "แต่ฉันอยู่ที่นี่ ฉันต้องเรียนรู้ความจริงทั้งหมด... และหยุดพวกเขาไม่ให้ส่งคนไปตายมากกว่านี้",
  ui_story_1016_10161402_162_dialog_content = "ฉันจะไม่อนุญาต",
  ui_story_1016_10161402_163_dialog_content = "คุณคือวิชาทดสอบของฉัน จนกว่าคุณจะรับใช้ฉันอย่างไม่มีจุดหมายอีกต่อไป คุณจะมากับฉัน",
  ui_story_1016_10161402_164_dialog_content = "ไม่มีทางเลือกอื่นสำหรับคุณ",
  ui_story_1016_10161402_165_dialog_content = "ที่นี่! ฉันพบเป้าหมายแล้ว!",
  ui_story_1016_10161402_166_dialog_content = "ชิ",
  ui_story_1016_10161402_167_dialog_content = "ศัตรูพืชที่น่ารำคาญ",
  ui_story_1016_10161402_168_dialog_content = "!!!",
  ui_story_1016_10161402_169_dialog_content = "อย่าลังเล! การโจมตีของเธอไม่ได้ผลกับคุณ!",
  ui_story_1016_10161402_170_dialog_content = "ยังไม่ยอมแพ้ เอ๊ะ...?",
  ui_story_1016_10161402_171_dialog_content = "ไม่แน่นอน เราใช้มาตรการทุกวิถีทางเพื่อให้แน่ใจว่าอาชญากรที่อิลลูมินาต้องการตัวมากที่สุดจะไม่หลบหนี",
  ui_story_1016_10161402_172_dialog_content = "ไสหัวไปซะ!",
  ui_story_1016_10161402_173_dialog_content = "โฟกัสผู้ชาย! คราวนี้อย่าปล่อยให้พวกเขาหนีไปได้!",
  ui_story_1016_10161402_174_dialog_content = "หน่วย A สร้างแนวป้องกันและรุกเข้าหาศัตรู!",
  ui_story_1016_10161402_175_dialog_content = "Squad B เข้าขนาบข้างพวกเขาจากด้านหลังและตัดทางหนี!",
  ui_story_1016_10161402_176_dialog_content = "ครับ!",
  ui_story_1016_10161402_177_dialog_content = "ช่างน่ารำคาญ",
  ui_story_1016_10161402_178_dialog_content = "คุณกำลังรออะไรอยู่? ไปกันเถอะตัวอย่าง",
  ui_story_1016_10161402_179_dialog_content = "เปล่านะ...",
  ui_story_1016_10161402_180_dialog_content = "ฉันจะ... ฉันจะจับพวกมันไว้ให้นานที่สุดเท่าที่จะทำได้ ใช้เวลาในการหลบหนี",
  ui_story_1016_10161402_181_dialog_content = "แกคิดจะทำอะไรน่ะ?!",
  ui_story_1016_10161402_182_dialog_content = "<size=45>กลับมา!</size>",
  ui_story_1016_10161402_183_dialog_content = "พาเขาลง!",
  ui_story_1016_10161402_184_dialog_content = "<color=#e8d9bb>บูม—!!!</color>",
  ui_story_1016_10161402_185_dialog_content = "ไอ ไอ ไอ ไอ—!",
  ui_story_1016_10161402_186_dialog_content = "เขาดึงเพดานลงมาและขังตัวเองอยู่ข้างเรา!",
