  ui_story_1016_10161501_96_dialog_content = "คุณด้วย...",
  ui_story_1016_10161501_97_dialog_content = "<color=#e8d9bb>ในขณะเดียวกันในสถานที่วิจัยที่ไม่เปิดเผย</color>",
