  ui_story_1017_10170101_60_dialog_content = "อา...",
  ui_story_1017_10170101_61_dialog_content = "<size=30>เธอคือใคร?</size>",
  ui_story_1017_10170101_62_dialog_content = "เจ้าหน้าที่เบลิซาเรีย ความมั่นคงของเธอในคณะกรรมการมากมาย",
