  ui_story_1017_10171001_86_dialog_content = "งั้นทำไมคุณถึงประหม่าเมื่ออยู่ใกล้ฉันล่ะ? ความแตกต่างระหว่างฉันกับเธอคืออะไร?",
  ui_story_1017_10171001_87_dialog_content = "(ถึงกับต้องถามเลยเหรอ...?)",
  ui_story_1017_10171001_88_dialog_content = "เรียกฉันด้วยชื่อเถอะ ฉันก็จะเรียกคุณด้วยชื่อเพื่อแสดงความเคารพด้วย",
  ui_story_1017_10171001_89_dialog_content = "เข้าใจแล้ว, วราธ...",
  ui_story_1017_10171001_90_dialog_content = "ฉันขอความช่วยเสียงเกี่ยวกับทหารของฉันครับ/ค่ะ",
  ui_story_1017_10171001_91_dialog_content = "ได้สิ",
  ui_story_1017_10171001_92_dialog_content = "ไม่แน่ใจว่าพวกเขาจะแย่ขึ้นหรือไม่ในการต่อสู้ครั้งต่อไป",
  ui_story_1017_10171001_93_dialog_content = "ตอนนี้ฉันต้องการให้คุณล็อคตำแหน่งของพวกเขาและจัดการก่อนที่ศัตรูจะเริ่มโจมตีอย่างรุนแรง",
  ui_story_1017_10171001_94_dialog_content = "ไม่เป็นไร โซรอซก็สามารถช่วยได้เช่นกัน",
  ui_story_1017_10171001_95_dialog_content = "สแกนหาทหารผิดปกติ ระยะเวลาโดยประมาณ: 60 วินาที",
  ui_story_1017_10171001_96_dialog_content = "ฉันมีคำถาม",
  ui_story_1017_10171001_97_dialog_content = "ว่าไง",
  ui_story_1017_10171001_98_dialog_content = "เพราะอะไร Axelia อยู่ในทีมของคุณ?",
  ui_story_1017_10171001_99_dialog_content = "ตามที่ฉันจำได้ เธอได้รับบาดเจ็บสาหัสในการฝึกซ้อมและควรยังอยู่ในช่วงการฟื้นตัว",
  ui_story_1017_10171001_100_dialog_content = "นั่นคือความดื้อรั้นของทหารอิลลูมินา รู้ยัง?",
  ui_story_1017_10171001_101_dialog_content = "เสี่ยงชีวิตและเข้าสู่การต่อสู้ซ้ำ ๆ หลายครั้งหรือครับ?",
  ui_story_1017_10171001_102_dialog_content = "คุณไม่คิดว่าเธอทำได้หรือ?",
  ui_story_1017_10171001_103_dialog_content = "ฉันคิดว่าเธอสามารถทำได้ ฉันแค่รู้สึกว่าแอ็กซีเลีย...",
  ui_story_1017_10171001_104_dialog_content = "เธอจะไม่กลัวหรือใคร่สงครามเหมือนคนที่ฉันรู้จัก",
  ui_story_1017_10171001_105_dialog_content = "ฉันรู้สึกว่าเธอแสดงอารมณ์น้อยมากในการพบกันครั้งก่อน ๆ",
