  ui_story_1017_10171001_120_dialog_content = "...",
  ui_story_1017_10171001_121_dialog_content = "คุณสัมผัสอะไรได้บ้าง?",
  ui_story_1017_10171001_122_dialog_content = "...",
  ui_story_1017_10171001_123_dialog_content = "เขายังรู้สึกตัวอยู่บ้าง แต่ไม่ได้ยินเสียงคุณพูด",
  ui_story_1017_10171001_124_dialog_content = "ฉันจะลองเชื่อมจิตกับเขาแล้วดูว่าจะเจออะไรบ้าง",
  ui_story_1017_10171001_125_dialog_content = "ได้สิ",
  ui_story_1017_10171001_126_option_content = "เชื่อมโยงกระแสจิต—",
  ui_story_1017_10171001_127_dialog_content = "(ฉันอยู่ในบึงโคลนหรือเปล่า?)",
  ui_story_1017_10171001_128_dialog_content = "(มันคลุมพื้นดินเหมือนพรมยักษ์...)",
  ui_story_1017_10171001_129_dialog_content = "(ตัวอาคารที่ทรุดโทรมรอบ ๆ นี่ดูคุ้นเคย...)",
  ui_story_1017_10171001_130_dialog_content = "(นี่ควรจะเป็นทไวไลท์แน่นอน...)",
  ui_story_1017_10171001_131_dialog_content = "(แต่โคลนทั้งหมดนี้มาจากไหนกันนะ? มันยังคงรวมตัวอยู่ใต้เท้าฉัน...)",
  ui_story_1017_10171001_132_dialog_content = "(ดูเหมือนว่ามันไม่ไหลไปในทิศทางใดๆเลย...)",
  ui_story_1017_10171001_133_dialog_content = "อ๊ากก...",
