  ui_story_1017_10171001_155_dialog_content = "คุณ... อิคลิพไซท์!",
  ui_story_1017_10171001_156_dialog_content = "ถอยลง!",
  ui_story_1017_10171001_157_dialog_content = "วราธ? เกิดอะไรขึ้นกับเขาครับ?",
  ui_story_1017_10171001_158_dialog_content = "อย่ากังวลนะ เขาเพิ่งเป็นลมไปเท่านั้น",
  ui_story_1017_10171001_159_dialog_content = "แต่ไม่ต้องสืบสวนอะไรเพิ่มเติมแล้ว แม้กระทั่งฉันก็สามารถสัมผัสพลังความมืดในเขาได้ตอนนี้",
  ui_story_1017_10171001_160_dialog_content = "ดูขอบฟ้าทางนั้นสิ เริ่มมืดขึ้นเรื่อย ๆ...",
  ui_story_1017_10171001_161_dialog_content = "นั่นคือทิศทาง! โคลนกำลังไหลเร็วขึ้นและเร็วขึ้นจาก Eternal Night ในใจของเขา",
  ui_story_1017_10171001_162_dialog_content = "นั่นคงเป็นที่ตั้งของห้องควบคุมกลางแน่นอน!",
  ui_story_1017_10171001_163_dialog_content = "เราเจอตำแหน่งศัตรูแล้วหรือ?",
  ui_story_1017_10171001_164_dialog_content = "ฉันมั่นใจค่ะ ฉันคงใช้เวลากับพลังความมืดมากเกินไป เพราะฉันรู้สึกเวียนศีรษะเมื่อมองรอบ ๆ...",
  ui_story_1017_10171001_165_dialog_content = "คุณตอบถูกต้อง ท้องฟ้าเหนือคืนนิรันดร์กำลังมืดลง",
  ui_story_1017_10171001_166_dialog_content = "ดูเหมือนว่าพลังความมืดสามารถควบคุมทหารและเปลี่ยนแปลงสภาพแวดล้อม มีกลิ่นเหม็นอยู่รอบ ๆ",
  ui_story_1017_10171001_167_dialog_content = "<color=#e8d9bb>พูดพล่าม, พูดพล่าม...</color>",
  ui_story_1017_10171001_168_dialog_content = "คุณได้ยินไหม?",
  ui_story_1017_10171001_169_dialog_content = "เสียงนั้นคือเสียงของเหลวที่ไหล...",
  ui_story_1017_10171001_170_dialog_content = "ของเหลวไหล... โอ้ไม่, อย่าบอกฉันว่ามีหินถล่มใน Twilight!",
  ui_story_1017_10171001_171_dialog_content = "และมันมาจากดินแดนรัตติกาลนิรันดร์!",
  ui_story_1017_10171001_172_dialog_content = "ผมเชื่อว่าศัตรูกลางกำลังเข้ามาใกล้",
  ui_story_1017_10171001_173_dialog_content = "<color=#e8d9bb>พูดพล่าม, พูดพล่าม...</color>",
  ui_story_1017_10171001_174_dialog_content = "PlayerName ตรวจพบฝูงอิคลิพไซท์ขนาดใหญ่ทางตะวันตกของคุณ ประมาณจะเข้าสู่รัศมีการตรวจจับของคุณใน 5 วินาที",
  ui_story_1017_10171001_175_dialog_content = "เร็วขนาดนั้นเหรอ? ขอดูหน่อยนะ...",
  ui_story_1017_10171001_176_option_content = "เชื่อมโยงกระแสจิต—",
  ui_story_1017_10171001_177_dialog_content = "(ดำหมด... มันจริงๆ คือห้วงอารมณ์ที่น่าหลงใหล!)",
  ui_story_1017_10171001_178_dialog_content = "นี่คือสิ่งที่ฉันเห็นในใจของพวกเขาเลย วราธ! อิคลิพไซท์กำลังมาทางนี้พร้อมกับโคลน!",
  ui_story_1017_10171001_179_dialog_content = "หา?",
  ui_story_1017_10171001_180_dialog_content = "อัปเดตข้อมูลให้กับอัศวินลูโมทันทีและให้พวกเขาช่วยอพยพประชาชน!",
  ui_story_1017_10171001_181_dialog_content = "ค่ะ ท่านจอมทัพ!",
  ui_story_1017_10171001_182_dialog_content = "ลาดตระเวน มากับฉันตรวจสอบ กันเถอะ กลุ่มเครื่องยนต์ VII คุ้มกันแนวหลัง!",
  ui_story_1017_10171001_183_dialog_content = "ไม่มีใครเคลื่อนไหวหากไม่มีคำสั่งจากฉัน หากคุณรู้สึกว่ามีอะไรผิดปกติ ให้ถอนตัวทันที!",
  ui_story_1017_10171001_184_dialog_content = "ท่านจอมทัพ! ทหารในกองกำลังตะวันออกกำลังเป็นบ้าตามกันหนึ่งคนต่อหนึ่งคน!",
  ui_story_1017_10171001_185_dialog_content = "ตะวันออกเหรอ? แต่ที่ฉันสัมผัสอยู่คือทางตะวันตก...",
  ui_story_1017_10171001_186_dialog_content = "ระวัง!",
  ui_story_1017_10171001_187_dialog_content = "แม้แต่ที่นี่เหรอ? แต่จะเป็นไงล่ะ?",
  ui_story_1017_10171001_188_dialog_content = "เห็นได้ชัดว่าเราถูกล้อม",
  ui_story_1017_10171001_189_dialog_content = "อยู่ใกล้ ๆ ฉันนะ, PlayerName!",
  ui_story_1017_10171101_1_dialog_content = "<color=#e8d9bb>ตั้งแต่ไม่นานมานี้... ตัวอาคารห้องทดลองในอิลลูมินา</color>",
  ui_story_1017_10171101_2_dialog_content = "เธอกำลังทำอะไรน่ะ",
  ui_story_1017_10171101_3_dialog_content = "แค่เดินตรวจความเรียบร้อย... ใช่ครับ วันนี้เป็นกะของฉันในการดูแลพื้นที่นี้...",
  ui_story_1017_10171101_4_dialog_content = "นี่คือห้องปฏิบัติการของศาสตราจารย์ยูลิสซิส และไม่มีตารางการตรวจตราระยะปกติ",
  ui_story_1017_10171101_5_dialog_content = "เอ่อ ก็...",
  ui_story_1017_10171101_6_dialog_content = "ใครส่งคุณมา?",
  ui_story_1017_10171101_7_dialog_content = "ฉัน...",
  ui_story_1017_10171101_8_dialog_content = "ฉัน-ฉันขอโทษค่ะ ผู้บัญชาการ Yingel! ฉันไม่ควรจะโกหก ฉันแค่...",
  ui_story_1017_10171101_9_dialog_content = "ฉันรู้ว่าพี่ชายของฉันเป็นส่วนหนึ่งของ<color=#FFB400>การทดลอง</color>ที่ยิ่งใหญ่ที่สุดในประวัติศาสตร์ของอิลลูมินา และฉันรู้สึกอิจฉาจริงๆ ซึ่งเป็นเหตุผลว่าทำไมฉัน...",
  ui_story_1017_10171101_10_dialog_content = "โครงการนี้เป็นความลับสูง และไม่ควรให้สมาชิกในครอบครัวรู้จนกว่าจะประสบความสำเร็จ",
  ui_story_1017_10171101_11_dialog_content = "พี่ชายฉันกับฉันใกล้ชิดกันมาก ดังนั้นฉันรู้ทุกอย่างเกี่ยวกับเขา โปรดเชื่อฉัน! ฉันพูดความจริง...",
  ui_story_1017_10171101_12_dialog_content = "...",
