  ui_story_1017_10171301_46_dialog_content = "(โคลนกำลังปกคลุมและก่อตัวเป็นรูปภาพ...)",
  ui_story_1017_10171301_47_dialog_content = "(นี่คือ... ยูลิสซิส, เบลิซาเรีย, และบนจอคือ...)",
  ui_story_1017_10171301_48_dialog_content = "(มันหายไปก่อนที่ฉันจะอ่านคำอื่น ๆ ได้... วราธไม่อยู่ตรงนี้แน่นอน)",
  ui_story_1017_10171301_49_dialog_content = "(อีกแสงเรือง!)",
  ui_story_1017_10171301_50_dialog_content = "(นี่คือไรน์ฮาร์ต!)",
  ui_story_1017_10171301_51_dialog_content = "(ไรน์ฮาร์ตเยาว์... และผู้ชม, ป้ายประกาศ...)",
  ui_story_1017_10171301_52_dialog_content = "(\"การทดสอบสุดท้ายของจอมทัพอิลลูมินา\"... พ่ายแพ้ให้ไรน์ฮาร์ต นี่หาย)",
  ui_story_1017_10171301_53_dialog_content = "(ฝน...?)",
  ui_story_1017_10171301_54_dialog_content = "(ฝนตกในที่ที่ดูเหมือนเมืองใต้ดิน?)",
  ui_story_1017_10171301_55_dialog_content = "(นั่นคงเป็นวันที่น่าจดจำสำหรับคุณวราธ...)",
  ui_story_1017_10171301_56_dialog_content = "(นี่คือ... ห้องปฏิบัติการอิลลูมินา)",
  ui_story_1017_10171301_57_dialog_content = "(ฉันเห็นยูลิสซิสและคนอื่น ๆ รอบ ๆ เตียงห้องทดลอง)",
  ui_story_1017_10171301_58_dialog_content = "(อยู่บนเตียงคือ...)",
  ui_story_1017_10171301_59_dialog_content = "(ไรน์ฮาร์ท?)",
  ui_story_1017_10171301_60_dialog_content = "(ได้ยังไงที่มันจะเป็นไรน์ฮาร์ด?)",
  ui_story_1017_10171301_61_dialog_content = "(และไม่ใช่วราธ?!)",
  ui_story_1017_10171301_62_dialog_content = "(รอสักครู่นะ คนข้างเตียงไม่ใช่ยูลิสซิส... แต่เป็นวราธ!)",
  ui_story_1017_10171301_63_dialog_content = "(คุณได้ยินฉันหรือเปล่า, วราธ?!)",
  ui_story_1017_10171301_64_dialog_content = "(...)",
  ui_story_1017_10171301_65_dialog_content = "(ตื่นขึ้นเถอะ คุณกำลังอยู่ใน Twilight ต่อสู้กับ Eclipsites นะตอนนี้!)",
  ui_story_1017_10171301_66_dialog_content = "(อิคลิพไซท์... ใครขึ้นเตียงก็จะกลายเป็นอิคลิพไซท์...)",
  ui_story_1017_10171301_67_dialog_content = "(ทไวไลท์กำลังจะถูกทำลายลงและคุณบาดเจ็บทั่วทั้งร่างกาย! ตื่น!)",
  ui_story_1017_10171301_68_dialog_content = "(ทำไม Reinhardt ถึงไม่เคยโดนบาดเจ็บเลย?)",
  ui_story_1017_10171301_69_dialog_content = "(เพราะเธอเป็นอิคลิพไซท์)",
  ui_story_1017_10171301_70_dialog_content = "(ทุกคนก็บาดเจ็บค่ะ! แต่คุณคือท่านจอมทัพ และทหารต้องการคุณ!)",
  ui_story_1017_10171301_71_dialog_content = "(ท่านจอมทัพ...)",
  ui_story_1017_10171301_72_dialog_content = "(ได้ผลมั้ย? ขอลองวิธีอื่นนะครับ)",
  ui_story_1017_10171301_73_dialog_content = "(การทดสอบครั้งสุดท้ายของจอมทัพ!)",
  ui_story_1017_10171301_74_dialog_content = "(คุณยังไม่ได้เอาชนะ Reinhardt กลับไปต่อสู้กัน!)",
  ui_story_1017_10171301_75_dialog_content = "(ไรน์ฮาร์ต... โฮร่! ไรน์ฮาร์ต!)",
  ui_story_1017_10171301_76_dialog_content = "(ใช่ครับ ไรน์ฮาร์ตยังอยู่ในสนามประลอง ไปพิสูจน์ว่าคุณดีกว่าเขา!)",
  ui_story_1017_10171301_77_dialog_content = "(คุณวราธ...!)",
  ui_story_1017_10171301_78_dialog_content = "PlayerName เธอฟื้นสติในที่สุดแล้วนะ",
  ui_story_1017_10171301_79_dialog_content = "ฉันสบายดี วราธอยู่ที่ไหน? เธอเป็นอย่างไรบ้าง?",
  ui_story_1017_10171301_80_dialog_content = "การประเมินเบื้องต้นแสดงให้เห็นว่าสติของเธอดูเหมือนจะฟื้นคืนครบถ้วนแล้ว และเธอสามารถปราบอิคลิพไซท์ได้อีกครั้ง",
  ui_story_1017_10171301_81_dialog_content = "วิเศษ!",
  ui_story_1017_10171301_82_dialog_content = "สิ่งที่คุณทำเมื่อกี้ การเริ่มบังคับเชื่อมกระแสจิตในขณะที่สภาพของวราธยังไม่แน่นอน นั้นเสี่ยงมากเลยครับ",
  ui_story_1017_10171301_83_dialog_content = "ฉันรู้ แต่มันเป็นเรื่องฉุกเฉินและฉันไม่มีเวลาเสียเลย...",
  ui_story_1017_10171301_84_dialog_content = "อาจเป็นเพราะมีคุณอยู่ด้วย ทำให้ฉันรู้สึกปลอดภัย",
  ui_story_1017_10171301_85_dialog_content = "หันไปทางขวาของคุณ - มันคืออัศวินไอรอนธรที่ทำให้คุณปลอดภัย",
  ui_story_1017_10171301_86_dialog_content = "ลีโอและคณะมาถึงแล้ว!",
  ui_story_1017_10171301_87_dialog_content = "พวกเขาเข้าร่วมการต่อสู้เมื่อคุณเชื่อมต่อกับวราธ",
  ui_story_1017_10171301_88_dialog_content = "ขอบคุณค่ะ, โซรอซ!",
  ui_story_1017_10171301_89_dialog_content = "โซรอซจะคอยนำทางให้คุณต่อไป",
  ui_story_1017_10171301_90_dialog_content = "หอกสายฟ้า ทิ่มแทง!",
  ui_story_1017_10171301_91_dialog_content = "เมื่อกี้คุณพูดพล่ามอะไรน่ะ?",
  ui_story_1017_10171301_92_option_content = "ฉันพยายามช่วย",
  ui_story_1017_10171301_93_dialog_content = "ดีใจที่เห็นคุณกลับมาอยู่กับเราอีกครั้ง",
  ui_story_1017_10171301_94_dialog_content = "ใส่ใจธุรกิจของคุณเอง!",
  ui_story_1017_10171301_95_option_content = "ฉันไม่ได้ตั้งใจพูดแบบนั้น",
  ui_story_1017_10171301_96_dialog_content = "ฉันแค่พยายามที่จะทำให้คุณตั้งสติ...",
  ui_story_1017_10171301_97_dialog_content = "เลิกมองสิ่งที่ไม่ควรดูเถอะ รับทราบไหม?",
  ui_story_1017_10171301_98_dialog_content = "เอิ่ม, ดีใจที่เห็นคุณตำหนิฉันอย่างนั้นอีกครั้ง!",
  ui_story_1017_10171301_99_dialog_content = "เรายังต้องปกป้อง Twilight",
  ui_story_1017_10171301_100_dialog_content = "แม้ว่าฉันจะกลายเป็นอิคลิพไซท์ ฉันจะเป็นคนที่รับผิดชอบให้เมืองคงอยู่อย่างไม่เสียหาย!",
  ui_story_1017_10171301_101_dialog_content = "เรียน, กองพลยาม!",
  ui_story_1017_10171301_102_dialog_content = "เราทุกคนเคยประสบความไม่สบายในระดับต่าง ๆ ในการต่อสู้ แต่เชื่อผม มันเป็นเพียงชั่วคราวเท่านั้น",
  ui_story_1017_10171301_103_dialog_content = "พยายามสมาธิ มันจะช่วยลดผลกระทบลบของพลังความมืดลงเยอะเลย",
  ui_story_1017_10171301_104_dialog_content = "ฉันรับประกันว่าฉันจะหาทหารที่หายไปทุกคน แต่ในระหว่างนี้ ฉันต้องการความช่วยเสริมจากทุกคนในทีม!",
  ui_story_1017_10171301_105_dialog_content = "ใครที่บาดเจ็บหรือยังไม่ตื่นสำนึกอย่างสมบูรณ์ รีบกลับไปที่อิลลูมินาทันที!",
  ui_story_1017_10171301_106_dialog_content = "คุณท่านที่ยังสามารถต่อสู้หรือ<color=#FFB400>ไม่กลัวผลกระทบของพลังความมืด</color> ตามฉันไปโจมตีที่สำนักงานควบคุมกลาง!",
  ui_story_1017_10171301_107_dialog_content = "รับทราบ!!!",
  ui_story_1017_10171401_1_dialog_content = "คุณอิ่มอยู่หรือยัง?",
  ui_story_1017_10171401_2_dialog_content = "ไม่ใกล้เคียงเลย—",
  ui_story_1017_10171401_3_dialog_content = "ทุกอย่างดีต้องเก็บไว้สุดท้ายเสมอ แน่นอน \"พรม\" ก็วางอยู่อย่างสวยงาม",
  ui_story_1017_10171401_4_dialog_content = "กลืนกินพวกมันทั้งหมด—",
