  ui_story_1017_10171401_12_dialog_content = "...",
  ui_story_1017_10171401_13_dialog_content = "เฮ้อ ฉันคาดหวังมากกว่านี้ ไม่คิดว่าจะเจอคนโง่ที่ไม่สามารถต่อสู้หลุดออกจากถุงกระดาษเปียกเลย",
