  ui_story_1017_10171501_94_dialog_content = "<color=#e8d9bb>วันต่อมา...</color>",
  ui_story_1017_10171501_95_dialog_content = "เป็นยังไงบ้าง?",
  ui_story_1017_10171501_96_dialog_content = "ไม่ทำอะไรทั้งนั้นล่ะ",
