  ui_story_1018_10180401_111_dialog_content = "หวา—! ช่วยที!",
  ui_story_1018_10180401_112_dialog_content = "พวกเขาเข้าสู่สถานะเบอร์เซิร์กแล้ว ท่านจอมทัพวราธ ฉันต้องจัดการพวกเขาเหมือนกับอิคลิพไซท์!",
  ui_story_1018_10180401_113_dialog_content = "ไม่ นั่นไม่ใช่...",
  ui_story_1018_10180401_114_dialog_content = "เรามีอิคลิพไซท์อยู่ข้างหลังเรา! ถ้าเราไม่ดำเนินการ โคลนจะทำให้เราจมทั้งหมด!",
  ui_story_1018_10180401_115_dialog_content = "สิงห์...",
  ui_story_1018_10180401_116_dialog_content = "<color=#e8d9bb>*เสียงนกหวีดของรถไฟในลมพัด*</color>",
  ui_story_1018_10180401_117_dialog_content = "ไม่นะ อีกตัวแล้ว!",
  ui_story_1018_10180401_118_dialog_content = "ฉันได้ยินเสียงนกหวีดของรถไฟ...",
  ui_story_1018_10180401_119_dialog_content = "คุณครับ! แผนที่แสดงว่านี่คือ... ทไวไลท์?",
  ui_story_1018_10180401_120_dialog_content = "วาร์ปทำเรื่องนี้ใช่ไหมคุณวิกตอเรีย? เรามาที่นี่เพราะอะไรครับ?",
  ui_story_1018_10180401_121_dialog_content = "เราได้หนีออกจาก The Warp และฉันได้นำรถไฟมาที่นี่ตามความปรารถนารักของนางวิส",
  ui_story_1018_10180401_122_dialog_content = "ทไวไลท์เป็นอยู่ที่ปลายของเส้นรัศมี",
  ui_story_1018_10180401_123_dialog_content = "ไม่อยากจะเชื่อเลย...",
  ui_story_1018_10180401_124_dialog_content = "ครับผม ฉันเห็นคนเยอะๆ อยู่ที่โน้น มันจะเป็น PlayerName และคนอื่นๆ หรือเปล่าครับ?",
  ui_story_1018_10180401_125_dialog_content = "มีโคลนเยอะใต้รถไฟ ระวังอิคลิพไซท์ที่อาจอยู่ในนั้นนะ",
  ui_story_1018_10180401_126_dialog_content = "โคลนสกปรก อิคลิพไซท์สกปรก! ด้านอื่น ๆ จะบดขยี้พวกเขา!",
  ui_story_1018_10180401_127_dialog_content = "เกาะแน่น ๆ นะทุกคน เรากำลังจะผ่านที่โคลนเพื่อหยุดข้างหน้า!",
  ui_story_1018_10180401_128_dialog_content = "<color=#e8d9bb>*เสียงนกหวีดของรถไฟ*</color>",
  ui_story_1018_10180401_129_dialog_content = "สวัสดีครับ ท่านจอมทัพวราธ—",
  ui_story_1018_10180401_130_dialog_content = "ยินดีด้วยที่ได้รับตำแหน่ง ขอโทษที่มาช้านะ!",
  ui_story_1018_10180401_131_dialog_content = "ท่านจอมทัพวราธ! PlayerName!",
  ui_story_1018_10180401_132_dialog_content = "ไวซ์!",
  ui_story_1018_10180401_133_dialog_content = "คารอน, ไวซ์... คุณทำอะไรอยู่ที่นี่?",
  ui_story_1018_10180401_134_dialog_content = "คุณไม่ได้อยู่ในภารกิจหรือไง? ทำไมถึงอยู่ใน Twilight?",
  ui_story_1018_10180401_135_dialog_content = "ระวังเวลานะคุณคอนดักเตอร์ นี่เป็นการหยุดชั่วคราวเท่านั้น",
  ui_story_1018_10180401_136_dialog_content = "ฉันได้ยินเรื่องการต่อสู้ใน Twilight และฉันก็ห่วงใย จอมพลครับ อย่างไรก็ตาม ฉันไม่สามารถอยู่นานเกินไปก่อนที่จะต้องกลับไปดำเนินภารกิจต่อ",
  ui_story_1018_10180401_137_dialog_content = "คุณวิ่งข้ามอิคลิพไซท์ไปแล้ว นั่นก็ช่วยเยอะแล้วนะ",
  ui_story_1018_10180401_138_dialog_content = "อีกด้านหนึ่ง คุณเป็นคนสร้างพายุแรงด้วยตัวเอง ไม่ใช่ศัตรูใช่ไหม?",
  ui_story_1018_10180401_139_dialog_content = "เราไม่ได้มาที่นี่โดยบังเอิญ แต่ฉันไม่มีเวลาอธิบาย โคลนยืดไกลมาก อาจมีอิคลิพไซท์เพิ่มเติมอยู่ด้วย",
  ui_story_1018_10180401_140_dialog_content = "ลมหมายความว่าเดอะวาร์ปจะเริ่มทำงานอีกครั้งใช่ไหมคะ ท่านหญิง...?",
  ui_story_1018_10180401_141_dialog_content = "ไม่ใช่หรือว่าไม่สามารถพักผ่อน... นั่งพักสักครู่เถอะ ฉันจะพาทุกคนไปด้วยกัน",
