  ui_story_1018_10180602_16_dialog_content = "ฉันเป็นเพียงอัศวินที่อาศัยอยู่ใน Twilight ฉันไม่มีความรับผิดชอบในการบังคับบัญชากองทัพทั้งหมดเหมือนคุณ",
  ui_story_1018_10180602_17_dialog_content = "ความเมตตาจะนำไปสู่ความสูญเสียที่มากขึ้น คุณต้องเรียนรู้ที่จะเผชิญกับความเป็นจริงนั้น",
  ui_story_1018_10180602_18_dialog_content = "ไม่ ฉันไม่สามารถทนกับเลือดที่เต็มไปหมดในมือของฉัน...",
  ui_story_1018_10180602_19_dialog_content = "ฉันสัญญากับพวกเขาว่าฉันจะนำพวกเขาสู่ชัยชนะในการต่อสู้ครั้งนี้...",
  ui_story_1018_10180602_20_dialog_content = "แทนที่จะช่วย ฉันกลับพาพวกเขาไปสู่สุสาน...",
  ui_story_1018_10180602_21_dialog_content = "(ฉันคิดว่าถ้าฉันมีพลัง ถ้าฉันแข็งแกร่งพอ ฉันก็สามารถทำอะไรก็ได้)",
  ui_story_1018_10180602_22_dialog_content = "(แข็งแกร่งพอแล้วหรือ... นี่คือตลก...)",
  ui_story_1018_10180602_23_dialog_content = "วราธ ฉันคิดว่าสิ่งที่คุณทำยากกว่าการพยายามเป็นคนที่แข็งแกร่งครับ",
  ui_story_1018_10180602_24_dialog_content = "...",
  ui_story_1018_10180602_25_dialog_content = "การนำตัวเองเข้าสู่ความอันตรายเป็นหน้าที่ของนักรบ",
  ui_story_1018_10180602_26_dialog_content = "เมื่อพวกเขาเป็นอันตรายเองและไม่สามารถปกป้องชีวิต...",
  ui_story_1018_10180602_27_dialog_content = "นี่คือสิ่งเดียวที่เราทำเพื่อพวกเขาในฐานะผู้บัญชาการ",
  ui_story_1018_10180602_28_dialog_content = "ผู้บัญชาการ...",
  ui_story_1018_10180602_29_dialog_content = "(นี่คือสิ่งที่คุณหมายถึงในการปล่อยมือ ไรน์ฮาร์ต... เหรอ?)",
  ui_story_1018_10180602_30_dialog_content = "เชื่อฉันเถอะ ทหารของคุณกำลังตายในที่ที่พวกเขาควรจะอยู่ และความทุกข์ของพวกเขาจะสิ้นสุดเร็ว ๆ นี้",
  ui_story_1018_10180602_31_dialog_content = "รอสักครู่นะลีโอ",
  ui_story_1018_10180602_32_dialog_content = "คุณน่าจะถูกเรื่องพวกเขาตายในที่ที่ควร...",
  ui_story_1018_10180602_33_dialog_content = "ฉันต้องเผชิญกับความเป็นจริง",
  ui_story_1018_10180602_34_dialog_content = "แทนที่จะให้มีชีวิตอยู่ในความทุกข์ยาก ฉันจะทำให้มันรวดเร็วและง่ายสำหรับพวกเขา",
  ui_story_1018_10180602_35_dialog_content = "จอมพล...",
  ui_story_1018_10180602_36_dialog_content = "ทหารทุกคน โปรดให้ฉันพูดคำลาสุดท้ายกับเพื่อนร่วมทีมเก่าของคุณสักหน่อย",
  ui_story_1018_10180602_37_dialog_content = "ไม่ว่าอะไร เราจะติดตามคุณเสมอ!",
  ui_story_1018_10180602_38_dialog_content = "...",
  ui_story_1018_10180602_39_dialog_content = "แม้ว่าคุณจะไม่เข้าใจที่ฉันพูด ฉันขอสัญญาให้คุณ...",
  ui_story_1018_10180602_40_dialog_content = "คุณคือทหารของอิลลูมินา ที่เกิดมาเพื่อรับใช้อิลลูมินาอย่างภูมิใจ และแบกรับหน้าที่ในการทำลายอิคลิพไซท์",
  ui_story_1018_10180602_41_dialog_content = "คุณรู้ว่าการต่อสู้เป็นเส้นทางที่สั้นที่สุดสู่ความตาย แต่คุณก้าวหน้าไปโดยไม่กลัว...",
  ui_story_1018_10180602_42_dialog_content = "เธอจะตายในฐานะนักรบกล้าของอิลลูมินา...",
  ui_story_1018_10180602_43_dialog_content = "ไม่ใช่คนที่ถูกบังคับให้ถูกทอดทิ้ง...",
  ui_story_1018_10180602_44_dialog_content = "เราจะดำเนินภารกิจที่คุณยังไม่เสร็จและสู้ต่อไป!",
  ui_story_1018_10180602_45_dialog_content = "โฮก...",
  ui_story_1018_10180602_46_dialog_content = "(นั่นแหละ วราธ มันจะจบไปอย่างรวดเร็ว...)",
  ui_story_1018_10180602_47_dialog_content = "และคุณปลดพันจากความผูกพันแล้ว สามารถฉลองได้ตามสบาย...",
  ui_story_1018_10180602_48_dialog_content = "ชัยชนะในสถานที่ที่ไม่มีสงคราม",
  ui_story_1018_10180602_49_dialog_content = "แกรห์!",
  ui_story_1018_10180602_50_dialog_content = "นักซุ่มยิงเล็งเป้า...",
  ui_story_1018_10180602_51_dialog_content = "ยิง!",
  ui_story_1018_10180602_52_dialog_content = "<color=#e8d9bb>ปัง! ปัง! ปัง!</color>",
  ui_story_1018_10180602_53_dialog_content = "...",
  ui_story_1018_10180602_54_dialog_content = "สงครามสิ้นสุดสำหรับคุณแล้ว พักผ่อนให้สบาย",
  ui_story_1018_10180602_55_dialog_content = "...",
  ui_story_1018_10180602_56_dialog_content = "...",
  ui_story_1018_10180701_1_dialog_content = "<color=#e8d9bb>ในทางไปยังฐานที่มั่นลูโม่...</color>",
  ui_story_1018_10180701_2_dialog_content = "ฐานที่มั่นลูโม่อยู่ข้างหน้าแค่นี้เอง ชิ คุณเป็นอย่างไรบ้าง?",
  ui_story_1018_10180701_3_dialog_content = "อืม... ฉันยังมีพลังงานเหลืออยู่บ้าง...",
