  ui_story_1018_10180702_42_dialog_content = "...",
  ui_story_1018_10180702_43_dialog_content = "ไม่จำเป็นต้องตอบกลับทุกคน ท่านผู้บริสุทธิ์",
  ui_story_1018_10180702_44_dialog_content = "แต่นี่เป็นครั้งแรกที่ฉันได้พบกับออโรเรียนนอกจากวัด...",
  ui_story_1018_10180702_45_dialog_content = "ไม่ต้องตอบก็ได้ครับ",
  ui_story_1018_10180702_46_dialog_content = "ได้สิ",
  ui_story_1018_10180702_47_dialog_content = "เลดี้เซนต์ได้รับความนับถือจากท่านทั้งหมดแล้วค่ะ",
  ui_story_1018_10180702_48_dialog_content = "ขอบคุณนะ คาร์ลีน ฉันแท้จริงมีความสุขมากเลย!",
  ui_story_1018_10180702_49_dialog_content = "อืม, คุณคือใคร? ทำไมคุณถึงจ้องมองฉันแบบนั้น...?",
  ui_story_1018_10180702_50_dialog_content = "เรื่องอะไรกับเขาบนหัวของคุณล่ะ?",
  ui_story_1018_10180702_51_dialog_content = "ระวังมารยาทหน่อย—",
  ui_story_1018_10180702_52_dialog_content = "ไม่เป็นไร!",
  ui_story_1018_10180702_53_dialog_content = "นี่คือเรื่องที่เกี่ยวข้องกับ<color=#FFB400>เสือโคร่ง</color>...",
  ui_story_1018_10180702_54_dialog_content = "คุณกำลังพูดถึงตำนานของผู้พิทักษ์เสือโคร่งหรือเปล่า? ฉันได้ยินเรื่องนี้มาตั้งแต่เด็กนะ นี่คือเนื้อเรื่องของตำนานนั้น...",
  ui_story_1018_10180702_55_dialog_content = "<color=#e8d9bb>หลังจากโจเซลีนดูแลคนที่บาดเจ็บแล้ว...</color>",
  ui_story_1018_10180702_56_dialog_content = "สวัสดีครับ ท่านเซนเทส! ข้าพเจ้าโจเซลีนขอขอโทษที่มาสายครับ",
  ui_story_1018_10180702_57_dialog_content = "สวัสดีค่ะ โจเซลีน คุณพ่อโจเซฟพูดถึงคุณกับฉัน และฉันยินดีที่จะช่วยค่ะ",
  ui_story_1018_10180702_58_dialog_content = "ฉันอับอายที่ไม่สามารถช่วยชาวออโรเรียนที่ถูกทำร้ายโดยอิคลิพไซท์ และขอขอบคุณคุณที่รักษาพวกเขาด้วยอาร่าของคุณ",
  ui_story_1018_10180702_59_dialog_content = "อย่ารู้สึกอับอาย คุณทำทุกอย่างเท่าที่คุณสามารถเพื่อช่วยเหลือพวกเขา คุณเป็นคนใจดีอยู่แล้ว",
  ui_story_1018_10180702_60_dialog_content = "ถ้าคุณไม่มีปัญหา โปรดเรียกฉันว่าฮิลด้า นั่นคือชื่อของฉัน และฉันมีเรื่องที่อยากจะถามคุณเยอะเลย!",
  ui_story_1018_10180702_61_dialog_content = "ฉันจะเรียกเธอด้วยชื่อยังไงล่ะ? เธอนี่ท่านนางพญาเซนต์เสียด้วยนะ!",
  ui_story_1018_10180702_62_dialog_content = "โจเซลีน ฉันพบว่าเลดี้เซนต์เทสอบอุ่นและใจดีพอๆ กับพี่สาวน้องสาวในทไวไลท์",
  ui_story_1018_10180702_63_dialog_content = "โอ้ และฉันยังไม่ได้จบเรื่องราวนะ ชิ! ในที่สุด...",
  ui_story_1018_10180702_64_dialog_content = "...",
  ui_story_1018_10180702_65_dialog_content = "คิดอะไรอยู่เหรอคะ ท่านหญิงโจเซลีน?",
  ui_story_1018_10180702_66_dialog_content = "ท่านหญิงคาร์ลีน ฉันไม่เคยคิดเลยว่า...",
  ui_story_1018_10180702_67_dialog_content = "ท่านหญิงเซนต์เสิสต์จริง ๆ แล้วมีบรรยากาศความใสซื่อเหมือนเด็กน้อย",
  ui_story_1018_10180702_68_dialog_content = "ต้องสาระสาคัญครับ ครั้งแรกที่ฉันพบเธอ ฉันก็ตกใจกับความ... อ่อนต่อโลกของเธอเช่นกัน",
  ui_story_1018_10180702_69_dialog_content = "แต่คุณเห็นว่าเธอเข้ากับผู้หญิงที่อายุเท่ากับชิอย่างเป็นธรรมชาติ และเธอสนใจในเรื่องราวที่เกิดขึ้นรอบ ๆ ทไวไลท์มากเลย",
  ui_story_1018_10180702_70_dialog_content = "อาจเป็นเพราะเธอยังค้นหาทางของตัวเองในฐานะที่เกินกว่าท่านหญิงเซนเทส",
  ui_story_1018_10180702_71_dialog_content = "คุณพูดถูก ฉันมองแคบเกินไป",
  ui_story_1018_10180702_72_dialog_content = "เจ้าไม่วางแผนที่จะอยู่หลังจากส่งคนบาดเจ็บให้โบสถ์หรือเปล่า?",
  ui_story_1018_10180702_73_dialog_content = "การต่อสู้ใน Twilight ยังไม่จบหรอก ฉันต้องกลับไปสู้คู่กับนักรบ",
  ui_story_1018_10180702_74_dialog_content = "ฉันรู้สึกสบายใจที่รู้ว่าคุณพ่อโจเซฟอยู่ที่นี่",
  ui_story_1018_10180702_75_dialog_content = "ตกลงครับ ฉันจะนำกำลังเสริมลูโมโพลิสและไปกับคุณ",
  ui_story_1018_10180702_76_dialog_content = "ฉันก็จะไปด้วย! เรายังทำได้ใช่ไหม?",
