  ui_story_1018_10180801_65_dialog_content = "โฮก...",
  ui_story_1018_10180801_66_dialog_content = "คุณเคยสละชีวิตตัวเองหนึ่งครั้งแล้ว...",
  ui_story_1018_10180801_67_dialog_content = "ฉันไม่สามารถให้คุณ...",
  ui_story_1018_10180801_68_dialog_content = "แอ็กซีเลียรู้สึกถึงความโกรธของท่านจอมทัพ...",
  ui_story_1018_10180801_69_dialog_content = "อะไรกันเนี่ย...",
  ui_story_1018_10180801_70_dialog_content = "Axelia ต้องการปกป้อง Grand Marshal และถึงแม้ว่า Axelia จะไม่สามารถรู้สึกความอบอุ่นของร่างกาย...",
  ui_story_1018_10180801_71_dialog_content = "อิงเกลบอกฉันว่านี่คือที่ที่หัวใจของแอ็กซีเลียอยู่",
  ui_story_1018_10180801_72_dialog_content = "ฉันคิดว่ามันร้อนกว่าพลังที่อยู่ในตัวเรานั่นแหละ",
  ui_story_1018_10180801_73_dialog_content = "แอ็กซีเลีย...",
  ui_story_1018_10180801_74_dialog_content = "ไม่ต้องห่วง ฉันจะไม่ปล่อยให้มันควบคุมฉัน",
  ui_story_1018_10180801_75_dialog_content = "กัปตัน... กองกำลังทั้งหมดกำลังมาทางนี้! เราจะทำอย่างไรต่อดี?",
  ui_story_1018_10180801_76_dialog_content = "ความโคล่... ไม่, พลังความมืด มันซึมออกมาจากร่างกายพวกเขา! ฉันเห็นเช่นนั้น! มีแสงแปลกๆ ในตาของทหาร!",
  ui_story_1018_10180801_77_dialog_content = "<color=#e8d9bb>ฟิ้วว—</color>",
  ui_story_1018_10180801_78_dialog_content = "หอกสายฟ้า ทิ่มแทง!",
  ui_story_1018_10180801_79_dialog_content = "วิญญาณของพวกเขาได้ออกไปนานแล้ว การต่อสู้ต่อไปของพวกเขาจะทำให้ชื่อเสียงของพวกเขาเสื่อมค่าเท่านั้น",
  ui_story_1018_10180801_80_dialog_content = "ทุกคนฟังดีๆ! อย่าให้ทหารของเราทนทุกข์เพิ่มเติม พวกเขาปกป้องเราและไม่ควรต้องสละเสียสำหรับสิ่งที่ไม่มีค่า!",
  ui_story_1018_10180801_81_dialog_content = "ค่ะ ท่านจอมทัพ",
  ui_story_1018_10180801_82_dialog_content = "เอาล่ะ ไม่มีความเมตตา งั้นคุณคงไม่ว่ากันหากฉันเอาที่เหลือไปด้วย...",
  ui_story_1018_10180801_83_dialog_content = "อย่าพยายามวิ่ง!",
  ui_story_1018_10180801_84_dialog_content = "ทหารไม่ได้เข้าไปในโคลนหรือเปล่า...",
  ui_story_1018_10180801_85_dialog_content = "พวกเขาคือผู้ใต้บังคับบัญชาของ Axelia",
  ui_story_1018_10180801_86_dialog_content = "Axelia จะนำทีมหมายเลขแปด!",
  ui_story_1018_10180801_87_dialog_content = "แอ็กซีเลียจะไม่เป็นไรใช่ไหม...?",
  ui_story_1018_10180801_88_dialog_content = "ทหารที่วิ่งไปกับเธอมีความภักดี ดังนั้นไม่ควรมีปัญหา",
  ui_story_1018_10180801_89_dialog_content = "เสร็จที่นี่แล้วเราค่อยคุยกันเถอะ!",
  ui_story_1018_10180801_90_dialog_content = "เอาสิ!",
  ui_story_1018_10180802_1_dialog_content = "ยังตามมาในสภาพนี้อีกรึ?",
  ui_story_1018_10180802_2_dialog_content = "แอ็กซีเลีย... ต้องปกป้องพวกเขา... โปรดคืนพวกเขาให้ฉัน",
  ui_story_1018_10180802_3_dialog_content = "แล้วนี่คงต้องฆ่าฉันให้ได้เหรอ",
  ui_story_1018_10180802_4_dialog_content = "แอ็กซีเลีย... จะนำทีมที่แปดกลับบ้าน!",
  ui_story_1018_10180802_5_dialog_content = "นี่คือการฆ่าที่ควรเป็นอยู่แล้ว!",
  ui_story_1018_10180802_6_dialog_content = "เปล่านะ...",
  ui_story_1018_10180802_7_dialog_content = "กัปตัน Axelia, คุณ... สบายดีไหม?",
  ui_story_1018_10180802_8_dialog_content = "...",
  ui_story_1018_10180802_9_dialog_content = "นั่นความเศร้าที่ฉันเห็นบนใบหน้าของสร้างที่ไม่มีอารมณ์ของยูลิสซิสเหรอ?",
  ui_story_1018_10180802_10_dialog_content = "แอ็กซีเลีย... ไม่ไร้ความรู้สึก",
  ui_story_1018_10180802_11_dialog_content = "ยังไม่ยอมรับเหรอ?",
  ui_story_1018_10180802_12_dialog_content = "อย่าทำร้ายพวกเขา... พวกเขากำลังทนความทุกข์ยาก...",
  ui_story_1018_10180802_13_dialog_content = "พวกเขาดูเหมือนจะได้ยินคำพูดของคุณรึเปล่าครับ?",
  ui_story_1018_10180802_14_dialog_content = "แอ็กซีเลียจะไม่ยอมให้คุณหลุดพ้นจากสิ่งนี้...",
  ui_story_1018_10180802_15_dialog_content = "นอกจากมองดูฉันบีบออกชีวิตจากพวกเขาแล้ว คุณจะทำอะไรได้อีกล่ะ?",
  ui_story_1018_10180802_16_dialog_content = "(ภาษาอิคลิพส์) นายท่าน มัดบันเดิลพร้อมแล้วและกำลังรอคำสั่งครับ",
  ui_story_1018_10180802_17_dialog_content = "ถ้าอย่างนั้นก็ตาม คุณขออย่างนี้ ฉันจะให้เธอหน่อยละกัน แต่ที่เหลือนั่น...",
  ui_story_1018_10180802_18_dialog_content = "กัปตัน Axelia ทุกคน... พวกเขาหายตัวไปในความหมองมัว...",
  ui_story_1018_10180802_19_dialog_content = "คืนพวกเขา... ให้ฉัน...",
  ui_story_1018_10180802_20_dialog_content = "แกรห์!",
  ui_story_1018_10180802_21_dialog_content = "กัปตันแอ็กเซเลีย ระวังนะ!",
  ui_story_1018_10180802_22_dialog_content = "แกรห์!",
  ui_story_1018_10180802_23_dialog_content = "หยุดนะ...",
  ui_story_1018_10180802_24_dialog_content = "ช่วยด้วย! นายก Axelia!",
  ui_story_1018_10180802_25_dialog_content = "แกรห์!",
  ui_story_1018_10180802_26_dialog_content = "อ๊ะ...",
  ui_story_1018_10180802_27_dialog_content = "คุณไม่ใช่เครื่องจักรสงคราม... ขอร้องอย่าฆ่าพวกเขา...",
  ui_story_1018_10180802_28_dialog_content = "แกรห์!",
  ui_story_1018_10180802_29_dialog_content = "อาร์กค์—!",
  ui_story_1018_10180802_30_dialog_content = "...",
  ui_story_1018_10180802_31_dialog_content = "(เสียงกรีดร้องของเขา... ลม, เสียงอาวุธ... ทั้งหมดเงียบสงัดแล้ว...)",
  ui_story_1018_10180802_32_dialog_content = "(เขา... ตายแล้วเหรอ?)",
  ui_story_1018_10180802_33_dialog_content = "(หรืออาจจะ... แอ็กซีเลียตายแล้ว...)",
  ui_story_1018_10180802_34_dialog_content = "(...)",
  ui_story_1018_10180802_35_dialog_content = "กัปตันแอ็กเซเลีย ช่วยฉันด้วย!",
  ui_story_1018_10180802_36_dialog_content = "(ฉันรู้สึกหนักมาก... ขยับไม่ได้เลย...)",
  ui_story_1018_10180802_37_dialog_content = "(เร็ว... ต้องช่วยเขา!)",
  ui_story_1018_10180802_38_dialog_content = "<color=#e8d9bb>แกล๊ง!</color>",
  ui_story_1018_10180802_39_dialog_content = "(ร่างกายของเขาถูกกระแทกแรงลงพื้น...)",
  ui_story_1018_10180802_40_dialog_content = "(มันเหมือนว่าร่างกายของ Axelia ถูกกระแทกลงสู่พื้น...)",
  ui_story_1018_10180802_41_dialog_content = "<color=#e8d9bb>รัว!!!</color>",
  ui_story_1018_10180802_42_dialog_content = "(เขาฉีกอกทหารและเริ่มอาหารเลี้ยง...)",
  ui_story_1018_10180802_43_dialog_content = "(ทหารคนนั้นตกอยู่ในหมู่เลือดของตัวเอง...)",
  ui_story_1018_10180802_44_dialog_content = "(แต่ Axelia รู้สึกเหมือนว่า... มันเป็นตัวฉันเองที่ล้มอยู่ที่นั่น...)",
  ui_story_1018_10180802_45_dialog_content = "<color=#e8d9bb>แกล๊ง! แกล๊ง!</color>",
  ui_story_1018_10180802_46_dialog_content = "(ห้าครั้ง, หกครั้ง...)",
  ui_story_1018_10180802_47_dialog_content = "(Axelia ล้มหกครั้งแล้ว...)",
  ui_story_1018_10180802_48_dialog_content = "(ครั้งที่สิบ...)",
  ui_story_1018_10180802_49_dialog_content = "(ครั้งที่ยี่สิบสาม, ครั้งที่ยี่สิบสี่...)",
  ui_story_1018_10180802_50_dialog_content = "(หนึ่งร้อยและสองครั้ง...)",
  ui_story_1018_10180802_51_dialog_content = "(สองพันครั้ง...)",
  ui_story_1018_10180802_52_dialog_content = "(...)",
  ui_story_1018_10180802_53_dialog_content = "11,111 ครั้ง...",
  ui_story_1018_10180802_54_dialog_content = "(Axelia ยังคงพ่ายแพ้...)",
  ui_story_1018_10180802_55_dialog_content = "(พ่อบอกว่า Axelia เป็นเครื่องจักรสงครามที่ยอดเยี่ยม และเครื่องจักรสงครามไม่เคยยอมแพ้)",
  ui_story_1018_10180802_56_dialog_content = "(แต่ Axelia ยังคงถูกเอาชนะ...)",
  ui_story_1018_10180802_57_dialog_content = "(Axelia ไม่รู้วิธีหยุดยั้งเรื่องนี้เลย)",
  ui_story_1018_10180802_58_dialog_content = "แอ็กเซเลีย!",
  ui_story_1018_10180802_59_dialog_content = "(พ่อ? โปรดอภัยให้แอ็กซีเลียนะครับ...)",
  ui_story_1018_10180802_60_dialog_content = "จำไว้นะ Axelia คุณต้องมีชีวิตอยู่ในฐานะคน!",
  ui_story_1018_10180802_61_dialog_content = "(มีชีวิต... แต่ Axelia สามารถทำอะไรได้...?)",
  ui_story_1018_10180802_62_dialog_content = "(อาจจะให้ Axelia ทำ...)",
  ui_story_1018_10180802_63_dialog_content = "โฮก...",
  ui_story_1018_10180802_64_dialog_content = "แกรห์!",
  ui_story_1018_10180802_65_dialog_content = "ฟ้าคำรนกึกก้อง!",
  ui_story_1018_10180802_66_dialog_content = "ตื่นขึ้นเถอะ แอ็กเซเลีย! ฟังเสียงของฉัน!",
  ui_story_1018_10180802_67_dialog_content = "คุณไม่สามารถก้าวหน้าไปข้างหน้าได้อีกแล้ว วราธ!",
  ui_story_1018_10180802_68_dialog_content = "โฮก...",
  ui_story_1018_10180802_69_dialog_content = "แม้กระทั่ง Axelia ก็จะ...",
  ui_story_1018_10180802_70_dialog_content = "<color=#e8d9bb>หวัดดี—</color>",
  ui_story_1018_10180802_71_dialog_content = "เสียงนั้น...",
  ui_story_1018_10180802_72_dialog_content = "แสงแดดนี่มันจ้าจริง ๆ...",
  ui_story_1018_10180802_73_dialog_content = "ขอโทษด้วยค่ะท่านจอมทัพเลโอ ที่มาสายค่ะ!",
  ui_story_1018_10180802_74_dialog_content = "ฉัน, โจเซลีน, ในออร่าของท่านหญิงนักบุญ, จะช่วยชาวออโรเรียนกลับสู่พระคุณของพระเจ้า!",
  ui_story_1018_10180802_75_dialog_content = "อิคลิพไซท์ที่ชั่วร้ายจะไม่ทำร้ายคุณอีกต่อไป!",
  ui_story_1018_10180802_76_dialog_content = "กัปตันขอรับ! นี่คือโจเซลีน! และ... ท่านหญิงคาร์ลีนและนักบินสวรรค์ลูโมโพลิสขอรับ!",
  ui_story_1018_10180802_77_dialog_content = "เด็กผู้หญิงที่ยืนอยู่ในแสงนั่น... เป็นคนที่ฉันคิดว่าเธอเป็นหรือเปล่า...?",
  ui_story_1018_10180802_78_dialog_content = "ฉันได้ฟังแล้ว แต่ยังไม่ถึงเวลาให้พวกเขากลับมา",
  ui_story_1018_10180802_79_dialog_content = "ทุกชีวิตมีค่าความสำคัญ คุณจะได้รับการชำระความชั่วร้ายด้วยความเมตตาจากพระผู้เป็นเจ้า",
  ui_story_1018_10180802_80_dialog_content = "ถูกล้างตัวด้วยแสงศักดิ์สิทธิ์ ได้ยินคำอธิษฐาน และรับพรวิเศษจากเทพดิวินี",
  ui_story_1018_10180802_81_dialog_content = "ให้พลังไหลเวียนเพื่อรักษาบาดแผล และกำจัดความคิดชั่วร้าย",
  ui_story_1018_10180802_82_dialog_content = "ขอให้เทพแห่งแสงสว่างนิรันดร์อยู่กับออโรเรียนเสมอ",
  ui_story_1018_10180802_83_dialog_content = "กัปตัน ดูทหารสิครับ! พวกเขาเปล่งประกายแสงทองคำ!",
  ui_story_1018_10180802_84_dialog_content = "ใช่ โจเซลินสามารถพาท่านหญิงเซนต์มาด้วย...",
  ui_story_1018_10180802_85_dialog_content = "เธอกำลังรักษาทหารที่ถูกคอร์รัปต์หรือเปล่า?",
  ui_story_1018_10180802_86_dialog_content = "ใช่ คาดว่าเธอไม่เพียงแต่สามารถสลายควบคุมของพลังความมืด แต่แม้กระทั่งแค่มองเห็นเอกซ์ออร่าศักดิ์สิทธิ์ก็สามารถรักษาออโรเรียนทั่วไปได้",
  ui_story_1018_10180802_87_dialog_content = "ถูกต้อง...",
  ui_story_1018_10180802_88_dialog_content = "ฉันรู้สึกว่าแรงบางอย่างในร่างกายของฉันกำลังแผ่กระจายเพื่อนำความสบายมากขึ้น...",
  ui_story_1018_10180802_89_dialog_content = "และนอกจากนี้ ทหารที่กลายเป็นอิคลิพไซท์ก็หยุดโจมตีแล้ว...",
  ui_story_1018_10180802_90_dialog_content = "ฉันเข้าใจความเจ็บปวดของคุณ ตอนนี้คุณเพียงแค่ต้องการพักฟื้นอย่างสงบเท่านั้น",
  ui_story_1018_10180802_91_dialog_content = "ขอเทิดทูนรัตติกาลสีขาว!",
  ui_story_1018_10180802_92_dialog_content = "ขอโทษที่เรามาช้านะคะ!",
  ui_story_1018_10180802_93_dialog_content = "สวัสดี...",
  ui_story_1018_10180802_94_dialog_content = "ทุกคน นี่คือเลดี้เซนต์เซสจากโบสถ์ลูโมโพลิส",
  ui_story_1018_10180802_95_dialog_content = "โบสถ์ลูโมโพลิส? มีอะไรเกิดขึ้นที่นี่?",
  ui_story_1018_10180802_96_dialog_content = "ท่านจอมทัพวราธ ท่านหญิงเซนเทสมาช่วยรักษาทหารที่บาดเจ็บค่ะ",
  ui_story_1018_10180802_97_dialog_content = "คนที่ตามฉันมายัง Lumo Stronghold ตอนนี้มีสภาพความเสถียรแล้ว ขอบคุณเธอครับ",
  ui_story_1018_10180802_98_dialog_content = "ท่านหญิงนักบวชใช้พลังศักดิ์สิทธิ์หรือเปล่า...?",
  ui_story_1018_10180802_99_dialog_content = "ไม่ ฉันเป็นออโรเรียนไม่ต่างจากคุณเลย นายทหารใหญ่",
  ui_story_1018_10180802_100_dialog_content = "แต่ทำไมฉันถึงคิดไม่ได้ว่า...",
  ui_story_1018_10180802_101_dialog_content = "ข้าพระองค์เสียใจเมื่อได้ยินเรื่องที่เกิดขึ้นกับคุณและทหารของคุณ ดังนั้นข้าพระองค์จึงรักษาพวกเขาโดยไม่ได้รับความยินยอมจากคุณ หวังว่าคุณจะให้อภัยข้าพระองค์",
  ui_story_1018_10180802_102_dialog_content = "ไม่, ฉันต่างหากที่ควรขอบคุณคุณ",
  ui_story_1018_10180802_103_dialog_content = "มาที่นี่มีเหตุผลอะไรเหรอคะ?",
  ui_story_1018_10180802_104_dialog_content = "ฉันได้ฟังเสียงกระซิบของออโรเรียนในฝันร้ายของพวกเขา ฉันสามารถรับรู้ความเจ็บปวดและความทุกข์ยาก",
