  ui_story_1019_10190101_45_dialog_content = "...",
  ui_story_1019_10190101_46_dialog_content = "ตื่นแล้วหรือยังครับ?",
  ui_story_1019_10190101_47_dialog_content = "ขอเทิดทูนรัตติกาลสีขาว, เราได้มาถึงอย่างปลอดภัย",
  ui_story_1019_10190101_48_dialog_content = "ลีโอ... โจเซลีน? เราอยู่ที่ไหน...?",
  ui_story_1019_10190101_49_dialog_content = "กลับมาอยู่ในอีราเวลแล้ว",
  ui_story_1019_10190101_50_dialog_content = "เรือเหาะสั่นไหวอย่างรุนแรงจนทหารแทบจะยืนไม่อยู่ แต่คุณกลับหลับสนิท...",
  ui_story_1019_10190101_51_dialog_content = "อีราเวล...",
  ui_story_1019_10190101_52_dialog_content = "ถูก... ใช่, นี่คืออีราเวล...",
  ui_story_1019_10190101_53_dialog_content = "ตามการรณรงค์ใน Twilight และบนเส้นป้องกันของ Illumina, เราได้ขึ้นเรือบิน Lumopolis กลับไปยัง Eraveil...",
