  ui_story_1019_10190201_43_dialog_content = "กลับบ้าน.",
  ui_story_1019_10190201_44_dialog_content = "บ้านเหรอ? ฉันอยู่ที่ไหนเนี่ย?",
  ui_story_1019_10190201_45_dialog_content = "กลับบ้าน.",
  ui_story_1019_10190201_46_dialog_content = "คุณคือใคร? ไวซ์อยู่ที่ไหน?",
