  ui_story_1019_10190301_6_dialog_content = "เรียกรวมพล!",
  ui_story_1019_10190301_7_dialog_content = "ได้เลยค่ะ",
  ui_story_1019_10190301_8_dialog_content = "อีกครั้ง ที่นี่ไม่ปลอดภัยเนื่องจากช่องโหว่ในการป้องกัน กรุณาออกจากที่นี่เดี๋ยวนี้",
  ui_story_1019_10190301_9_dialog_content = "จุดอ่อน...",
  ui_story_1019_10190301_10_dialog_content = "ดูเหมือนว่าความปลอดภัยยังคงเป็นปัญหา แม้ว่าจะมีทหารเยอะแยะเหล่านี้",
  ui_story_1019_10190301_11_dialog_content = "ฮ่า! รับสิ่งนี้ไปเถอะ, PlayerName!",
  ui_story_1019_10190301_12_dialog_content = "เดี๋ยวนะ... คุณเป็นใครอีกครั้ง?",
  ui_story_1019_10190301_13_dialog_content = "มาสิ นี่ลืมฉันเหรอ?!",
  ui_story_1019_10190301_14_dialog_content = "โอ้ ฉันจำได้แล้ว คุณคือ...",
  ui_story_1019_10190301_15_option_content = "กรีนนี่",
  ui_story_1019_10190301_16_dialog_content = "ไม่, ฉันหมายถึงฌอน!",
  ui_story_1019_10190301_17_dialog_content = "(ไม่อยากเชื่อเลยว่าฉันได้ปล่อยความประทับใจครั้งแรกของฉันต่อเขาไป...)",
  ui_story_1019_10190301_18_dialog_content = "ฮ่า, ดีใจนะ, มีคนบางคนเรียกฉันแบบนั้น!",
  ui_story_1019_10190301_19_option_content = "อีกา",
  ui_story_1019_10190301_20_dialog_content = "ไม่สิ เดี๋ยวนะ ไม่ใช่อีกา... มันคือฌอน!",
  ui_story_1019_10190301_21_dialog_content = "เอาจริง ๆ แล้วเทียบกับอีกา ฉันคงไม่น่าจะเด่นเท่านั้นนะ",
  ui_story_1019_10190301_22_option_content = "ฌอน",
  ui_story_1019_10190301_23_dialog_content = "นั่นเอง คุณคือฌอน...",
  ui_story_1019_10190301_24_dialog_content = "ขอโทษนะ! คุณดู...ต่างไป จากที่ฉันจำได้",
  ui_story_1019_10190301_25_dialog_content = "เอาล่ะ แน่นอน ฉันได้ฝึกฝนทักษะการชกมวยของฉันและกำลังแข็งแกร่งขึ้นทุกวัน!",
