  ui_story_1019_10190901_9_dialog_content = "ทำไมพูดอย่างนั้นล่ะ",
  ui_story_1019_10190901_10_dialog_content = "คุณจะรู้ในไม่ช้า ตอนนี้ เราเริ่มกันเถอะ",
  ui_story_1019_10190901_11_dialog_content = "...",
  ui_story_1019_10190901_12_option_content = "ลิงค์โทรจิต",
  ui_story_1019_10190901_13_dialog_content = "นี่คือนอร์ธแลนด์...หรือเปล่า?",
  ui_story_1019_10190901_14_dialog_content = "เสาน้ำแข็งจำนวนมาก ชี้ไปที่ท้องฟ้าเหมือนคมดาบ",
  ui_story_1019_10190901_15_dialog_content = "ไม่, ความมืดมิดนี้ใกล้เคียงกับเขตแดนมืดมากขึ้น...",
  ui_story_1019_10190901_16_dialog_content = "ฉันได้สำรวจซากปรักหักพังออโรรามาก่อน พวกเขามีหินสีดำบางอันที่ส่งออกความรู้สึกหนาวเหมือนกัน",
  ui_story_1019_10190901_17_dialog_content = "แต่หินพวกนั้นถูกวางแบนบนพื้นดินที่แข็งแรง ในขณะที่เสาหินพวกนี้ลอยอยู่กลางอากาศ",
  ui_story_1019_10190901_18_dialog_content = "บางตัวยังส่องประกายและยืดตัวขึ้นสูง...",
  ui_story_1019_10190901_19_dialog_content = "นี่เป็นส่วนหนึ่งของความทรงจำของ Ulysses หรือไม่? เขามาที่นี่เพราะอะไร?",
  ui_story_1019_10190901_20_dialog_content = "แล้วทำไมความทรงจำแบบนั้นถึงอยู่ในส consciousness ของเขาได้ล่ะ?",
  ui_story_1019_10190901_21_dialog_content = "นี่คือสถานที่ที่ถูกทิ้งร้างโดยไม่มีสัญญาณของสิ่งมีชีวิต...",
  ui_story_1019_10190901_22_dialog_content = "<color=#e8d9bb>กริ๊ง กริ๊ง!</color>",
  ui_story_1019_10190901_23_dialog_content = "มีอะไรอีก",
  ui_story_1019_10190901_24_dialog_content = "เสาหินกำลังเปลี่ยนแปลงเหมือนถูกดึงด้วยแรงบางอย่างเข้าสู่กลุ่มที่หันไปทางท้องฟ้า",
  ui_story_1019_10190901_25_dialog_content = "พวกเขากำลังรวมตัวเข้าด้วยกันเป็นอะไรหรือ?",
  ui_story_1019_10190901_26_dialog_content = "สถานที่นี้คืออะไรกันแน่?",
  ui_story_1019_10190901_27_dialog_content = "<color=#e8d9bb>ชน...</color>",
  ui_story_1019_10190901_28_dialog_content = "*แฮ่ก แฮ่ก*",
