  ui_story_1019_10190901_31_option_content = "ที่นั้นอยู่ที่ไหนครับ?",
  ui_story_1019_10190901_32_dialog_content = "เรา...",
  ui_story_1019_10190901_33_option_content = "ทำไมคุณถึงแสดงให้ฉันดูเนี่ย?",
  ui_story_1019_10190901_34_dialog_content = "เพราะว่า...",
  ui_story_1019_10190901_35_dialog_content = "นั่นคือสุดขอบโลก.",
  ui_story_1019_10190901_36_dialog_content = "ที่อิคลิพไซท์ซ่อนตัวและพยายามปลุกปิศาจ...",
