  ui_story_1020_10200501_47_dialog_content = "(\"X\"?)",
  ui_story_1020_10200501_48_dialog_content = "(ตัวอักษรที่เรืองแสงนั้นเป็น \"X\" หรือไม่?)",
  ui_story_1020_10200501_49_dialog_content = "(โอย... คงมีเวลาผ่านไปมากแล้วนะ...)",
  ui_story_1020_10200501_50_dialog_content = "(หัวฉันดูไม่ปวดเท่าที่เคยแล้ว!)",
  ui_story_1020_10200501_51_dialog_content = "(แต่ทำไมมี \"X\" นี้เหรอ?)",
  ui_story_1020_10200501_52_dialog_content = "(เอ้อออ... มันเร็วขึ้นอีกแล้ว...)",
  ui_story_1020_10200502_1_dialog_content = "บู! บู! บู!",
  ui_story_1020_10200502_2_dialog_content = "สองนาทีเต็มๆ",
  ui_story_1020_10200502_3_dialog_content = "ยอดมาก!",
  ui_story_1020_10200502_4_dialog_content = "บู! บู! บู!",
  ui_story_1020_10200502_5_dialog_content = "โอเค โอเค... ช้า ๆ หน่อยสิ!",
  ui_story_1020_10200502_6_dialog_content = "เอาล่ะ มาใช้คอมพิวเตอร์เหล่านี้วิเคราะห์ข้อมูลที่เราเพิ่งได้รับกัน เรามั่นใจว่าคราวนี้มันจะทำงานได้แน่นอน",
