  ui_story_1020_10200502_8_dialog_content = "อ๊าก—",
  ui_story_1020_10200502_9_dialog_content = "เป็นอะไรรึเปล่า PlayerName?",
  ui_story_1020_10200502_10_dialog_content = "ว้าว, คุณมีความดันโลหิตสูงจริงๆ! และออกซิเจนในชีพจรของคุณ... คุณมองเราเห็นชัดไหม?",
  ui_story_1020_10200502_11_dialog_content = "ย-ใช่ ฉันเห็นคุณ...",
  ui_story_1020_10200502_12_dialog_content = "นั่งลงและอย่าขยับ ตามนิ้วของฉันด้วยตาของคุณ",
