  ui_story_1020_10200602_71_dialog_content = "\"ยูลิสซิส\"",
  ui_story_1020_10200602_72_dialog_content = "...",
  ui_story_1020_10200602_73_dialog_content = "บูล! เปลี่ยนเส้นทางการเข้าถึงและพยายามเรียกคืนโมดูล!",
  ui_story_1020_10200602_74_dialog_content = "บู้!",
  ui_story_1020_10200602_75_dialog_content = "<color=#e8d9bb>ฟิ้ว—</color>",
  ui_story_1020_10200602_76_dialog_content = "...",
  ui_story_1020_10200602_77_dialog_content = "มันผ่านไป... เวลานาน...",
  ui_story_1020_10200602_78_dialog_content = "ใช่แล้ว... ใช่แล้ว... ฮะฮะ...",
  ui_story_1020_10200602_79_dialog_content = "เธอก็มาสินะ...",
  ui_story_1020_10200602_80_dialog_content = "ใครน่ะ?",
  ui_story_1020_10200602_81_dialog_content = "วิศวกร...",
  ui_story_1020_10200602_82_dialog_content = "ตรงไหนเหรอ?",
  ui_story_1020_10200602_83_dialog_content = "ให้ฉันยาเม็ดสุดท้าย, เอสเซน",
  ui_story_1020_10200602_84_dialog_content = "คุณคารอน...",
  ui_story_1020_10200602_85_dialog_content = "เอามาเดี๋ยวนี้!",
  ui_story_1020_10200602_86_dialog_content = "<color=#e8d9bb>ห้องขังอิลลูมินา</color>",
  ui_story_1020_10200602_87_dialog_content = "(ภาษาอิคลิพส์) ค-คุณ... ผู้ปกครองสูงสุด!",
  ui_story_1020_10200602_88_dialog_content = "(Eclipsian) คนรับใช้ที่ภักดีของคุณ ฟิเจอรัลด์ ได้หักเหลี่ยมอยู่ที่นี่ตลอดเวลานี้ รอคอยการมาถึงของคุณ",
  ui_story_1020_10200602_89_dialog_content = "...",
  ui_story_1020_10200602_90_dialog_content = "<color=#e8d9bb>ปึก—</color>",
  ui_story_1020_10200602_91_dialog_content = "(ภาษาอิคลิพส์) ...",
  ui_story_1020_10200602_92_dialog_content = "(Eclipsian) ผม-ผมสั่นสะท้านในหน้าท่าน! ผมจะไม่กล้าที่จะต่อต้านความปรารถนาของท่านเลย!",
  ui_story_1020_10200602_93_dialog_content = "(Eclipsian) อนุญาตให้ฉันได้ชดเชยตัวเอง...",
  ui_story_1020_10200602_94_dialog_content = "(Eclipsian) ภารกิจที่ฉันเคยล้มเหลวจะต้องสำเร็จ แม้ว่าจะต้องเสียชีวิตของฉันเองก็ตาม",
  ui_story_1020_10200701_1_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10200701_2_dialog_content = "เขาได้เอาแกนกลางของ Guardian One ไปแล้ว Ulysses แล้วเขาต้องการอะไรเพิ่มเติมอีกหรือ?",
  ui_story_1020_10200701_3_dialog_content = "คุณไม่รู้สึกกลัวเลยหรือไง ไอรอน มาสก์ ที่เมืองใต้ดินกำลังจะพังทลายลงมา",
  ui_story_1020_10200701_4_dialog_content = "คุณวางแผนทั้งหมดนี้... คุณส่งชีวิตและเลือดของ Illumina ให้กับ Eclipse แค่เพื่อที่จะได้ทรัพยากรวิจัยเพิ่มเติมและบรรลุความฝันของคุณหรือ?",
  ui_story_1020_10200701_5_dialog_content = "ฉันเคยเชื่อว่าหากไม่มีวิศวกร อิลลูมินาคงไม่มีที่ตรงนี้ในวันนี้",
  ui_story_1020_10200701_6_dialog_content = "แล้วฉันก็ตระหนักว่า หัวใจหลักของ Guardian One ไม่เคยเป็นเลือดชีวิตของ Illumina",
  ui_story_1020_10200701_7_dialog_content = "ฉันทำแล้ว!",
  ui_story_1020_10200701_8_dialog_content = "ระบบป้องกันของ Gannon จะกลายเป็นกรวยง่าย ๆ เพียงเพราะแกนกลางหายไปได้ยังไงล่ะ?",
  ui_story_1020_10200701_9_dialog_content = "ฉันจะบอกคุณเกี่ยวกับแผนของวิศวกร...",
  ui_story_1020_10200701_10_dialog_content = "เขาต้องการที่จะรวมกลุ่มและเผาผลาญ ท้าทายความไม่สำคัญของออโรเรียนด้วยความยิ่งใหญ่ของเขา...",
  ui_story_1020_10200701_11_dialog_content = "แต่ฉันไม่ต้องการที่จะรอความตายของฉันในเมืองใต้ดินที่มืดมิดนี้เหมือนคุณ! ฉันจะท้าทายเขา!",
  ui_story_1020_10200701_12_dialog_content = "วุ่นวาย... นี่มันวุ่นวาย!",
  ui_story_1020_10200701_13_dialog_content = "คุณรู้ไหมว่าเขาวางแผนจะทำให้สำเร็จได้ยังไง?",
  ui_story_1020_10200701_14_dialog_content = "เขาสร้างทุกอย่างนี้ขึ้น แล้วเข้าสู่ความเงียบ และมอบหมายงานในการกู้คืนแกนหลักและการสร้างอิคลิพไซท์ให้กับเจตภูตที่โง่เขลา",
  ui_story_1020_10200701_15_dialog_content = "หลับสงบมาหลายร้อยปีแล้ว ตอนนี้เขาตื่นขึ้นมาแล้ว",
  ui_story_1020_10200701_16_dialog_content = "แต่โลกก็เปลี่ยนไปแล้ว เขาไม่ใช่วิศวกรที่ฉันเคยศึกษาจากไฟล์อีกต่อไป",
  ui_story_1020_10200701_17_dialog_content = "อะไรก็ตามที่เขาทำได้ ฉันน่าจะทำได้เหมือนกัน",
  ui_story_1020_10200701_18_dialog_content = "หุบปากที่เหม็นๆ นะ!",
  ui_story_1020_10200701_19_dialog_content = "ใครก็ตามในที่นี่สามารถฆ่าคุณด้วยการโบกมือได้ คุณควร—",
  ui_story_1020_10200701_20_dialog_content = "คุณสามารถทำอะไรได้บ้าง?",
  ui_story_1020_10200701_21_dialog_content = "...",
  ui_story_1020_10200701_22_dialog_content = "ฮิฮิ... ฉันมีทุกอย่างที่ต้องการพร้อมในคลังของฉันแล้ว",
  ui_story_1020_10200701_23_dialog_content = "หยุดอยู่ตรงนั้น!",
  ui_story_1020_10200701_24_dialog_content = "...เธอกำลังพยายามหยุดฉันหรือ?",
  ui_story_1020_10200701_25_dialog_content = "อยู่ตรงนั้นแหละ ไม่ต้องไปไหนทั้งนั้น",
  ui_story_1020_10200701_26_dialog_content = "... ไม่มีใครในคุณที่เชื่อฉันเลย แต่ตอนนี้ฉันเป็นคนเดียวที่สามารถ—",
  ui_story_1020_10200701_27_dialog_content = "เดินอีกก้าวหนึ่งเถอะ!",
  ui_story_1020_10200701_28_dialog_content = "วางอาวุธซะ",
  ui_story_1020_10200701_29_dialog_content = "...",
  ui_story_1020_10200701_30_dialog_content = "เวลาของเรากำลังจะหมดไป หน้ากากเหล็ก แต่ Illumina ยังมีทางที่ยาวไกลอยู่ และ Aurorians ก็เช่นกัน",
  ui_story_1020_10200701_31_dialog_content = "ฉันรู้ว่าวันนี้จะมาถึง แต่ฉันจะไม่ยอมแพ้แม้ว่าทุกคนในคุณจะไม่เห็นด้วย!",
  ui_story_1020_10200701_32_dialog_content = "ฉันจะต่อสู้เอาทางของฉันคืนมา",
  ui_story_1020_10200701_33_dialog_content = "ถ้าคุณช่วยไม่ได้ ฉันจะทำมันเอง...",
  ui_story_1020_10200701_34_dialog_content = "คุณมีความกล้าที่จะมาดูมันไหม?",
  ui_story_1020_10200701_35_dialog_content = "...",
  ui_story_1020_10200701_36_dialog_content = "<color=#e8d9bb>บี๊บ—</color>",
  ui_story_1020_10200701_37_dialog_content = "ท่านจอมทัพ?",
  ui_story_1020_10200701_38_dialog_content = "เธอบอกให้เรานำ Ulysses มาที่นี่",
  ui_story_1020_10200701_39_dialog_content = "...",
  ui_story_1020_10200701_40_dialog_content = "เกมหมากรุกจะไม่มีอะไรเลยหากไม่มีตัวหมากรุก โบลิซาริอา คุณจะสามารถที่จะเป็นคนที่ทำการเดินได้อย่างไรในกรณีนั้นครับ?",
  ui_story_1020_10200701_41_dialog_content = "ฉันเชื่อว่าไม่ว่าจะเกิดอะไรขึ้น ไรน์ฮาร์ตจะรักษาแกนนอนให้คงอยู่ แต่คุณสามารถทำเช่นเดียวกันได้หรือไม่?",
  ui_story_1020_10200701_42_dialog_content = "...",
  ui_story_1020_10200701_43_dialog_content = "Davidar, ติดต่อ Barrett",
  ui_story_1020_10200701_44_dialog_content = "ดร.บาร์เร็ตต์รอคุณมานานแล้ว",
  ui_story_1020_10200701_45_dialog_content = "การตัดสินใจคืออะไร?",
  ui_story_1020_10200701_46_dialog_content = "เริ่มต้น<color=#FFB400>โปรโตคอลฉุกเฉิน</color>",
  ui_story_1020_10200701_47_dialog_content = "แกะอุปกรณ์ต้นฉบับ แก้ไขเส้นทางที่ตั้งไว้ล่วงหน้า เปิดท่อการขนส่ง และขนส่งพลเรือนไปยังเมืองใต้ดินสำรอง",
  ui_story_1020_10200701_48_dialog_content = "ยานพาหนะและทางขนส่งทำงานได้ปกติ สามารถขนส่งพลเรือนได้",
  ui_story_1020_10200701_49_dialog_content = "แต่ข้าขอร้องให้มีกองทหารเพียงพอเพื่อรับรองการขนส่งที่ปลอดภัยในท่อจากคณะกรรมการ",
  ui_story_1020_10200701_50_dialog_content = "เพียงทำมัน คณะกรรมการจะเปิดทางให้คุณ",
  ui_story_1020_10200701_51_dialog_content = "นั่นแหละที่ฉันชอบ",
  ui_story_1020_10200701_52_dialog_content = "คุณสองคนพายูลิสซิสไปที่โกดังนะ",
  ui_story_1020_10200701_53_dialog_content = "เดี๋ยวนะ ยานพาหนะและท่อขนส่ง... หมายถึงอะไรกันน่ะ?",
  ui_story_1020_10200701_54_dialog_content = "เครื่องบินที่พัฒนาโดยอิลลูมินาและเครือข่ายรางใต้ดินที่ออกแบบมาเฉพาะสำหรับพวกเขา",
  ui_story_1020_10200701_55_dialog_content = "เครื่องบิน?",
  ui_story_1020_10200701_56_dialog_content = "คุณคิดว่าอิลลูมินามีแค่รถไฟที่วิ่งบนพื้นดิน, พาหนะ, และอุโมงค์เท่านั้นหรือ?",
  ui_story_1020_10200701_57_dialog_content = "แล้วอุปกรณ์ต้นฉบับและเส้นทางที่ตั้งไว้ล่วงหน้านั้นหมายถึงอะไรล่ะครับ?",
  ui_story_1020_10200701_58_dialog_content = "ฉันไม่มีปัญหาที่จะบอกคุณ—เครื่องบินเหล่านี้ถูกสร้างขึ้นเพื่อเมืองลอยนี้ และเส้นทางที่ตั้งไว้จะไปตรงไปยังลูโมโพลิสจากที่นี่",
  ui_story_1020_10200701_59_dialog_content = "เครื่องบินเหล่านี้ถูกติดอาวุธเพื่อโจมตีลูโมโปลิสหรือ?",
  ui_story_1020_10200701_60_dialog_content = "คุณต้องการอาวุธที่แตกต่างกันเพื่อต่อสู้กับศัตรูที่แตกต่างกัน และเมื่อคุณตัดสินใจจะลุยที่ผิวน้ำ คุณต้องทำอะไรก็ตามที่จำเป็น",
  ui_story_1020_10200701_61_dialog_content = "...",
  ui_story_1020_10200701_62_dialog_content = "ฉันไม่ได้คาดหวังว่าเวลานี้จะเป็นเวลาที่จะเริ่มต้นโปรโตคอล",
  ui_story_1020_10200701_63_dialog_content = "แม้ว่าคุณจะไม่พูดออกมา แต่เราก็มีความสนใจเดียวกันอย่างน้อยในเรื่องนี้",
  ui_story_1020_10200701_64_dialog_content = "พายูลิสซิสไปที่คลังสินค้าของเขา ตอนนี้เขาเป็นตัวประกันของคุณแล้ว",
  ui_story_1020_10200701_65_dialog_content = "...",
  ui_story_1020_10200701_66_dialog_content = "ฮิฮิ. ฉันเห็นว่านายไม่ได้เป็นผู้นำที่เซ็นิคอลเหมือนที่เคยอีกต่อไปแล้วนะ.",
  ui_story_1020_10200701_67_dialog_content = "เราจะได้เจอกันอีกใช่ไหม?",
  ui_story_1020_10200701_68_dialog_content = "มีเวลาสำหรับการล้อเล่น",
  ui_story_1020_10200701_69_dialog_content = "แต่คุณต้องจริงจังเมื่อสถานการณ์เป็นไปไม่ดั่งใจ",
  ui_story_1020_10200701_70_dialog_content = "ถ้าคุณจัดการสิ่งนั้นได้ ฉันคิดว่าเราไม่จำเป็นต้องเจอกันอีกนะ",
  ui_story_1020_10200701_71_dialog_content = "ไม่มีอะไรเกิดขึ้นในลูโมโพลิสแม้หลังจากที่ทางขนส่งถูกเปิดขึ้น",
  ui_story_1020_10200701_72_dialog_content = "หลังจากที่เราปกปิดตัวเองมาเป็นเวลาหลายปี ถ้าไม่ยึดโอกาสนี้ไปโจมตีเมืองลอยนั่นจะเป็นเรื่องน่าเสียดาย",
  ui_story_1020_10200701_73_dialog_content = "กลับไปทำหน้าที่ของคุณ เรายังมีงานที่รอคอยให้ทำอีกมาก",
  ui_story_1020_10200701_74_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10200701_75_dialog_content = "แอ็กซีเลีย, อิงเกล, เราควรทำอะไรตอนนี้?",
  ui_story_1020_10200701_76_dialog_content = "สิ่งที่เราได้ทำมาตลอดเวลา ท่านจอมทัพและคนอื่น ๆ ไปที่คลังสินค้า ดังนั้นเราควรปกป้องพวกเขา",
  ui_story_1020_10200701_77_dialog_content = "ในฐานะเครื่องจักรสงคราม คุณรู้เสมอว่าควรทำอะไรในทุกๆ เวลาหรือไม่?",
  ui_story_1020_10200701_78_dialog_content = "มันเป็นเรื่องชัดเจนสำหรับฉันตั้งแต่ฉันโตขึ้นพอที่จะคิดได้",
  ui_story_1020_10200701_79_dialog_content = "ฉันเพิ่งรู้เรื่องนั้นเมื่อไม่นานนี้ และเธอก็จะรู้เรื่องนั้นเอง ฌอน",
  ui_story_1020_10200701_80_dialog_content = "ง่ายสำหรับคุณที่จะพูด คุณสองคนคือ—",
  ui_story_1020_10200701_81_dialog_content = "โอ๊ย!",
  ui_story_1020_10200701_82_dialog_content = "Yingel! เธอหยิกฉันทำไม? ฉันเลือดออกนี่...",
  ui_story_1020_10200701_83_dialog_content = "เครื่องจักรสงครามไม่ใช่ออโรเรียนที่มีเนื้อและเลือดเหมือนกันหรือ?",
  ui_story_1020_10200701_84_dialog_content = "ลืมเรื่องที่เกิดขึ้นในการประชุม ไม่ว่าจะเป็นอย่างไร ท่านจอมทัพจะไม่เล็กน้อยต่อความมีอยู่หรือจุดประสงค์ของคุณเลย",
  ui_story_1020_10200701_85_dialog_content = "เธอและจอมทัพวราธทั้งคู่เป็นเหยื่อของโครงการนี้ แต่พวกเขายังคงปฏิบัติหน้าที่ของตนเอง",
  ui_story_1020_10200701_86_dialog_content = "อาจจะแปลกหน่อยที่จะพูดแบบนี้ แต่ด้วยจอมพลเหล่านั้น ฉันไม่รู้สึกกลัวเลย",
  ui_story_1020_10200701_87_dialog_content = "...",
  ui_story_1020_10200701_88_dialog_content = "ฉันก็ไม่",
  ui_story_1020_10200701_89_dialog_content = "เธอ...",
  ui_story_1020_10200701_90_dialog_content = "เอาล่ะ ไปเถอะ! วิ่งเร็วขึ้นซักหน่อย ฌอน!",
  ui_story_1020_10200701_91_dialog_content = "... ตกลง!",
  ui_story_1020_10200701_92_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10200801_1_dialog_content = "การสั่น... มันหยุดแล้ว.",
  ui_story_1020_10200801_2_dialog_content = "เราสร้างแกนใหม่สำเร็จแล้วใช่มั้ย?",
  ui_story_1020_10200801_3_dialog_content = "ไม่... ความเร็วในการประมวลผลช้ากว่าที่เราคาดไว้ และใช้เวลานานเกินไปในการทำงานมาถึงจุดนี้",
  ui_story_1020_10200801_4_dialog_content = "แต่ขอเวลาอีกหน่อยเถอะ ฉันรู้ว่าฉันทำได้!",
  ui_story_1020_10200801_5_dialog_content = "บู้!",
  ui_story_1020_10200801_6_dialog_content = "หยุดเสียเวลา...",
  ui_story_1020_10200801_7_dialog_content = "ยืนนิ่ง ๆ นะยูลิสซิส!",
  ui_story_1020_10200801_8_dialog_content = "คุณอยู่ที่นี่.",
  ui_story_1020_10200801_9_dialog_content = "นี่เป็นความคิดของเบลิซาเรียด้วย เธอสั่งให้คนในเมืองแกนน่อนย้ายที่อยู่",
  ui_story_1020_10200801_10_dialog_content = "ฉันไม่สามารถเชื่อได้... ดร. อัลกอล, คุณวางแผนจะจัดการกับยูลิสซิสอย่างไร?",
  ui_story_1020_10200801_11_dialog_content = "บอกฉันสิ ยูลิซิส นายสร้างอิคลิพไซท์ทั้งหมดนี้เป็นส่วนหนึ่งของการตกลงกับวิศวกรหรือไม่?",
  ui_story_1020_10200801_12_dialog_content = "น่าเหลือเชื่อจริง ๆ แต่ดูเหมือนว่าคุณจะได้เรียนรู้บางอย่างในหลายปีที่ผ่านมาเพื่อเข้าสู่ระบบและรักษาความสงบของ Gannon",
  ui_story_1020_10200801_13_dialog_content = "อย่างไรก็ตามคุณได้คิดอย่างฉลาดเกินไปเมื่อคุณพยายามเข้าถึงข้อมูลการป้องกันของ Guardian และป้องกันการโจมตีของเขาในเวลาเดียวกัน",
  ui_story_1020_10200801_14_dialog_content = "คุณได้อะไร?",
  ui_story_1020_10200801_15_dialog_content = "การละเมิดใน Illumina ไม่สามารถแก้ไขได้ทีละครั้ง มันง่ายที่จะทำลายระบบป้องกัน",
  ui_story_1020_10200801_16_dialog_content = "แต่ฉันสามารถบอกให้เขาหยุดได้เลย",
  ui_story_1020_10200801_17_dialog_content = "แสดงให้ฉันเห็นวิธีทำนะ",
  ui_story_1020_10200801_18_dialog_content = "ฉันทำไม่ได้ ฉันบอกว่าเคเลสไทต์สามารถทำได้ แต่ไม่มีใครเชื่อฉันเลย",
  ui_story_1020_10200801_19_dialog_content = "หืม?",
  ui_story_1020_10200801_20_dialog_content = "อย่าเอาเขามาเกี่ยวข้องในนี้ แค่บอกเราวิธีหยุดวิศวกรเท่านั้น",
  ui_story_1020_10200801_21_dialog_content = "หยุด? ฉันไม่ต้องการหยุดเขา ฉันมาที่นี่เพียงเพื่อดูว่าคุณทำลายลูกของฉันหรือไม่",
  ui_story_1020_10200801_22_dialog_content = "คุณกล้ากลับคำหรือ!",
  ui_story_1020_10200801_23_dialog_content = "ทั้งหมดนี้ไม่เกี่ยวข้องกับพวกคุณเลยในตอนแรก",
  ui_story_1020_10200801_24_dialog_content = "<color=#e8d9bb>บัซ—บัซ—</color>",
  ui_story_1020_10200801_25_dialog_content = "ไม่นะ อีกแล้วเหรอเนี่ย...",
  ui_story_1020_10200801_26_dialog_content = "... บู, บู...",
  ui_story_1020_10200801_27_dialog_content = "\"ของขวัญ\"?",
  ui_story_1020_10200801_28_dialog_content = "... หมายความว่าอย่างไร?",
  ui_story_1020_10200801_29_dialog_content = "ฉันจะไม่โทษคุณเรื่องการทดลองที่ไม่สมบูรณ์ที่คุณทำลายลง",
  ui_story_1020_10200801_30_dialog_content = "แต่ฉันได้เตรียมสิ่งพิเศษเพิ่มเติมให้เขา",
  ui_story_1020_10200801_31_dialog_content = "ขอดูหน่อย, ควรจะอยู่แถวนี้...",
  ui_story_1020_10200801_32_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10200801_33_dialog_content = "อ๊าก!",
  ui_story_1020_10200801_34_dialog_content = "จับฉันไว้!",
  ui_story_1020_10200801_35_dialog_content = "ยูลิสซิส คุณทำอะไรไปแล้ว?",
  ui_story_1020_10200801_36_dialog_content = "นี่แผ่นดินไหวใหญ่กว่าครั้งที่แล้วนะ!",
  ui_story_1020_10200801_37_dialog_content = "มันไม่ได้แค่สั่น! มันกำลังขยับ!",
  ui_story_1020_10200801_38_dialog_content = "อย่าเสียหลัก—",
  ui_story_1020_10200801_39_dialog_content = "ฮ่าฮ่าฮ่าฮ่า! จงประจักษ์!",
  ui_story_1020_10200801_40_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10200801_41_dialog_content = "พวก<color=#FFB400>ทหารเหนือมนุษย์</color> ผสมผสานระหว่างออโรเรียนและอิคลิพไซท์ แต่ละคนสามารถต่อสู้กับศัตรูได้หนึ่งร้อยคนพร้อมกัน...",
  ui_story_1020_10200801_42_dialog_content = "พวกเขาทำได้เกินกว่าสิ่งที่คุณทำไปนานแล้ว!",
  ui_story_1020_10200801_43_dialog_content = "ทั้งหมดใต้ดินนั้นถูกท่วมน้ำ...",
  ui_story_1020_10200801_44_dialog_content = "มันมีอยู่เท่าไหร่?",
  ui_story_1020_10200801_45_dialog_content = "... พวกเขาอยู่ใต้พื้นที่เรายืนอยู่! ไม่แปลกที่เราไม่สามารถหาพวกเขาได้!",
  ui_story_1020_10200801_46_dialog_content = "ตามคำประเมินของฉันนะ... ร้อยกว่าแน่ ไม่, มากกว่านั้น.",
  ui_story_1020_10200801_47_dialog_content = "พวกมันมีสายไฟเดินออกมาจากทุกๆ รูขุมขน เหมือนว่าพวกมันกำลังได้รับพลังงาน...",
  ui_story_1020_10200801_48_dialog_content = "ยูลิสซิส!",
  ui_story_1020_10200801_49_dialog_content = "<color=#e8d9bb>ปัง—ปัง—ปัง—</color>",
  ui_story_1020_10200801_50_dialog_content = "นี่ไม่ดี... ทหารเหล่าซูเปอร์กำลังเริ่มเคลื่อนไหว!",
  ui_story_1020_10200801_51_dialog_content = "<color=#e8d9bb>ปึก—ปึก—</color>",
  ui_story_1020_10200801_52_dialog_content = "ไปตรวจสอบสายไฟในโกดัง... มันพ่นประกายไฟออกมา!",
  ui_story_1020_10200801_53_dialog_content = "สายไฟที่ยึดติดกับสิ่งรอบข้างได้อยู่ใต้โกดังมาตลอดเวลา!",
  ui_story_1020_10200801_54_dialog_content = "บู! บู! บู!",
  ui_story_1020_10200801_55_dialog_content = "เราเข้าใจแล้วว่าเขาควบคุมทหารพลังเหนือมนุษย์อย่างไร ด้วยสิ่งเหล่านี้ เขาสามารถสั่งการผ่านคอมพิวเตอร์...",
  ui_story_1020_10200801_56_dialog_content = "... เข้าใจแล้ว! บูล!",
  ui_story_1020_10200801_57_dialog_content = "บู้!",
  ui_story_1020_10200801_58_dialog_content = "เป็นไง ชอบมั้ย?",
  ui_story_1020_10200801_59_dialog_content = "Eclipsites ที่บุกเข้ามาใน Astra สิบหรือยี่สิบปีที่แล้วไม่สามารถหวังที่จะเทียบเท่ากับพวกเขาได้!",
  ui_story_1020_10200801_60_dialog_content = "ว่าไง",
  ui_story_1020_10200801_61_dialog_content = "ฮ่าฮ่าฮ่า!",
  ui_story_1020_10200801_62_dialog_content = "<color=#e8d9bb>บัซ—บัซ—</color>",
  ui_story_1020_10200801_63_dialog_content = "(วิศวกรสามารถได้ยินเสียงของยูลิสซิสได้อย่างไรนะ?)",
  ui_story_1020_10200801_64_dialog_content = "(มันเป็นต้นแบบหรือไม่? หรือพวกเขามีวิธีการสื่อสารอื่นๆหรือไม่?)",
  ui_story_1020_10200801_65_dialog_content = "... บู, บู...",
  ui_story_1020_10200801_66_dialog_content = "\"มันไม่ใช่\"",
  ui_story_1020_10200801_67_dialog_content = "... บู, บู...",
  ui_story_1020_10200801_68_dialog_content = "\"ควรกล่าวถึง\"",
  ui_story_1020_10200801_X68_dialog_content = "(วิศวกรสามารถได้ยินเสียงของยูลิสซิสได้อย่างไรนะ?)",
  ui_story_1020_10200801_X69_dialog_content = "(มันเป็นต้นแบบหรือไม่? หรือพวกเขามีวิธีการสื่อสารอื่นๆหรือไม่?)",
  ui_story_1020_10200801_69_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10200801_70_dialog_content = "ทหารเหล่าซูเปอร์กำลังยืนขึ้น!",
  ui_story_1020_10200801_X70_dialog_content = "คุณชอบมันแบบนั้นรึเปล่า... ฮ่าฮ่า...",
  ui_story_1020_10200801_71_dialog_content = "ฮิอิโระ, จับอูลิสซีส์! ทุกคนอื่น ถอย!",
  ui_story_1020_10200801_72_dialog_content = "รับทราบ!",
  ui_story_1020_10200801_73_dialog_content = "...",
  ui_story_1020_10200801_74_dialog_content = "ดร.อัลกอล!",
  ui_story_1020_10200801_75_dialog_content = "... อิลลูมินาจะจบสิ้นถ้าเราปล่อยเครื่องนี้ไว้เฉยๆ!",
  ui_story_1020_10200801_76_dialog_content = "คุณชอบมันแบบนั้นรึเปล่า... ฮ่าฮ่า...",
  ui_story_1020_10200801_77_dialog_content = "<color=#e8d9bb>ปี๊บ—ปี๊บ—ปี๊บ—</color>",
  ui_story_1020_10200801_78_dialog_content = "บอกเราวิธีการปิดคลังสินค้านะ ยูลิสซิส!",
  ui_story_1020_10200801_79_dialog_content = "ตอบมา!",
  ui_story_1020_10200801_80_dialog_content = "สิ่งนี้ไม่เกี่ยวข้องกับคุณ พวกเขาไม่ใช่ศัตรูของคุณ! คุณสามารถออกไปได้...",
  ui_story_1020_10200801_81_dialog_content = "เลิกพูดไร้สาระของคุณได้แล้ว!",
  ui_story_1020_10200801_82_dialog_content = "บูล, คุณหาทางเข้าอื่นได้หรือยัง? คุณต้องรีบขึ้นนะ!",
  ui_story_1020_10200801_83_dialog_content = "บู, บู, บู!",
  ui_story_1020_10200801_X83_dialog_content = "มาสิ, เร็วขึ้นนิดเดียวก็พอ!",
  ui_story_1020_10200801_84_dialog_content = "<color=#e8d9bb>ปัง—ปัง—ปัง—</color>",
  ui_story_1020_10200801_85_dialog_content = "รัว—",
  ui_story_1020_10200801_86_dialog_content = "ดร.อัลกอล!",
  ui_story_1020_10200801_87_dialog_content = "...",
  ui_story_1020_10200801_88_dialog_content = "ดร.อัลกอลยังคงปฏิเสธที่จะออกไป...",
  ui_story_1020_10200801_89_dialog_content = "ฉันจะใช้พลังของฉันมาช่วยคุณ Algol!",
  ui_story_1020_10200801_90_dialog_content = "ไม่! พวกคุณทุกคนออกจากที่นี่เถอะ!",
  ui_story_1020_10200801_91_dialog_content = "ฉันได้ค้นพบวิธีในการควบคุมทหารพลังเหนือมนุษย์แล้ว...",
  ui_story_1020_10200801_92_dialog_content = "บู, บู, บู!",
  ui_story_1020_10200801_93_dialog_content = "ดีเลย ฐานข้อมูลได้รับการอัปเดตแล้ว! ตอนนี้ฉันแค่ต้องเข้าถึงมัน...",
  ui_story_1020_10200801_94_dialog_content = "เอาล่ะ... เร็วขึ้นนิดนึงสิ!",
  ui_story_1020_10200801_95_dialog_content = "บู! บู! บู!",
  ui_story_1020_10200801_96_dialog_content = "หลบ, อัลกอล!",
  ui_story_1020_10200801_97_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_1020_10200801_98_dialog_content = "บู?",
  ui_story_1020_10200801_99_dialog_content = "รัว—",
  ui_story_1020_10200801_100_dialog_content = "เกิดอะไรขึ้น? ทหารเหล่าซูเปอร์ซอลเจอร์ไม่ทำร้าย Algol เลยเหรอ!",
  ui_story_1020_10200801_101_dialog_content = "...",
  ui_story_1020_10200801_102_dialog_content = "<color=#e8d9bb>ปัง! ปัง! ปัง!</color>",
  ui_story_1020_10200801_103_dialog_content = "พวกเขากำลังโจมตี...ต้นแบบเหรอ?",
  ui_story_1020_10200801_104_dialog_content = "นี่เป็นเหตุผลที่ยูลิสซิสสร้างทหารเหนือมนุษย์หรือไม่?",
  ui_story_1020_10200801_105_dialog_content = "ฮ่าฮ่าฮ่าฮ่าฮ่าฮ่าฮ่าฮ่า, คุณชอบมันใช่ไหม?",
  ui_story_1020_10200801_106_dialog_content = "รู้สึกยังไงบ้าง? อิคลิพไซท์ของคุณอยู่ที่ไหนตอนนี้?",
  ui_story_1020_10200801_107_dialog_content = "<color=#e8d9bb>บัซ—บัซ—</color>",
  ui_story_1020_10200801_108_dialog_content = "... บู, บู...",
  ui_story_1020_10200801_109_dialog_content = "\"ขอบคุณ\"",
  ui_story_1020_10200801_110_dialog_content = "... ขอบคุณเหรอ?",
  ui_story_1020_10200801_111_dialog_content = "...",
  ui_story_1020_10200801_112_dialog_content = "โฮก...",
  ui_story_1020_10200801_113_dialog_content = "ซูเปอร์ทหาร... พวกเขาหยุดขยับแล้ว.",
  ui_story_1020_10200801_114_dialog_content = "พวกเขากำลังหาอะไรอยู่เหรอ?",
  ui_story_1020_10200801_115_dialog_content = "<color=#e8d9bb>ซ่า—ซ่า—</color>",
  ui_story_1020_10200801_116_dialog_content = "สายไฟกำลังยุ่งเหยิงอีกแล้วนะ ดร. อัลกอล!",
  ui_story_1020_10200801_117_dialog_content = "ไม่ต้องห่วงนะ ฉันจะยกเลิกคำสั่งซื้อของพวกเขา...",
  ui_story_1020_10200801_118_dialog_content = "<color=#e8d9bb>ปี๊บ—ปี๊บ—ปี๊บ—</color>",
  ui_story_1020_10200801_119_dialog_content = "คุณล้อเล่นฉันหรือ? โอ๊ยยย! เกลียดอย่างนี้เลย!",
  ui_story_1020_10200801_120_dialog_content = "เธอกำลังทำอะไรน่ะ",
  ui_story_1020_10200801_121_dialog_content = "<color=#e8d9bb>ซ่า—ซ่า—</color>",
  ui_story_1020_10200801_122_dialog_content = "ดูที่สิ่งที่อยู่เบื้องหลังทหารเหล่าซูเปอร์!",
  ui_story_1020_10200801_123_dialog_content = "โฮกกกก!",
  ui_story_1020_10200801_124_dialog_content = "เขาเริ่มโจมตีแล้ว!",
  ui_story_1020_10200801_125_dialog_content = "คุณกำลังทำอะไรกับลูกของฉัน?",
  ui_story_1020_10200801_126_dialog_content = "โฮกกกก!",
  ui_story_1020_10200801_127_dialog_content = "ระวัง อัลกอล!",
  ui_story_1020_10200901_1_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10200901_2_dialog_content = "ผู้บัญชาการบาร์ตัน พวกเราได้ทำหมดที่สุดแล้ว!",
  ui_story_1020_10200901_3_dialog_content = "แต่พวกเราที่<color=#FFB400>ประตู 10</color> ยังคงต้องต่อสู้อยู่และต้องการความช่วยเหลืออย่างเร่งด่วน!",
  ui_story_1020_10200901_4_dialog_content = "ดังนั้นคุณทั้งหมดที่เป็นผู้นำก็จะปล่อยให้คนอื่นได้โอกาสนี้ไปสู้หรือ?",
  ui_story_1020_10200901_5_dialog_content = "ไม่, ผู้บัญชาการ! ประตูสั่นสะเทือนอย่างรุนแรงเกินกว่าที่ร่างกายเราจะทนได้...",
  ui_story_1020_10200901_6_dialog_content = "ประตูที่ 10... นั่นไม่ใช่ทางไปสนามบริการหรือเปล่า?",
  ui_story_1020_10200901_7_dialog_content = "เด็กคนนั้นกำลังพยายามเอาเกียรติคุณหาความสนใจโดยให้โซรอซช่วยยกประตูหรือเปล่า?",
  ui_story_1020_10200901_8_dialog_content = "โคลอสซัสสามารถสนับสนุนประตูได้หรือไม่?",
  ui_story_1020_10200901_9_dialog_content = "ทำไมมันไม่สามารถทำได้เมื่อมันสามารถเพาะเลี้ยง Caelestite ได้?",
  ui_story_1020_10200901_10_dialog_content = "ตามฉันมา! ไม่มีใครบอกฉันว่าร่างกายนี้แย่กว่ากองขยะ!",
  ui_story_1020_10200901_11_dialog_content = "ผู้บัญชาการ! ที่<color=#FFB400>ประตู 9</color>ก็สั่นสะเทือนอย่างรุนแรงเช่นกัน มันเหมือนกับมีกระแสอากาศแรงกำลังพุ่งขึ้นไปที่ชั้นบนจากใต้ดิน!",
  ui_story_1020_10200901_12_dialog_content = "ใต้ดินหรือ? ตรวจสอบท่อระบายลมทั้งหมดเดี๋ยวนี้! ทุกมุมและทุกนิ้ว!",
  ui_story_1020_10200901_13_dialog_content = "เราได้ตรวจสอบทุกอย่างแล้ว! ไม่พบร่องรอยของอิคลิพไซท์!",
  ui_story_1020_10200901_14_dialog_content = "นี่มันเกิดอะไรขึ้น?",
  ui_story_1020_10200901_15_dialog_content = "<color=#e8d9bb>รอบๆ ประตูที่ 9</color>",
  ui_story_1020_10200901_16_dialog_content = "เจ้าหน้าที่ พื้นที่นี้สั่นสะเทือนอย่างรุนแรง กรุณาอพยพไปยังที่ปลอดภัย!",
  ui_story_1020_10200901_17_dialog_content = "ไม่ต้องสนใจฉัน ท่อลำเลียงด้านล่างกำลังทำงานอยู่ และฉันมาวัดระดับการสั่นสะเทือนที่นี่",
  ui_story_1020_10200901_18_dialog_content = "ปล่องทางขนส่ง...",
  ui_story_1020_10200901_19_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10200901_20_dialog_content = "ยอมรับได้ ไม่เป็นอันตรายต่อประตูมากนัก",
  ui_story_1020_10200901_21_dialog_content = "...",
  ui_story_1020_10200901_22_dialog_content = "<color=#e8d9bb>อุษาวิทยาลัยดอว์นแห่งลูโมโพลิส</color>",
  ui_story_1020_10200901_23_dialog_content = "ขอเทิดทูนรัตติกาลสีขาว! คุณได้ยินรึยัง? มีเรื่องแปลกๆเกิดขึ้นกับ<color=#FFB400>หินรัตติกาลสีขาว</color>ของโรงเรียน และลูมินาได้สั่นสะเทือนอย่างรุนแรงเป็นเวลานาน.",
  ui_story_1020_10200901_24_dialog_content = "พ่อและแม่ชีทั้งหมดวิ่งมา แต่ไม่สามารถบรรเทาความผันผวนได้ แม้จะใช้ลูมินาติกส์ด้วยพลังทั้งหมดของพวกเขา!",
  ui_story_1020_10200901_25_dialog_content = "นี่เกี่ยวข้องกับการสั่นสะเทือนที่ทำให้ลูโมโพลิสสะเทือนไปก่อนหน้านี้หรือไม่?",
  ui_story_1020_10200901_26_dialog_content = "ใช่ ฉันกลัวว่าซากโบราณได้เริ่มสัมผัสกับพลังงานลึกลับอีกครั้ง",
  ui_story_1020_10200901_27_dialog_content = "เรื่องนี้เกิดขึ้นมาก่อนเมื่อมีการระบาดของออโรร่าที่ Twilight ในอดีต แต่ครั้งนี้สถานการณ์ดูรุนแรงขึ้น",
  ui_story_1020_10200901_28_dialog_content = "<color=#e8d9bb>ลูโมโปลิสราชสำนัก</color>",
  ui_story_1020_10200901_29_dialog_content = "ดูสิ, ท่อเหล่านั้นกำลังเปิดอย่างกับปากหิวโหยที่พื้นดิน อิลลูมินาถูกทำให้เหมือนหมาป่าหิวโหย!",
  ui_story_1020_10200901_30_dialog_content = "หมาป่ายังไม่ได้กัดลูโมโพลิสเลย",
  ui_story_1020_10200901_31_dialog_content = "ยกเลิกการเตือนภัย กัปตันครับ ซากปรักหักพังนั้นปลอดภัยแล้วในทางปฏิบัติ",
  ui_story_1020_10200901_32_dialog_content = "ใช่เจ้านายของฉัน",
  ui_story_1020_10200901_33_dialog_content = "เจ้าเมืองครับ ศิลาที่มีลูมินาอยู่ในวิทยาลัยดอว์นได้ตอบสนองอย่างรุนแรงต่อการสั่นสะเทือน คุณคิดว่ามีพลังงานที่ไม่รู้จักอยู่ในลูโมโพลิสหรือไม่?",
  ui_story_1020_10200901_34_dialog_content = "ขอเทิดทูนรัตติกาลสีขาว ท่านเจ้าหญิง คุณไม่จำเป็นต้องกังวลเรื่องนี้",
  ui_story_1020_10200901_35_dialog_content = "แม้ว่าสิ่งนี้จะไม่เคยเกิดขึ้นตั้งแต่ท่านหญิง Saintess เข้าสู่วัดลูโมโพลิส แต่เทพแห่งแสงสว่างจะนำทางเรา",
  ui_story_1020_10200901_36_dialog_content = "คุณคิดว่าอะไรที่ทำให้หินรัตติกาลสีขาวมีปฏิกิริยาขึ้นเหรอคะ พ่อ?",
  ui_story_1020_10200901_37_dialog_content = "มีบางสิ่งที่เกี่ยวข้องถูกบันทึกไว้ในตำรา มันกล่าวว่าลูมินาจะเริ่มสั่นสะเทือนอย่างรุนแรงเมื่อมี<color=#FFB400>ผู้สืบสันดานวิญญาณ</color>ใหม่ปรากฏขึ้น",
  ui_story_1020_10200901_38_dialog_content = "...",
  ui_story_1020_10200901_39_dialog_content = "กำลังชั่วร้ายที่ซ่อนอยู่ในซากปรัมปราที่อยู่ใต้ดินเคยสั่นทั้งอะซูไรท์ มันคือผู้สืบสันดานของวิญญาณ - นักบุญหญิง - ที่ได้ขับไล่มันออกไป",
  ui_story_1020_10200901_40_dialog_content = "ตามที่ฉันนับได้ นางซานเทสได้ปกป้องแอชูไรต์มาหลายปีแล้ว",
  ui_story_1020_10200901_41_dialog_content = "ความชั่วร้ายสามารถไล่ไปได้เท่านั้น แต่ไม่สามารถขับไล่ออกไปได้ ลูโมโพลิสไม่ใช่สิ่งที่บริสุทธิ์",
  ui_story_1020_10200901_42_dialog_content = "ลูโมโพลิสจะอยู่ในอันตรายหรือไม่ พ่อ?",
  ui_story_1020_10200901_43_dialog_content = "ไม่นี่",
  ui_story_1020_10200901_44_dialog_content = "เรื่องสหพันธรัฐอิลลูมินาล่ะครับ?",
  ui_story_1020_10200901_45_dialog_content = "ขั้นแรก พวกเขาต้องหาศรัทธาของตัวเอง",
  ui_story_1020_10200901_46_dialog_content = "ระวังดูข้อความจากอิลลูมินานะครับ กัปตัน",
  ui_story_1020_10200901_47_dialog_content = "ใช่ ท่านชวาตส์",
  ui_story_1020_10200901_48_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10200901_49_dialog_content = "สถานการณ์ปัจจุบันเป็นอย่างไรบ้าง ดร.อัลกอล?",
  ui_story_1020_10200901_50_dialog_content = "แผงควบคุมกำลังแสดงว่าแกนกลางใกล้เสร็จแล้ว",
  ui_story_1020_10200901_51_dialog_content = "ฉันไม่เชื่อว่าวิศวกรยังไม่ได้โจมตีเรา... อยู่ทนไว้นะ Bool!",
  ui_story_1020_10200901_52_dialog_content = "บู! บู! บู!",
  ui_story_1020_10200901_53_dialog_content = "ว่าไง",
  ui_story_1020_10200901_54_dialog_content = "<color=#e8d9bb>บัซ—บัซ—</color>",
  ui_story_1020_10200901_55_dialog_content = "... บู, บู...",
  ui_story_1020_10200901_56_dialog_content = "\"กลับบ้านเถอะ, เคเลสไทต์\"",
  ui_story_1020_10200901_57_dialog_content = "เคเลสไทต์ไม่ไปไหนเลย!",
  ui_story_1020_10200901_58_dialog_content = "...",
  ui_story_1020_10200901_59_dialog_content = "วิศวกรไม่ได้คุยกับ Ulysses เหรอ? เขารู้เรื่อง PlayerName ได้ยังไงน่ะ?",
  ui_story_1020_10200901_60_dialog_content = "กลับบ้านมาเถอะ, เคเลสไทต์",
  ui_story_1020_10200901_61_dialog_content = "ฉันคิดว่าฉันได้ยินเสียงของเขา...",
  ui_story_1020_10200901_62_dialog_content = "มันมาจากที่ไหนกันนะ?",
  ui_story_1020_10200901_63_dialog_content = "จากภายในหัวของฉัน...",
  ui_story_1020_10200901_64_dialog_content = "ดังนั้นภาพที่ฉันเห็นนั้นจริง ๆ แล้วก็เกิดจากพลังจิต...",
  ui_story_1020_10200901_65_dialog_content = "กลับบ้านมาเถอะ, เคเลสไทต์",
  ui_story_1020_10200901_66_dialog_content = "... คุณคือใคร?",
  ui_story_1020_10200901_67_dialog_content = "คุณๆเรียกฉันว่าวิศวกร",
  ui_story_1020_10200901_68_dialog_content = "เธอคืออิคลิพไซท์... และเธอกำลังควบคุมทหารเหนือมนุษย์ของอิลลูมินาผ่านเครื่องจักรนี้ตามคำสั่งของอิคลิพส์ ใช่ไหม?",
  ui_story_1020_10200901_69_dialog_content = "ไม่นี่",
  ui_story_1020_10200901_70_dialog_content = "... แต่คุณได้ขโมยหัวใจสำคัญของการ์เดี้ยนวัน ซึ่งทำให้อิคลิพไซท์สามารถบุกเข้ามาในเมือง Gannon City.",
  ui_story_1020_10200901_71_dialog_content = "นั่นเป็นของฉันตั้งแต่แรกแล้ว",
  ui_story_1020_10200901_72_dialog_content = "เช่นเดียวกับคุณ",
  ui_story_1020_10200901_73_dialog_content = "... ฉันเป็น Caelestite ฉันเกิดที่ Eraveil.",
  ui_story_1020_10200901_74_dialog_content = "เคเลสไทต์มาจากที่ไหน?",
  ui_story_1020_10200901_75_dialog_content = "เธอทำอะไรกับผู้คนของฉัน... กับฉันเนี่ย?",
  ui_story_1020_10200901_76_dialog_content = "กลับบ้านมาเถอะ, เคเลสไทต์",
  ui_story_1020_10200901_77_dialog_content = "มาร่วมกันสืบสานภารกิจที่สูงส่งนี้กับฉันเถอะ",
  ui_story_1020_10200901_78_dialog_content = "เหตุผลที่สูงส่ง? เคเลสไทต์ไม่ไปไหนเลย!",
  ui_story_1020_10200901_79_dialog_content = "คุณกำลังพูดอะไรอยู่ ยูลิสซิส?",
  ui_story_1020_10200901_80_dialog_content = "...",
  ui_story_1020_10200901_81_dialog_content = "เขาสามารถเชื่อมโยงจิตกับคุณได้หรือเปล่า?",
  ui_story_1020_10200901_82_dialog_content = "เขากับคุณไม่เหมือนกัน",
  ui_story_1020_10200901_83_dialog_content = "ฉันจะบอกคุณความจริงทั้งหมดที่คุณอยากจะรู้อย่างยิ่ง",
  ui_story_1020_10200901_84_dialog_content = "เกี่ยวกับการต่อสู้ใน Dark Zone ในอดีต ระดับการจอด Colossi บ้านของ Caelestite...",
  ui_story_1020_10200901_85_dialog_content = "และสหายร่วมอุดมการณ์ที่คุณปรารถนามานาน",
  ui_story_1020_10200901_86_dialog_content = "!",
  ui_story_1020_10200901_87_dialog_content = "<color=#e8d9bb>บี๊บ—บี๊บ บี๊บ—บี๊บ บี๊บ บี๊บ—</color>",
  ui_story_1020_10200901_88_dialog_content = "วงกลมข้อมือของ Algol รายงานภัยคุกคาม.",
  ui_story_1020_10200901_89_dialog_content = "สนามบริการอิลลูมินา...",
  ui_story_1020_10200901_90_dialog_content = "PlayerName ยานโคลอสซัสกำลังตัดการเชื่อมต่อกับเทอร์มินัลของฉัน!",
  ui_story_1020_10200901_91_dialog_content = "โซรอซ...",
  ui_story_1020_10200901_92_dialog_content = "นี่เป็นฝีมือของคุณหรือ?",
  ui_story_1020_10200901_93_dialog_content = "ฉันได้เปิดใช้งานโคลอสซัสให้คุณแล้ว",
  ui_story_1020_10200901_94_dialog_content = "ไม่... ไม่!",
  ui_story_1020_10200901_95_dialog_content = "<color=#e8d9bb>ตุ้บ—</color>",
  ui_story_1020_10200901_96_dialog_content = "PlayerName!",
  ui_story_1020_10200901_97_dialog_content = "โอ้! เขาไปแล้ว",
  ui_story_1020_10200901_98_dialog_content = "ตามมาด่วน วิเวียน ตอนนี้มันอันตรายอยู่นอกนั้น",
  ui_story_1020_10200901_99_dialog_content = "เข้าใจแล้ว!",
  ui_story_1020_10200901_100_dialog_content = "เคเลสไทต์ไม่ไปไหนหรอก! ฉันคือเป้าหมายของเธอ...",
  ui_story_1020_10200901_101_dialog_content = "หยุดเรื่องไร้สาระนี้ทันที ยูลิสซิส!",
  ui_story_1020_10200901_102_dialog_content = "ปล่อยฉันนะ! ให้ฉันจัดการกับเขาเอง!",
  ui_story_1020_10200901_103_dialog_content = "<color=#e8d9bb>คลิก, คลิก—</color>",
  ui_story_1020_10200901_104_dialog_content = "บู! บู! บู!",
  ui_story_1020_10200901_105_dialog_content = "หยุดนะ, ยูลิสซิส!",
  ui_story_1020_10200901_106_dialog_content = "โฮกก!",
  ui_story_1020_10200901_107_dialog_content = "หลังจากหลายปีที่ผ่านมา... ฉันทำสำเร็จ...",
  ui_story_1020_10200901_108_dialog_content = "เหล่านี้พอหรือไม่?",
  ui_story_1020_10200901_109_dialog_content = "มีอีก! พัน ๆ คน! ทหารเหล่าซูเปอร์ที่แข็งแกร่งกว่าอิคลิพไซท์ถึงพันเท่า!",
  ui_story_1020_10200901_110_dialog_content = "<color=#e8d9bb>บัซ—บัซ—</color>",
  ui_story_1020_10200901_111_dialog_content = "... บู, บู...",
  ui_story_1020_10200901_112_dialog_content = "\"ครั้งสุดท้าย\"",
  ui_story_1020_10200901_113_dialog_content = "โอ้ไม่ คุณกำลังจะสั่งให้ทหารเหล่าซูเปอร์โจมตี! เราต้องควบคุมยูลิสซิสได้!",
  ui_story_1020_10200901_114_dialog_content = "ทิ้งยูลิสซิสให้ฉันจัดการ!",
  ui_story_1020_10200901_115_dialog_content = "<color=#e8d9bb>ปี๊บ—ปี๊บ—ปี๊บ—</color>",
  ui_story_1020_10200901_116_dialog_content = "อ๊าก! การสร้างโมดูลป้องกันอีกตัวนี่เป็นเรื่องที่น่ารำคาญชะมัด!",
  ui_story_1020_10200901_117_dialog_content = "โฮกก!",
  ui_story_1020_10201001_1_dialog_content = "PlayerName!",
  ui_story_1020_10201001_2_dialog_content = "เรายังต้องเดินทางไปอีกหลายทางจากที่นี่ถึงสนามบริการ ที่นอกนั้นอันตรายเกินไป!",
  ui_story_1020_10201001_3_dialog_content = "...ฉันจะไม่ให้โซรอซหนีไป!",
  ui_story_1020_10201001_4_dialog_content = "โซรอซจะออกไปได้ยังไงถ้าไม่มีคำสั่งจากคุณ?",
  ui_story_1020_10201001_5_dialog_content = "...",
  ui_story_1020_10201001_6_dialog_content = "ฉันเห็นมัน...",
  ui_story_1020_10201001_7_dialog_content = "ว่าไง",
  ui_story_1020_10201001_8_dialog_content = "ฉันเห็นสิ่งที่ยูลิสซีสเคยเห็นมาก่อน...",
  ui_story_1020_10201001_9_dialog_content = "มีเสียง... วิศวกรกำลังบอกฉันและโซรอซว่าควรกลับบ้าน...",
  ui_story_1020_10201001_10_dialog_content = "PlayerName...",
  ui_story_1020_10201001_11_dialog_content = "ไม่ใช่เรื่องง่ายสำหรับฉันที่จะพบโซรอซอีกครั้ง และเราได้พบกันเพียงไม่กี่วัน...",
  ui_story_1020_10201001_12_dialog_content = "ฉันสาบาน...ฉันสาบานว่าฉันจะไม่ปล่อยให้สิ่งนี้เกิดขึ้น!",
  ui_story_1020_10201001_13_dialog_content = "แต่ฉันจะทำอะไรได้? ต้องมีอะไรที่ฉันสามารถทำได้...",
  ui_story_1020_10201001_14_option_content = "ลิงค์โทรจิต",
  ui_story_1020_10201001_15_dialog_content = "...",
  ui_story_1020_10201001_16_option_content = "ลิงค์โทรจิต",
  ui_story_1020_10201001_17_dialog_content = "...",
  ui_story_1020_10201001_18_dialog_content = "โซรอซ... หายไปแล้วหรือ?",
  ui_story_1020_10201001_19_dialog_content = "ในขณะที่ฉันเดินออกจากห้องปฏิบัติการเมื่อวันนี้ ฉันรู้สึกถึงบางอย่างที่ไม่สามารถอธิบายได้",
  ui_story_1020_10201001_20_dialog_content = "ฉันเห็นแสงสว่างลอยอยู่เหนือโครงสร้างใหญ่โต พร้อมกับความหวังทั้งหมดของฉัน...",
  ui_story_1020_10201001_21_dialog_content = "และด้วยเหตุผลบางอย่าง ฉันรู้สึกว่าโซรอซจะบินขึ้นจากที่นั่น...",
  ui_story_1020_10201001_22_dialog_content = "ฉัน... ฉันไม่รู้ว่าทำไมฉันถึงรู้สึกแบบนั้นในตอนนั้น...",
  ui_story_1020_10201001_23_dialog_content = "หลังจากนั้นและความฝันที่ฉันเห็น ฉันควรจะคิดออกเร็วกว่านี้...",
  ui_story_1020_10201001_24_option_content = "ลิงค์โทรจิต",
  ui_story_1020_10201001_25_dialog_content = "...",
  ui_story_1020_10201001_26_option_content = "ลิงค์โทรจิต",
  ui_story_1020_10201001_27_dialog_content = "...",
  ui_story_1020_10201001_28_option_content = "ลิงค์โทรจิต",
  ui_story_1020_10201001_29_dialog_content = "...",
  ui_story_1020_10201001_30_dialog_content = "อ๊าก!",
  ui_story_1020_10201001_31_dialog_content = "หยุดเดี๋ยวนี้ PlayerName!",
  ui_story_1020_10201001_32_dialog_content = "คุณใช้พลังจิตของคุณมากเกินไปในวันนี้แล้ว และคุณดูป่วย!",
  ui_story_1020_10201001_33_dialog_content = "ฉันสูญเสียการติดต่อกับ Vice ไปแล้ว... ฉันไม่รู้ว่าฉันจะทำอย่างไรถ้าฉันสูญเสีย Soroz อีก...",
  ui_story_1020_10201001_34_dialog_content = "... โซรอซจะไปที่ไหน? วิศวกรต้องการอะไรกับมัน?",
  ui_story_1020_10201001_35_dialog_content = "คุณสามารถถามฉันคำถามเหล่านั้นได้เสมอ—",
  ui_story_1020_10201001_36_dialog_content = "ชักดาบ!",
  ui_story_1020_10201001_37_dialog_content = "คุณวิเวียน!",
  ui_story_1020_10201001_38_dialog_content = "... ฟิเจอรัลด์?",
  ui_story_1020_10201001_39_dialog_content = "อ่อนแอเกินไป—ไม่—น่าจะว่าอ่อนโยนเกินไป, ฉันคิดว่า...",
  ui_story_1020_10201001_40_dialog_content = "น่าสงสารจริง ๆ ที่คุณนุ่มนวลขนาดนี้!",
  ui_story_1020_10201001_41_dialog_content = "หึหึ ไม่มีอะไรเทียบเท่ากับรสชาติของความสิ้นหวังเมื่อคนหนึ่งสูญเสียสิ่งที่เขารักเรียบร้อย",
  ui_story_1020_10201001_42_dialog_content = "...คุณรู้ว่าโซรอซจะบินหนีไปหรือ?",
  ui_story_1020_10201001_43_dialog_content = "เอาล่ะ ทำไมคุณไม่ถามฉันว่าฉันทำอะไรกับโซรอซล่ะ?",
  ui_story_1020_10201001_44_dialog_content = "แก!",
  ui_story_1020_10201001_45_dialog_content = "รอสักครู่, PlayerName, มีบางอย่างไม่ถูกต้องกับเขา",
  ui_story_1020_10201001_46_dialog_content = "เขาถูกกักขังในห้องคุม แต่ยังสามารถหนีออกมาได้...",
  ui_story_1020_10201001_47_dialog_content = "ยังไม่เชื่อเหรอ? พลังของเขาทำให้ทุกอย่างนี้เป็นไปได้.",
  ui_story_1020_10201001_48_dialog_content = "โซ่พวกนั้นผูกมัดฉันจริง แต่ฉันสอนสัตว์เดรัจฉานที่จำกัดฉันให้เห็นความงดงามของความสิ้นหวังในช่วงสุดท้ายของพวกมัน",
  ui_story_1020_10201001_49_dialog_content = "แต่เสียดายที่รสทานของความทุกข์ทรมานของพวกเขายังไม่เทียบเท่ากับความทุกข์ทรมานของชาวเคเลสไทต์เลย.",
  ui_story_1020_10201001_50_dialog_content = "ฮ่าฮ่าฮ่า ตอนนี้เลือกสิ เคเลสไทต์! คุณจะตายอย่างไร้สาระเหมือนเพื่อนร่วมทีมที่ไร้ประโยชน์ของคุณหรือเปล่า?",
  ui_story_1020_10201001_51_dialog_content = "หรือคุณจะกลายเป็นของขวัญของฉันสำหรับผู้ครองสูงสุดและเป็นพยานความยิ่งใหญ่ของเขาที่ด้านข้างฉันหรือไม่?",
  ui_story_1020_10201001_52_dialog_content = "เคเลสไทต์จะไม่เคยตายอย่างไร้สาระ! ตอนนี้วิศวกรอยู่ที่ไหน?",
  ui_story_1020_10201001_53_dialog_content = "ฮ่าฮ่าฮ่า! ดูเหมือนว่าคุณเลือกอย่างหลังนะ!",
  ui_story_1020_10201001_54_dialog_content = "ถ้าเป็นแบบนั้น ก็ไม่มีความจำเป็นที่จะปรานีกับคนโง่ที่อยู่ข้างๆคุณเลย",
  ui_story_1020_10201001_55_dialog_content = "อย่ากล้าทำร้าย PlayerName!",
  ui_story_1020_10201001_56_dialog_content = "เจ้าต้องการที่จะสัมผัสพลังของความมืดของข้าหรือ? เจ้าควรรู้ว่า มันเกิดขึ้นจากเลือดของออโรเรียนที่ตกสู่ดิน",
  ui_story_1020_10201001_57_dialog_content = "หลบหลังฉันเร็ว PlayerName!",
  ui_story_1020_10201001_58_dialog_content = "การต่อต้านของคุณนั้นมันเหมือนกับการตลก...",
  ui_story_1020_10201001_59_dialog_content = "เป็นน้ำใจที่คุณยังรู้สึกความเจ็บปวดได้ ในเวลาที่เขาได้รับความสุข คุณจะได้รับการปลดปล่อยจากความทุกข์ทรมานของคุณ",
  ui_story_1020_10201001_60_dialog_content = "เรเวน—ฉันขอเสนอเลือดของ Caelestite ให้คุณ!",
  ui_story_1020_10201001_61_dialog_content = "ฉันจะไม่ปล่อยให้คุณทำร้าย PlayerName อิคลิพไซท์!",
  ui_story_1020_10201001_62_dialog_content = "ดีที่ฉันมาทันเวลาพอดี!",
  ui_story_1020_10201001_63_dialog_content = "PlayerName! หัวหน้าวิเวียน! คุณสองคนได้รับบาดเจ็บหรือไม่?",
  ui_story_1020_10201001_64_dialog_content = "ฌอน? ออกจากที่นี่เถอะ! พลังความมืดนั้นอันตรายมาก!",
  ui_story_1020_10201001_65_dialog_content = "ฉันรู้ แต่ฉันต้องปกป้องคุณ PlayerName!",
  ui_story_1020_10201001_66_dialog_content = "เอาล่ะ? ฉันไม่ได้ทำให้คุณผิดหวังใช่ไหม?",
  ui_story_1020_10201001_67_dialog_content = "ไม่ใช่เลย! ฌอน คุณสามารถทนทานการโจมตีของเขาได้ยังไง?",
  ui_story_1020_10201001_68_dialog_content = "ฮ่า! เพราะฉันเป็นนักสู้ที่ดีเท่ากับ Yingel หรือ Axelia!",
  ui_story_1020_10201001_69_dialog_content = "ฉันแค่เป็นออโรเรียนที่มีเนื้อและเลือดเหมือนกันนั่นแหละ",
  ui_story_1020_10201001_70_dialog_content = "ผู้บัญชาการ, PlayerName, ให้ฉันจัดการอิคลิพไซท์นี้เอง!",
  ui_story_1020_10201001_71_dialog_content = "ระวังนะ ฌอน! เขาเล่ห์เหลี่ยมมาก เราจะช่วยปกป้องคุณโดยการกำจัดอิคลิพไซท์ที่อยู่ข้างหลังคุณ!",
  ui_story_1020_10201001_72_dialog_content = "รับทราบ!",
  ui_story_1020_10201001_73_dialog_content = "อ๊ะ... นุ่มจัง! สดจัง!",
  ui_story_1020_10201101_1_dialog_content = "คุณพวกหนอน... จริง ๆ แล้วคิดว่าจะหยุดฉันได้เหรอ?",
  ui_story_1020_10201101_2_dialog_content = "ฉันต้องทำภารกิจให้สำเร็จในครั้งนี้ ไม่เช่นนั้น—",
  ui_story_1020_10201101_3_dialog_content = "คุณที่มีหูยาวขนนุ่ม... คุณจะสามารถรอดจากการโจมตีด้วยพลังความมืดของฉันได้โดยไม่ได้รับบาดเจ็บเลยอย่างไร?",
  ui_story_1020_10201101_4_dialog_content = "แล้วไง? ฉันจะไม่ปล่อยให้คุณทำร้ายเพื่อนของฉันเด็ดขาด!",
  ui_story_1020_10201101_5_dialog_content = "เฮ้ หน้าตาของเจ้าบอกทุกอย่าง... นั่นแหละเหตุผลที่เจ้ายังมีชีวิตอยู่หลังจากที่สัตว์ประเภทอื่น ๆ ถูกลบล้างทั้งหมด",
  ui_story_1020_10201101_6_dialog_content = "พูดอะไรของเธอน่ะ",
  ui_story_1020_10201101_7_dialog_content = "ฉัน ฟิเจอรัลด์ มีเกียรติที่ได้ร่วมมือในการกำจัดพันธุ์ของคุณอย่างมวลมหา มันเป็นการสนับสนุนที่ยิ่งใหญ่ที่สุดของฉันต่อผู้ปกครองสูงสุดของเรา",
  ui_story_1020_10201101_8_dialog_content = "อย่างไรก็ตาม ดูเหมือนว่าโดยการทำสันติภาพกับ Aurorians พวกคุณที่ขี้เกียจและทรยศได้พบทางเลือกในการอยู่รอด",
  ui_story_1020_10201101_9_dialog_content = "ในทางหนึ่ง คุณก็ไม่ต่างจากแมลงสาบเลย คุณไม่คิดเหมือนฉันหรือ?",
  ui_story_1020_10201101_10_dialog_content = "หุบปาก! ฉันจะไม่ยอมให้คุณพูดถึงฌอนในทางที่ไม่ดีแบบนั้น!",
  ui_story_1020_10201101_11_dialog_content = "โกรธหรือ? คุณอยากฆ่าฉันเดี๋ยวนี้ใช่มั้ย?",
  ui_story_1020_10201101_12_dialog_content = "แต่คุณยังอยากทราบว่าโซรอซไปที่ไหนใช่ไหม? ไม่ใช่แค่โซรอซเท่านั้น แต่ยังมีสาวอิลลูมินาที่ไม่มีค่าอยู่ด้วย",
  ui_story_1020_10201101_13_dialog_content = "ไม่ต้องกังวล ฉันมั่นใจว่าอานีโมเน่ได้ให้เธอความตายที่น่ากลัวอย่างงดงาม",
  ui_story_1020_10201101_14_dialog_content = "ไวซ์... เธอเจอกับอะเนโมน? บอกฉันว่าเธอเกิดอะไรขึ้น!",
  ui_story_1020_10201101_15_dialog_content = "โอ๊ะ? มาดูว่าฉันจำได้หรือเปล่า...",
  ui_story_1020_10201101_16_dialog_content = "วิศวกรอยู่ที่ไหน? โซรอซไปที่ไหน? บอกฉันสิ!",
  ui_story_1020_10201101_17_dialog_content = "...",
  ui_story_1020_10201101_18_dialog_content = "โอ้เจ้านายที่ยิ่งใหญ่และเหนือกว่า โปรดอย่าทอดทิ้งข้าพเจ้า!",
  ui_story_1020_10201101_19_dialog_content = "...",
  ui_story_1020_10201101_20_dialog_content = "\"เจ้านาย\"? เขากำลังพูดกับใครน่ะ?",
  ui_story_1020_10201101_21_dialog_content = "วิศวกรคงกำลังสื่อสารกับเขาผ่านความคิดของเขาในตอนนี้...",
  ui_story_1020_10201101_22_dialog_content = "นี่อาจจะเป็นเวลาที่ดีที่สุดในการหาเบาะแส",
  ui_story_1020_10201101_23_dialog_content = "นายทำอะไรอยู่น่ะ PlayerName?",
  ui_story_1020_10201101_24_option_content = "บูสต์พลัง",
  ui_story_1020_10201101_25_dialog_content = "(อ๊าก! ความเจ็บปวดนี้ไม่ทนได้...)",
  ui_story_1020_10201101_26_dialog_content = "(แต่ไม่มีทางอื่นแล้วน่ะ!)",
  ui_story_1020_10201101_27_dialog_content = "(ฉันต้องการทราบว่าเกิดอะไรขึ้นกับไวซ์และโซรอซ...)",
  ui_story_1020_10201101_28_dialog_content = "(ฉันต้องหาคำตอบ...)",
  ui_story_1020_10201101_29_dialog_content = "ร่างกายของคุณกลายเป็นอ่อนแอและน่าเกลียด",
  ui_story_1020_10201101_30_dialog_content = "มันไม่สำคัญสำหรับฉันเลย! ตราบใดที่ฉันยังคงมีเครื่องหมายของคุณ พวกออโรเรียนและอิคลิพไซท์ที่ต่ำต้อยนั้นจะต้องน้อมศีลให้ฉันทั้งหมด",
  ui_story_1020_10201101_31_dialog_content = "โค้งให้คุณ? แล้วฉันล่ะ?",
  ui_story_1020_10201101_32_dialog_content = "ข-ข้าสั่นไหวในความยิ่งใหญ่ของท่าน ท่านนาย! โปรดให้ข้าเป็นปีกของท่าน และข้าจะอุทิศชีวิตทั้งชีวิตให้แก่ท่าน!",
  ui_story_1020_10201101_33_dialog_content = "คุณยินยอมสวมแหวนนี้เพื่อรับรู้ฐานะใหม่ของคุณหรือไม่?",
  ui_story_1020_10201101_34_dialog_content = "แหวน...",
  ui_story_1020_10201101_35_dialog_content = "ฉันยินยอม! แหวนนี้เป็นสัญลักษณ์แห่งความกรุณาของคุณ ของขวัญที่เฉพาะหัวใจที่สูงส่งที่สุดเท่านั้นที่จะได้รับ! มันทำให้ชีวิตของฉันมีความหมาย!",
  ui_story_1020_10201101_36_dialog_content = "ฉันคุกเข่าขอบคุณท่าน, ผู้ครองสูงสุด!",
  ui_story_1020_10201101_37_dialog_content = "เอาละ",
  ui_story_1020_10201101_38_dialog_content = "ป-ประทานให้ฉัน... อ๊ากกกกกก!",
  ui_story_1020_10201101_39_dialog_content = "ฉัน... หัวของฉัน! ความเจ็บปวด... ฉันไม่สามารถทนได้อีกต่อไป! ผู้ครองสูงสุด... โปรดช่วยฉัน...",
  ui_story_1020_10201101_40_dialog_content = "(นี่เป็นความทรงจำของฟิเจอรัลด์จากอดีต และเสียงที่เพิ่งได้ยินนั้นเป็นของวิศวกร...)",
  ui_story_1020_10201101_41_dialog_content = "(ภูตผีจาก Eclipse สมัครใจสวมแหวนที่คล้ายกับกุญแจ...)\n\n",
  ui_story_1020_10201101_42_dialog_content = "(...)",
  ui_story_1020_10201101_43_dialog_content = "(ฉันไม่รู้เลยว่าฉันสามารถใช้พลังของฉันเพื่อมองเห็นไกลถึงอดีตแบบนี้... สิ่งนี้เกิดขึ้นเพราะฝันของวิศวกรหรือเปล่า?)",
  ui_story_1020_10201101_44_dialog_content = "(หรือเพราะ Algol ฝึกฉันให้สามารถเชื่อมต่อกับ Bool ได้สำเร็จหรือไม่?)",
  ui_story_1020_10201101_45_dialog_content = "(ถ้าฉันต้องการทราบเกี่ยวกับที่ตั้งของไวซ์และโซรอซ ฉันจะต้องเข้าถึงความทรงจำที่ใหม่ขึ้นของเขา...)",
  ui_story_1020_10201101_46_option_content = "การสื่อสารโทรจิต—",
  ui_story_1020_10201101_47_dialog_content = "(เอ่อ, พลังความมืดนี้... มันรู้สึกแย่เหมือนกับครั้งแรกที่ฉันเชื่อมต่อจิตใจกับ Bool.)",
  ui_story_1020_10201101_48_dialog_content = "(แต่ตอนนี้หลังจากที่ฉันได้ประสบประสบการณ์แบบนั้นแล้ว ฉันคิดว่าฉันสามารถรับมือกับสิ่งนี้ได้...)",
  ui_story_1020_10201101_49_dialog_content = "(หืม? นี่คือเขตแดนมืดหรือเปล่า?)",
  ui_story_1020_10201101_50_dialog_content = "(หลุมนี้กว้างมาก และรอยแตกดูเหมือนจะยืดไปไกลมากขึ้น...)",
  ui_story_1020_10201101_51_dialog_content = "(จะเป็นซากโบราณจากสงครามโบราณที่วิศวกรพูดถึงหรือไม่?)",
  ui_story_1020_10201101_52_dialog_content = "(เกิดอะไรขึ้นที่นี่เนี่ย? ทำไมที่นี่ถึ้งกลายเป็นสภาพแย่ๆ แบบนี้?)",
  ui_story_1020_10201101_53_dialog_content = "(ฉันไม่เห็นสัญญาณของโคลอสซัสที่อยู่ใกล้ ๆ ...)",
  ui_story_1020_10201101_54_option_content = "การสื่อสารโทรจิต—",
  ui_story_1020_10201101_55_dialog_content = "(นั่นคือ... กองซากของโคลอสซัสหรือ?)",
  ui_story_1020_10201101_56_dialog_content = "(หนึ่ง, สอง, สาม...)",
  ui_story_1020_10201101_57_dialog_content = "(...)",
  ui_story_1020_10201101_58_dialog_content = "(ที่จอดของโคลอสซัส...)",
  ui_story_1020_10201101_59_dialog_content = "(ชายหาดที่แห้งแล้งและเปล่าเปลี่ยว... มันแตกต่างจากหอคอยแห่งการหวนคืนมากเลย.)",
  ui_story_1020_10201101_60_dialog_content = "(พวกเขาเกิดอะไรขึ้น? ไม่มีอะไรเหลืออยู่เลยยกเว้นโครงสร้างที่สึกหักเหมือนกระดูกมังกร...)",
  ui_story_1020_10201101_61_dialog_content = "(นี่เกิดขึ้นนานแค่ไหนแล้ว? ฉันไม่รู้สึกสัญญาณของสิ่งมีชีวิตแม้แต่เล็กน้อยที่สุด...)",
  ui_story_1020_10201101_62_dialog_content = "(นั่นคือ, หลักของ Guardian One...)",
  ui_story_1020_10201101_63_dialog_content = "(อาจจะเป็นเพราะพิกัดที่ฉันเห็นในข้อมูลของโซรอซเป็นคำใบ้...)",
  ui_story_1020_10201101_64_dialog_content = "(พิกัด... หลักเรืองแสง...)",
  ui_story_1020_10201101_65_option_content = "การสื่อสารโทรจิต—",
  ui_story_1020_10201101_66_dialog_content = "(นี่แหละ!)",
  ui_story_1020_10201101_67_dialog_content = "(ไม่มีข้อผิดพลาด นี่เป็นสิ่งที่ฉันเห็นในความทรงจำของยูลิสซิสเป๊ะเลย...)",
  ui_story_1020_10201101_68_dialog_content = "(เสาเหล่านี้ที่ส่องสว่างคือหัวใจของ Guardian One ฉันสามารถมองเห็นพวกมันได้ชัดเจนแล้ว...)",
  ui_story_1020_10201101_69_dialog_content = "(หินกำลังลอยขึ้น ต้องมีอะไรบนนั้นแน่...)",
  ui_story_1020_10201101_70_dialog_content = "คุณเตรียมพร้อมหรือยัง",
  ui_story_1020_10201101_71_dialog_content = "ใช่. <color=#FFB400>Drive Ring</color> ตัวสุดท้ายอยู่ในมือแล้ว.",
  ui_story_1020_10201101_72_dialog_content = "เอาละ",
  ui_story_1020_10201101_73_dialog_content = "ฉันอ่านชื่อที่ท่านทรงเกียรติและหวังว่าท่านจะมองเห็น—",
  ui_story_1020_10201101_74_dialog_content = "เราขอรอคอยการมาถึงของคุณอย่างเคารพค่ะ—",
  ui_story_1020_10201101_75_dialog_content = "คุณเป็นใครน่ะ",
  ui_story_1020_10201101_76_dialog_content = "...",
  ui_story_1020_10201101_77_dialog_content = "สาวอิลลูมิน่าและนักวิทยาศาสตร์",
  ui_story_1020_10201101_78_dialog_content = "อิลลูมินาสินะ",
  ui_story_1020_10201101_79_dialog_content = "อีกาที่ไร้ประโยชน์นั้นก็อยู่ในอิลลูมินาเช่นกัน",
  ui_story_1020_10201101_80_dialog_content = "อิลลูมินา... ชื่อที่ฉันคิดถึงจังเลย",
  ui_story_1020_10201101_81_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_1020_10201101_82_dialog_content = "(ฉากเมื่อกี้... มันไม่ใช่ความฝันเลยนี่นา...)",
  ui_story_1020_10201101_83_dialog_content = "(แต่คราวนี้ ฟอร์เซคินอยู่ที่นี่แทน Vice...)",
  ui_story_1020_10201101_84_dialog_content = "(คนที่อยู่ข้างเธอ ... นั่นเป็นเจตภูตหรือ?)",
  ui_story_1020_10201101_85_dialog_content = "ค-คุณ... ผู้ปกครองสูงสุด!",
  ui_story_1020_10201101_86_dialog_content = "คนรับใช้ที่ภักดีของคุณ ฟิเจอรัลด์ ได้ยอมเข่าอยู่ที่นี่ตลอดเวลานี้ รอคอยการมาถึงของคุณ",
  ui_story_1020_10201101_87_dialog_content = "คุณยังไม่ได้บรรลุอะไรเลย",
  ui_story_1020_10201101_88_dialog_content = "ข้าได้รับใช้ท่านอย่างดี อาจารย์! ข้าคือผู้ที่นำการกำจัดสัตว์ประหลาดเหล่านั้น—",
  ui_story_1020_10201101_89_dialog_content = "เรื่องที่เกิดขึ้นหลายศตวรรษที่แล้วตอนนี้.",
  ui_story_1020_10201101_90_dialog_content = "ในขณะที่ฉันต้องการมัน ฉันจะเอาคืนสิ่งที่ฉันได้มอบให้คุณ",
  ui_story_1020_10201101_91_dialog_content = "นายท่าน... คุณจะไม่ทำเรื่องแบบนั้นใช่ไหม? ฉันเป็นปีกของคุณ ที่ถูกสร้างขึ้นด้วยมือของคุณเอง!",
  ui_story_1020_10201101_92_dialog_content = "ฉันจะปลดปล่อยคุณจากข้อจำกัดของคุณ",
  ui_story_1020_10201101_93_dialog_content = "พิสูจน์ความคุ้มค่าของคุณแก่ Eclipse โดยการนำ Caelestite มาให้ฉัน",
  ui_story_1020_10201101_94_dialog_content = "ฉันยังมีพลังงานเพียงพอที่จะเปิดใช้งานโคลอสซัส",
  ui_story_1020_10201101_95_dialog_content = "<color=#e8d9bb>ปึก—</color>",
  ui_story_1020_10201101_96_dialog_content = "...",
  ui_story_1020_10201101_97_dialog_content = "ฉ-ฉันสั่นกลัวต่อหน้าคุณ! ฉันจะไม่กล้าที่จะต่อต้านความปรารถนาของคุณเลย!",
  ui_story_1020_10201101_98_dialog_content = "(...)",
  ui_story_1020_10201101_99_dialog_content = "(วิศวกรมาที่เมืองแกนน่อนเพื่อเรียกวรรธน์กลับ...)",
  ui_story_1020_10201101_100_dialog_content = "(และเขาต้องการพาฉันและโซรอซไปด้วย...)",
  ui_story_1020_10201101_101_dialog_content = "คุณชอบมันไหม?",
  ui_story_1020_10201101_102_dialog_content = "เธอ... กำลังมองฉันเหรอ?",
  ui_story_1020_10201101_103_dialog_content = "เสมอ.",
  ui_story_1020_10201101_104_dialog_content = "ฉันได้ให้คุณเห็นภาพลวงตา คุณควรขอบคุณฉันที่แสดงให้คุณเห็นสิ่งที่น่าตื่นตาตื่นใจในสนามรบ Spire",
  ui_story_1020_10201101_105_dialog_content = "สนามรบหอคอย... สรุปแล้วมันเกิดขึ้นจริง ๆ เหรอ?",
  ui_story_1020_10201101_106_dialog_content = "เฉพาะ \"ความจริง\" เท่านั้นที่มีค่า",
  ui_story_1020_10201101_107_dialog_content = "รอยแยกนั้นเคยเป็นบ้านของฉัน แต่สงครามได้ทำให้ฉันพังทลาย",
  ui_story_1020_10201101_108_dialog_content = "ฉันค้นหาชิ้นส่วนเพื่อซ่อมแซมฐานของฉันให้กลับมาเหมือนเดิม แล้วจึงเริ่มต้นหัวใจของฉันใหม่",
  ui_story_1020_10201101_109_dialog_content = "โคลอสซัสเหล่านั้นได้ใช้พลังงานจากแกนของพวกมันเพื่อสนับสนุนฉัน",
  ui_story_1020_10201101_110_dialog_content = "... โซรอซจะกลายเป็นเหยื่อถังถัดไปของคุณหรือ? คุณกำลังพยายามทำลายโลกหรือ?",
  ui_story_1020_10201101_111_dialog_content = "ไม่ ฉันไม่ชอบหรอก",
  ui_story_1020_10201101_112_dialog_content = "เธอจะเข้าใจเองเถอะ คุณและฉันนั้นเหมือนกัน",
  ui_story_1020_10201101_113_dialog_content = "...",
  ui_story_1020_10201101_114_dialog_content = "... โซรอซอยู่ที่ไหน?",
  ui_story_1020_10201101_115_dialog_content = "...แล้วไวซ์เกิดอะไรขึ้น?",
  ui_story_1020_10201101_116_dialog_content = "...",
  ui_story_1020_10201101_117_dialog_content = "(... มันเริ่มมืดขึ้นและมืดขึ้น...)",
  ui_story_1020_10201101_118_dialog_content = "จำไว้นะ แสงสว่างจะทำให้คุณตาบอด คุณจะสามารถเห็นความจริงได้เฉพาะในความมืดเท่านั้นค่ะ",
  ui_story_1020_10201101_119_dialog_content = "ยอมรับความมืด เปิดใจรับมัน และให้มันเป็นแรงกำลังของคุณ",
  ui_story_1020_10201101_120_dialog_content = "ฉันปฏิเสธ!",
  ui_story_1020_10201101_121_dialog_content = "อนุญาตให้ความมืดเป็นแรงกำลังของคุณ",
  ui_story_1020_10201101_122_dialog_content = "ฉันจะไม่สวมโซ่ตรวนของคุณ!",
  ui_story_1020_10201101_123_dialog_content = "(ถ้าเป็นแบบนี้ ความมืดจริง ๆ จะกลืนกินฉัน...)",
  ui_story_1020_10201102_1_dialog_content = "<color=#e8d9bb>กระเซ็น—</color>",
  ui_story_1020_10201102_2_dialog_content = "(ฉันได้ยินเสียงเปียโนในความมืด...)",
  ui_story_1020_10201102_3_dialog_content = "(ที่นี่... มันสว่างจัง...)",
  ui_story_1020_10201102_4_dialog_content = "(แสงที่ไหลเวียนนี้ดูเหมือนว่าจะสะท้อนจากผิวน้ำของทะเลสาบ...)",
  ui_story_1020_10201102_5_dialog_content = "(นี่คือ... แสงออโรราที่นอร์ธแลนด์หรือ?)",
  ui_story_1020_10201102_6_dialog_content = "(หืม? เสียงอะไรน่ะ...)",
  ui_story_1020_10201102_7_dialog_content = "PlayerName",
  ui_story_1020_10201102_8_dialog_content = "โซรอซเหรอ? จริงๆแกเหรอ? โซรอซ!",
  ui_story_1020_10201102_9_dialog_content = "ฉันได้ยินเสียงเปียโนเมื่อครู่ แล้วก็เสียงของคุณ PlayerName",
  ui_story_1020_10201102_10_dialog_content = "เปียโนเหรอ? ฉันก็ได้ยินนะ! ฉันไม่ได้คาดหวังว่าจะได้พบคุณอย่างนี้!",
  ui_story_1020_10201102_11_dialog_content = "ตอนนี้คุณอยู่ที่ไหน โซรอซ?",
  ui_story_1020_10201102_12_dialog_content = "...",
  ui_story_1020_10201102_13_dialog_content = "ฉันไม่รู้",
  ui_story_1020_10201102_14_dialog_content = "...",
  ui_story_1020_10201102_15_dialog_content = "เขาสั่งให้คุณทำใช่มั้ย?",
  ui_story_1020_10201102_16_dialog_content = "...",
  ui_story_1020_10201102_17_dialog_content = "คุณสามารถไม่สนใจมันได้หรือเปล่า... โซรอซ?",
  ui_story_1020_10201102_18_dialog_content = "...",
  ui_story_1020_10201102_19_dialog_content = "ฉันขอโทษนะ PlayerName",
  ui_story_1020_10201102_20_dialog_content = "เคเลสไทต์ฝันถึงความเสรีทั้งชีวิต...",
  ui_story_1020_10201102_21_dialog_content = "ข้อมูลชั่วคราวที่มอบให้ฉันได้เห็นภาพของ Caelestites และ Colossi ก่อนที่ฉันจะพบคุณ...",
  ui_story_1020_10201102_22_dialog_content = "ฉันเห็นหลายรุ่นของ Caelestites และ Colossi ที่กำลังพยายามปลดปล่อยตัวเองออกจากโซ่ที่มัดมัน",
  ui_story_1020_10201102_23_dialog_content = "คราวนี้...",
  ui_story_1020_10201102_24_dialog_content = "ฉันคิดว่าฉันทำไม่สำเร็จ",
  ui_story_1020_10201102_25_dialog_content = "โซรอซ... กรุณาอย่าไป...",
  ui_story_1020_10201102_26_dialog_content = "เราสามารถปลดปล่อยตัวเราเองจากโซ่เหล่านี้ได้ด้วยกันใช่มั้ย?",
  ui_story_1020_10201102_27_dialog_content = "...",
  ui_story_1020_10201102_28_dialog_content = "ณ ตอนนี้ ฉันคือทั้งโซรอซและนาวิดุซ...",
  ui_story_1020_10201102_29_dialog_content = "รวมถึง Solituz, Probarduz, Vocoduz, Spanduz...",
  ui_story_1020_10201102_30_dialog_content = "สิ่งที่ฉันสามารถทำได้คือปกป้องผู้นำทางของฉันให้ดีที่สุดเท่าที่ฉันทำได้ เหมือนที่บรรพบุรุษของฉันเคยทำมา",
  ui_story_1020_10201102_31_dialog_content = "ในช่วงเวลาที่ฉันอยู่กับคุณ ทุกครั้งที่เราบินไปด้วยกันเป็นช่วงเวลาที่ยิ่งใหญ่ที่สุดในชีวิตของฉัน",
  ui_story_1020_10201102_32_dialog_content = "ถ้าฉันสามารถหักห่วงได้ เราจะได้พบกันอีกครั้ง",
  ui_story_1020_10201102_33_dialog_content = "โซรอซ...",
  ui_story_1020_10201102_34_dialog_content = "ไม่ว่าฉันจะได้รับสัญญาณมากมายเท่าใด...",
  ui_story_1020_10201102_35_dialog_content = "ตราบใดที่ฉันยังมี \"หัวใจ\" มันจะได้ยินเสียงของคุณเท่านั้น PlayerName",
  ui_story_1020_10201102_36_dialog_content = "...",
  ui_story_1020_10201102_37_dialog_content = "โซรอซ...",
  ui_story_1020_10201102_38_dialog_content = "โซรอซ?",
