  ui_story_1020_10201102_40_option_content = "ลิงค์โทรจิต",
  ui_story_1020_10201102_41_dialog_content = "...",
  ui_story_1020_10201102_42_option_content = "ลิงค์โทรจิต—",
  ui_story_1020_10201102_43_dialog_content = "...",
  ui_story_1020_10201102_44_option_content = "ลิงค์โทรจิต!",
  ui_story_1020_10201102_45_dialog_content = "...",
  ui_story_1020_10201102_46_option_content = "เชื่อมโยงทางโทรจิต!",
  ui_story_1020_10201102_47_dialog_content = "PlayerName!",
  ui_story_1020_10201102_48_dialog_content = "...",
  ui_story_1020_10201102_49_dialog_content = "ฉันทำไม่ได้...",
  ui_story_1020_10201102_50_dialog_content = "ฉันสัมผัสไม่ได้ถึงโซรอซแล้ว!",
  ui_story_1020_10201102_51_dialog_content = "ฟื้นซะทีนะ PlayerName สบายดีรึเปล่า?",
  ui_story_1020_10201102_52_dialog_content = "มันทำให้ฉันเจ็บปวดที่ต้องเห็นคุณอยู่ในสภาพนี้ PlayerName",
  ui_story_1020_10201102_53_dialog_content = "มันน่ากลัวเมื่อเห็นคุณพึมพำกับตัวเอง โชคดีที่ฌอนได้ทำให้ฟิเจอรัลด์สงบลง ทำให้คุณสามารถรู้สึกตัวเองได้อีกครั้ง!",
