  ui_story_1021_10210301_72_dialog_content = "คุณทำอะไรที่นี่? แล้วเกิดอะไรขึ้น?",
  ui_story_1021_10210301_73_dialog_content = "...",
  ui_story_1021_10210301_74_dialog_content = "(นั่นหมาจิ้งจอกหิมะตำนานหรือเปล่า? มันมองฉันเหมือนอยากให้ฉันออกไป.)",
  ui_story_1021_10210301_75_dialog_content = "เรามาเยี่ยมฝ่าบาท แต่เครื่องบินของเราเจอความเข้มข้นและถูกบังคับให้ลงจอดที่นี่",
  ui_story_1021_10210301_76_dialog_content = "...",
