  ui_story_1022_10220402_38_dialog_content = "...",
  ui_story_1022_10220402_39_dialog_content = "ถ้าคุณจริงจังเกลียดความหน้าซื่อใจคดเท่าที่คุณบอก แล้วแทนที่จะพูดเรื่องไร้สาระที่ก่อการกบฏนี้ทั้งหมด—",
